use super::*;
use crate::db::TestEntity;
use std::collections::HashMap;
use std::sync::OnceLock;
use tempfile::tempdir;

/// The five community-reader membership lists must agree.
///
/// They are deliberately not collapsed into one lookup — the gate SQL survived
/// four independent review rounds, and re-opening it to prevent a drift that
/// has not happened would buy speculative safety with real review risk. This is
/// the cheaper half of that trade: a consumer present in
/// `COMMUNITY_READER_CONSUMERS` but missing from the gate's own match would be
/// permanently dark and *silent*, because the gate fails closed by returning
/// `0=1`. Silence is the whole hazard, so it gets a test rather than a comment.
#[tokio::test]
async fn community_reader_consumer_lists_agree() {
    let (db, _dir) = test_db().await;

    for consumer in COMMUNITY_READER_CONSUMERS {
        assert_ne!(
            community_reader_durable_gate_sql(consumer),
            "0=1",
            "{consumer} is a listed consumer but the gate SQL fails it closed as unknown"
        );
        // `set_community_reader_cutover` rejects an unknown consumer, so a
        // successful call proves membership in `is_known_community_reader`
        // without making that private predicate public.
        db.set_community_reader_cutover(consumer, false)
            .await
            .unwrap_or_else(|error| panic!("{consumer} is not a known community reader: {error}"));
    }

    // The reverse direction, so the agreement above is not vacuously true of
    // every string that happens to be passed in.
    assert_eq!(
        community_reader_durable_gate_sql("not_a_consumer"),
        "0=1",
        "an unlisted consumer must fail closed"
    );
    assert!(
        db.set_community_reader_cutover("not_a_consumer", true)
            .await
            .is_err(),
        "an unlisted consumer must not be able to record cutover intent"
    );
}

pub(crate) mod community_grouping_test_hooks {
    use super::*;

    struct Pause {
        reached: Arc<tokio::sync::Notify>,
        resume: Arc<tokio::sync::Notify>,
    }

    static AFTER_MEMBER_DELETE: OnceLock<std::sync::Mutex<HashMap<String, Pause>>> =
        OnceLock::new();
    static AFTER_RUNTIME_TAKE: OnceLock<std::sync::Mutex<HashMap<String, Pause>>> = OnceLock::new();

    fn install_pause(
        pauses: &'static OnceLock<std::sync::Mutex<HashMap<String, Pause>>>,
        space: &str,
    ) -> (Arc<tokio::sync::Notify>, Arc<tokio::sync::Notify>) {
        let reached = Arc::new(tokio::sync::Notify::new());
        let resume = Arc::new(tokio::sync::Notify::new());
        pauses.get_or_init(Default::default).lock().unwrap().insert(
            space.to_owned(),
            Pause {
                reached: Arc::clone(&reached),
                resume: Arc::clone(&resume),
            },
        );
        (reached, resume)
    }

    pub(crate) fn pause_after_member_delete(
        space: &str,
    ) -> (Arc<tokio::sync::Notify>, Arc<tokio::sync::Notify>) {
        install_pause(&AFTER_MEMBER_DELETE, space)
    }

    pub(crate) fn pause_after_runtime_take(
        space: &str,
    ) -> (Arc<tokio::sync::Notify>, Arc<tokio::sync::Notify>) {
        install_pause(&AFTER_RUNTIME_TAKE, space)
    }

    async fn await_pause(
        pauses: &'static OnceLock<std::sync::Mutex<HashMap<String, Pause>>>,
        space: &str,
    ) {
        let pause = pauses
            .get_or_init(Default::default)
            .lock()
            .unwrap()
            .remove(space);
        if let Some(pause) = pause {
            pause.reached.notify_one();
            pause.resume.notified().await;
        }
    }

    pub(crate) async fn after_member_delete(space: &str) {
        await_pause(&AFTER_MEMBER_DELETE, space).await;
    }

    pub(crate) async fn after_runtime_take(space: &str) {
        await_pause(&AFTER_RUNTIME_TAKE, space).await;
    }
}

pub(crate) mod community_routing_test_hooks {
    use super::*;

    struct Pause {
        reached: Arc<tokio::sync::Notify>,
        resume: Arc<tokio::sync::Notify>,
    }

    static AFTER_SNAPSHOT: OnceLock<std::sync::Mutex<HashMap<String, Pause>>> = OnceLock::new();

    pub(crate) fn pause_after_snapshot(
        space: &str,
    ) -> (Arc<tokio::sync::Notify>, Arc<tokio::sync::Notify>) {
        let reached = Arc::new(tokio::sync::Notify::new());
        let resume = Arc::new(tokio::sync::Notify::new());
        AFTER_SNAPSHOT
            .get_or_init(Default::default)
            .lock()
            .unwrap()
            .insert(
                space.to_owned(),
                Pause {
                    reached: Arc::clone(&reached),
                    resume: Arc::clone(&resume),
                },
            );
        (reached, resume)
    }

    pub(crate) async fn after_snapshot(space: &str) {
        let pause = AFTER_SNAPSHOT
            .get_or_init(Default::default)
            .lock()
            .unwrap()
            .remove(space);
        if let Some(pause) = pause {
            pause.reached.notify_one();
            pause.resume.notified().await;
        }
    }
}

pub(crate) mod community_parity_test_hooks {
    use super::*;
    use std::sync::atomic::{AtomicBool, Ordering};

    struct Pause {
        reached: Arc<tokio::sync::Notify>,
        resume: Arc<tokio::sync::Notify>,
        read_connection_autocommit: Arc<AtomicBool>,
    }

    static AFTER_SNAPSHOT: OnceLock<std::sync::Mutex<HashMap<(String, String), Pause>>> =
        OnceLock::new();

    pub(crate) fn pause_after_snapshot(
        consumer: &str,
        relevant_spaces_digest: &str,
    ) -> (
        Arc<tokio::sync::Notify>,
        Arc<tokio::sync::Notify>,
        Arc<AtomicBool>,
    ) {
        let reached = Arc::new(tokio::sync::Notify::new());
        let resume = Arc::new(tokio::sync::Notify::new());
        let read_connection_autocommit = Arc::new(AtomicBool::new(false));
        AFTER_SNAPSHOT
            .get_or_init(Default::default)
            .lock()
            .unwrap()
            .insert(
                (consumer.to_owned(), relevant_spaces_digest.to_owned()),
                Pause {
                    reached: Arc::clone(&reached),
                    resume: Arc::clone(&resume),
                    read_connection_autocommit: Arc::clone(&read_connection_autocommit),
                },
            );
        (reached, resume, read_connection_autocommit)
    }

    pub(crate) async fn after_snapshot(
        consumer: &str,
        relevant_spaces_digest: &str,
        autocommit: bool,
    ) {
        let pause = AFTER_SNAPSHOT
            .get_or_init(Default::default)
            .lock()
            .unwrap()
            .remove(&(consumer.to_owned(), relevant_spaces_digest.to_owned()));
        if let Some(pause) = pause {
            pause
                .read_connection_autocommit
                .store(autocommit, Ordering::Release);
            pause.reached.notify_one();
            pause.resume.notified().await;
        }
    }
}

// ── compute_page_delta_summary tests ─────────────────────────────────────

#[test]
fn delta_noop_returns_none() {
    // Identical content and identical source sets → None.
    let result = compute_page_delta_summary(
        "same content",
        &["mem_a".to_string()],
        "same content",
        &["mem_a"],
        "re_distill",
    );
    assert_eq!(result, None);
}

#[test]
fn delta_char_only() {
    // Content changes, sources same, user-edit branch.
    let result = compute_page_delta_summary(
        "abc",
        &["mem_a".to_string()],
        "abcdef",
        &["mem_a"],
        "fs_edit",
    );
    let s = result.expect("should be Some");
    assert!(s.contains("User-edited"), "expected 'User-edited' in: {s}");
    assert!(s.contains("+3 chars"), "expected '+3 chars' in: {s}");
}

#[test]
fn delta_word_delta_surfaces_when_large() {
    // 6-word change (>= 5 threshold) should appear.
    let old = "one two three";
    let new = "one two three four five six seven eight nine";
    let result =
        compute_page_delta_summary(old, &["mem_a".to_string()], new, &["mem_a"], "fs_edit");
    let s = result.expect("should be Some");
    assert!(s.contains("words"), "expected word delta in: {s}");
}

#[test]
fn delta_source_added() {
    let result = compute_page_delta_summary(
        "content",
        &["mem_a".to_string()],
        "content",
        &["mem_a", "mem_xyz"],
        "re_distill",
    );
    let s = result.expect("should be Some");
    assert!(s.contains("+mem_xyz"), "expected '+mem_xyz' in: {s}");
}

#[test]
fn delta_source_removed() {
    let result = compute_page_delta_summary(
        "content",
        &["mem_old".to_string(), "mem_keep".to_string()],
        "content",
        &["mem_keep"],
        "re_distill",
    );
    let s = result.expect("should be Some");
    assert!(s.contains("-mem_old"), "expected '-mem_old' in: {s}");
}

#[test]
fn delta_many_sources_truncated() {
    // Adding 5 new sources: first 3 listed, then "(+ 2 more)".
    let old_sources: Vec<String> = vec!["mem_keep".to_string()];
    let new_sources = ["mem_keep", "mem_1", "mem_2", "mem_3", "mem_4", "mem_5"];
    let result = compute_page_delta_summary(
        "content",
        &old_sources,
        "content",
        &new_sources,
        "re_distill",
    );
    let s = result.expect("should be Some");
    assert!(s.contains("(+ 2 more)"), "expected '(+ 2 more)' in: {s}");
}

#[test]
fn delta_user_edit_branch() {
    // manual_edit → "User-edited" prefix.
    let result = compute_page_delta_summary(
        "original",
        &["mem_a".to_string()],
        "original plus more text here",
        &["mem_a"],
        "manual_edit",
    );
    let s = result.expect("should be Some");
    assert!(
        s.starts_with("User-edited"),
        "expected 'User-edited' prefix in: {s}"
    );
}

#[test]
fn delta_synthesize_from_empty() {
    // old is empty + edited_by="distill" → "Synthesized from N sources".
    let result = compute_page_delta_summary(
        "",
        &[],
        "full body content here",
        &["src_a", "src_b"],
        "distill",
    );
    let s = result.expect("should be Some");
    assert!(
        s.starts_with("Synthesized from 2 sources"),
        "expected synthesize message in: {s}"
    );
}

#[test]
fn delta_re_distill_paren_suffix() {
    // re_distill with source addition → suffix "(re_distill)".
    let result = compute_page_delta_summary(
        "body",
        &["mem_a".to_string()],
        "body extended with more",
        &["mem_a", "mem_new"],
        "re_distill",
    );
    let s = result.expect("should be Some");
    assert!(
        s.ends_with("(re_distill)"),
        "expected '(re_distill)' suffix in: {s}"
    );
}

#[test]
fn delta_distill_nonempty_old_paren_suffix() {
    // distill with non-empty old content → paren suffix "(distill)" (not silenced).
    let result = compute_page_delta_summary(
        "existing content",
        &["mem_a".to_string()],
        "existing content extended",
        &["mem_a"],
        "distill",
    );
    let s = result.expect("should be Some");
    assert!(
        s.ends_with("(distill)"),
        "expected '(distill)' suffix in: {s}"
    );
}

#[test]
fn delta_exactly_3_sources_no_more_suffix() {
    // Adding exactly 3 new sources: all 3 listed, no "(+ N more)".
    let old_sources: Vec<String> = vec!["mem_keep".to_string()];
    let new_sources = ["mem_keep", "mem_1", "mem_2", "mem_3"];
    let result = compute_page_delta_summary(
        "content",
        &old_sources,
        "content",
        &new_sources,
        "re_distill",
    );
    let s = result.expect("should be Some");
    assert!(
        !s.contains("more)"),
        "expected no '(+ N more)' for exactly 3 added in: {s}"
    );
    assert!(s.contains("+mem_1"), "expected +mem_1 in: {s}");
    assert!(s.contains("+mem_2"), "expected +mem_2 in: {s}");
    assert!(s.contains("+mem_3"), "expected +mem_3 in: {s}");
}

#[test]
fn delta_exactly_4_sources_one_more_suffix() {
    // Adding exactly 4 new sources: first 3 listed, then "(+ 1 more)".
    let old_sources: Vec<String> = vec!["mem_keep".to_string()];
    let new_sources = ["mem_keep", "mem_1", "mem_2", "mem_3", "mem_4"];
    let result = compute_page_delta_summary(
        "content",
        &old_sources,
        "content",
        &new_sources,
        "re_distill",
    );
    let s = result.expect("should be Some");
    assert!(
        s.contains("(+ 1 more)"),
        "expected '(+ 1 more)' for 4 added in: {s}"
    );
}

