#[tokio::test]
async fn migration_95_replays_after_partial_ddl_without_losing_existing_identity_rows() {
    let dir = tempdir().unwrap();
    let embedder = shared_embedder();
    let db = MemoryDB::new_with_shared_embedder(
        dir.path(),
        Arc::new(crate::events::NoopEmitter),
        Arc::clone(&embedder),
    )
    .await
    .unwrap();
    drop(db);

    let raw_db = libsql::Builder::new_local(
        dir.path()
            .join("origin_memory.db")
            .to_str()
            .expect("migration replay path"),
    )
    .build()
    .await
    .unwrap();
    let raw = raw_db.connect().unwrap();
    raw.execute_batch(
        "PRAGMA foreign_keys=OFF;
         DROP TABLE IF EXISTS community_members;
         DROP TABLE IF EXISTS grouping_leases;
         DROP TABLE IF EXISTS space_graph_state;
         DROP TABLE IF EXISTS communities;
         CREATE TABLE communities (
             community_id TEXT PRIMARY KEY,
             space TEXT NOT NULL,
             display_name TEXT,
             algo_version TEXT NOT NULL,
             projection_version TEXT NOT NULL,
             created_at INTEGER NOT NULL,
             updated_at INTEGER NOT NULL,
             retired_at INTEGER
         );
         INSERT INTO communities (
             community_id, space, display_name, algo_version,
             projection_version, created_at, updated_at, retired_at
         ) VALUES (
             'partial-community', 'partial-space', NULL, 'leiden-m4-v1',
             'grounded-relates-v1', 1712707200, 1712707200, NULL
         );
         CREATE TABLE space_graph_state (
             space TEXT PRIMARY KEY,
             graph_generation INTEGER NOT NULL DEFAULT 0,
             published_generation INTEGER,
             dirty INTEGER NOT NULL DEFAULT 0
         );
         INSERT INTO space_graph_state (
             space, graph_generation, published_generation, dirty
         ) VALUES ('partial-space', 7, 6, 1);
         PRAGMA user_version=94;",
    )
    .await
    .unwrap();
    drop(raw);
    drop(raw_db);

    let reopened = MemoryDB::new_with_shared_embedder(
        dir.path(),
        Arc::new(crate::events::NoopEmitter),
        embedder,
    )
    .await
    .expect("migration 95 must replay after interrupted partial DDL");
    let conn = reopened.conn.lock().await;
    let mut version_rows = conn.query("PRAGMA user_version", ()).await.unwrap();
    assert_eq!(
        version_rows
            .next()
            .await
            .unwrap()
            .unwrap()
            .get::<i64>(0)
            .unwrap(),
        i64::from(SCHEMA_VERSION)
    );
    drop(version_rows);
    for table in [
        "communities",
        "community_members",
        "space_graph_state",
        "grouping_leases",
    ] {
        let mut rows = conn
            .query(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?1",
                libsql::params![table],
            )
            .await
            .unwrap();
        assert!(
            rows.next().await.unwrap().is_some(),
            "migration replay must restore {table}"
        );
    }
    let mut identity_rows = conn
        .query(
            "SELECT algo_version, projection_version FROM communities \
             WHERE community_id='partial-community'",
            (),
        )
        .await
        .unwrap();
    let identity = identity_rows.next().await.unwrap().unwrap();
    assert_eq!(identity.get::<String>(0).unwrap(), "leiden-m4-v1");
    assert_eq!(identity.get::<String>(1).unwrap(), "grounded-relates-v1");
    drop(identity_rows);
    let mut state_rows = conn
        .query(
            "SELECT graph_generation, grouping_generation, published_generation, dirty \
             FROM space_graph_state WHERE space='partial-space'",
            (),
        )
        .await
        .unwrap();
    let state = state_rows.next().await.unwrap().unwrap();
    assert_eq!(state.get::<i64>(0).unwrap(), 7);
    assert_eq!(
        state.get::<i64>(1).unwrap(),
        8,
        "partial migration replay must advance the broader generation past graph-only state"
    );
    assert_eq!(state.get::<i64>(2).unwrap(), 6);
    assert_eq!(state.get::<i64>(3).unwrap(), 1);
}

#[tokio::test]
async fn migration_95_repairs_stamped_schema_and_bootstraps_existing_grounded_spaces() {
    let dir = tempdir().unwrap();
    let db = MemoryDB::new_with_shared_embedder(
        dir.path(),
        Arc::new(crate::events::NoopEmitter),
        shared_embedder(),
    )
    .await
    .unwrap();
    // The ported `edges_space_fence` trigger resolves an entity endpoint's
    // space via its shadow page, so the two entities below need one each
    // before the relation/edge fixtures can insert.
    db.test_seed_entity_shadow_page(
        TestEntity::new("m95-bootstrap-left", "Left", "concept").space("m95-bootstrap-space"),
    )
    .await
    .unwrap();
    db.test_seed_entity_shadow_page(
        TestEntity::new("m95-bootstrap-right", "Right", "concept").space("m95-bootstrap-space"),
    )
    .await
    .unwrap();
    // `test_seed_entity_shadow_page` leaves the shadow embedding NULL, which
    // the crash-recovery pass reads as an entities/shadow desync and "repairs"
    // via the embedder -- an UPDATE that fires the M4 grouping trigger and
    // moves the very generation this test asserts on. Backfill a matching
    // non-NULL embedding so the pair reads as already in sync, exactly as
    // `migration_95_complete_shape_does_not_repeat_grounded_bootstrap_scan`
    // does for the same reason.
    {
        let conn = db.conn.lock().await;
        let embedding = MemoryDB::vec_to_sql(&vec![0.0f32; EMBEDDING_DIM]);
        for entity_id in ["m95-bootstrap-left", "m95-bootstrap-right"] {
            conn.execute(
                "UPDATE pages SET embedding = vector32(?1) \
                 WHERE kind = 'entity' \
                   AND id = (SELECT page_id FROM entity_page_map WHERE entity_id = ?2)",
                libsql::params![embedding.clone(), entity_id],
            )
            .await
            .unwrap();
        }
    }
    let conn = db.conn.lock().await;
    conn.execute_batch(
        "INSERT INTO provenance_roots (
             root_id, identity_version, identity_digest, root_kind,
             independence_group_id, status, created_at
         ) VALUES (
             'm95-bootstrap-root', 1, 'm95-bootstrap-digest', 'generated',
             'm95-bootstrap-group', 'active', 1
         );
         INSERT INTO relations (
             id, from_entity, to_entity, relation_type, source_agent, created_at
         ) VALUES (
             'm95-bootstrap-relation', 'm95-bootstrap-left', 'm95-bootstrap-right',
             'related_to', 'test', 1
         );",
    )
    .await
    .unwrap();
    drop(conn);
    let conn = db.conn.lock().await;
    // Content-addressed, and backed by the `relations` row above: `relations` is
    // the sole producer of `relates`, so an edge with no relation behind it is
    // parity drift that migration 111's repair retracts.
    conn.execute(
        "INSERT INTO edges (
             edge_id, src_id, src_kind, dst_id, dst_kind, edge_type,
             lineage, grounded, root_id, space, created_at
         ) VALUES (
             ?1, 'm95-bootstrap-left', 'entity',
             'm95-bootstrap-right', 'entity', 'relates', 'assertion', 1,
             'm95-bootstrap-root', 'm95-bootstrap-space', 1
         )",
        libsql::params![crate::provenance::compute_edge_id(
            "relates",
            "entity",
            "m95-bootstrap-left",
            "entity",
            "m95-bootstrap-right",
            "related_to",
        )],
    )
    .await
    .unwrap();
    conn.execute_batch(
        "DROP TABLE community_members;
         DROP TABLE grouping_leases;
         DROP TABLE space_graph_state;
         DROP TABLE communities;
         CREATE TABLE space_graph_state (
             space TEXT PRIMARY KEY,
             graph_generation INTEGER NOT NULL DEFAULT 0,
             published_generation INTEGER,
             dirty INTEGER NOT NULL DEFAULT 0
         );
         INSERT INTO space_graph_state (
             space, graph_generation, published_generation, dirty
         ) VALUES ('m95-clean-space', 9, 9, 0);",
    )
    .await
    .unwrap();
    drop(conn);

    // A database that genuinely sat at 95 -- legacy entity rows present, M4
    // triggers still anchored on `entities` -- not a tip-shaped one wearing an
    // old version number. See `test_rewind_to_version`.
    db.test_rewind_to_version(95).await.unwrap();

    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("startup repair must run even when user_version is already 95");

    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT graph_generation, grouping_generation, published_generation, dirty \
             FROM space_graph_state WHERE space='m95-bootstrap-space'",
            (),
        )
        .await
        .expect("query bootstrapped M4 state");
    let state = rows
        .next()
        .await
        .expect("read bootstrapped M4 state")
        .expect("pre-existing grounded space must be queued");
    assert_eq!(state.get::<i64>(0).unwrap(), 1);
    assert_eq!(state.get::<i64>(1).unwrap(), 1);
    assert_eq!(state.get::<Option<i64>>(2).unwrap(), None);
    assert_eq!(state.get::<i64>(3).unwrap(), 1);
    drop(rows);

    let mut rows = conn
        .query(
            "SELECT graph_generation, grouping_generation, published_generation, dirty \
             FROM space_graph_state WHERE space='m95-clean-space'",
            (),
        )
        .await
        .expect("query conservatively invalidated clean M4 state");
    let state = rows
        .next()
        .await
        .expect("read conservatively invalidated clean M4 state")
        .expect("existing state row must survive repair");
    assert_eq!(state.get::<i64>(0).unwrap(), 9);
    assert_eq!(
        state.get::<i64>(1).unwrap(),
        10,
        "a newly repaired grouping generation must outrun the old clean publication"
    );
    assert_eq!(state.get::<Option<i64>>(2).unwrap(), Some(9));
    assert_eq!(
        state.get::<i64>(3).unwrap(),
        1,
        "old graph-only cleanliness cannot prove the broader grouping snapshot"
    );
}

#[tokio::test]
async fn migration_95_complete_shape_does_not_repeat_grounded_bootstrap_scan() {
    let (db, _dir) = test_db().await;
    // The ported `edges_space_fence` trigger resolves an entity endpoint's
    // space via its shadow page, so the two entities below need one each
    // before the edge below can insert.
    db.test_seed_entity_shadow_page(
        TestEntity::new("m95-late-left", "Left", "concept").space("m95-late-direct-space"),
    )
    .await
    .unwrap();
    db.test_seed_entity_shadow_page(
        TestEntity::new("m95-late-right", "Right", "concept").space("m95-late-direct-space"),
    )
    .await
    .unwrap();
    let conn = db.conn.lock().await;
    conn.execute(
        "INSERT INTO provenance_roots (
             root_id, identity_version, identity_digest, root_kind,
             independence_group_id, status, created_at
         ) VALUES (
             'm95-late-root', 1, 'm95-late-digest', 'generated',
             'm95-late-group', 'active', 1
         )",
        (),
    )
    .await
    .unwrap();
    drop(conn);
    // `test_seed_entity_shadow_page` deliberately leaves the shadow page's
    // embedding NULL (raw-SQL fixtures carry no re-encodable blob -- see its
    // own doc comment). Item 6's UNION-ported crash-recovery pass now reads
    // that NULL as a genuine entities/shadow desync and "recovers" it via
    // the embedder, which UPDATEs `entities.embedding` and fires
    // `m4_grouping_entity_update`, re-dirtying `space_graph_state` for this
    // space -- exactly the row this test deletes below to isolate the M4
    // substrate-repair guard from unrelated recovery mechanics. Backfill a
    // matching non-NULL embedding here so the shadow pages read as already
    // in sync and the crash-recovery pass has nothing to do.
    {
        let conn = db.conn.lock().await;
        let embedding = MemoryDB::vec_to_sql(&vec![0.0f32; EMBEDDING_DIM]);
        for entity_id in ["m95-late-left", "m95-late-right"] {
            conn.execute(
                "UPDATE pages SET embedding = vector32(?1) \
                 WHERE kind = 'entity' \
                   AND id = (SELECT page_id FROM entity_page_map WHERE entity_id = ?2)",
                libsql::params![embedding.clone(), entity_id],
            )
            .await
            .unwrap();
        }
    }
    let conn = db.conn.lock().await;
    conn.execute(
        "INSERT INTO edges (
             edge_id, src_id, src_kind, dst_id, dst_kind, edge_type,
             lineage, grounded, root_id, space, created_at
         ) VALUES (
             'm95-late-edge', 'm95-late-left', 'entity',
             'm95-late-right', 'entity', 'relates', 'assertion', 1,
             'm95-late-root', 'm95-late-direct-space', 1
         )",
        (),
    )
    .await
    .unwrap();
    conn.execute(
        "DELETE FROM space_graph_state WHERE space='m95-late-direct-space'",
        (),
    )
    .await
    .unwrap();
    let mut rows = conn
        .query(
            "SELECT 1 FROM space_graph_state WHERE space='m95-late-direct-space'",
            (),
        )
        .await
        .unwrap();
    assert!(
        rows.next().await.unwrap().is_none(),
        "fixture removes trigger-created state to isolate complete-shape startup scanning"
    );
    drop(rows);
    drop(conn);

    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("a complete M95 shape needs no repair");

    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT 1 FROM space_graph_state WHERE space='m95-late-direct-space'",
            (),
        )
        .await
        .unwrap();
    assert!(
        rows.next().await.unwrap().is_none(),
        "complete M95 startup must not rescan all grounded edges"
    );
}

