#[tokio::test]
async fn upsert_documents_page_invalidation_rolls_back_with_replacement() {
    let (db, _dir) = test_db().await;
    db.upsert_documents(vec![make_memory_doc(
        "replace-page-rollback",
        "Original source content survives rollback.",
        "knowledge",
        "work",
        "agent",
    )])
    .await
    .unwrap();
    let row_id = memory_row_id(&db, "memory", "replace-page-rollback").await;
    let pages = install_page_locator_forms(
        &db,
        "page-upsert-rollback",
        "replace-page-rollback",
        &row_id,
    )
    .await;
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "CREATE TRIGGER reject_upsert_page_invalidation
             BEFORE UPDATE OF stale_reason ON pages
             WHEN OLD.id = 'page-upsert-rollback-mixed'
             BEGIN SELECT RAISE(ABORT, 'blocked upsert page invalidation'); END",
            (),
        )
        .await
        .unwrap();
    }

    let error = db
        .upsert_documents(vec![make_memory_doc(
            "replace-page-rollback",
            "Replacement must roll back.",
            "knowledge",
            "work",
            "agent",
        )])
        .await
        .unwrap_err();
    assert!(error
        .to_string()
        .contains("blocked upsert page invalidation"));

    let memories = db
        .get_memories_by_source_id("memory", "replace-page-rollback")
        .await
        .unwrap();
    assert_eq!(
        memories[0].content,
        "Original source content survives rollback."
    );
    for (page_id, revision_before, count_before) in pages {
        let page = db.get_page(&page_id).await.unwrap().unwrap();
        assert_eq!(page.stale_reason, None);
        assert_eq!(page.sources_updated_count, count_before);
        assert_eq!(
            db.get_page_source_revision(&page_id).await.unwrap(),
            revision_before
        );
    }
}

#[tokio::test]
async fn upsert_documents_rolls_back_and_reuses_connection() {
    let (db, _dir) = test_db().await;
    let original =
        "Original evidence must remain available after a failed replacement. ".repeat(200);
    db.upsert_documents_with_derived_channels_for_test(
        vec![memory_doc_with_fields(
            "tx-replace",
            &original,
            "{\"status\":\"original\"}",
        )],
        false,
        true,
    )
    .await
    .unwrap();

    let old_memories = db
        .get_memories_by_source_id("memory", "tx-replace")
        .await
        .unwrap();
    assert!(
        old_memories.len() > 1,
        "fixture must cover replacement of multiple chunks"
    );
    let mut old_chunk_inventory: Vec<_> = old_memories
        .iter()
        .map(|memory| (memory.id.clone(), memory.content.clone()))
        .collect();
    old_chunk_inventory.sort();
    let old_child_count = count_child_vectors_for(&db, "tx-replace").await;
    assert!(
        old_child_count >= 2,
        "fixture must include derived child rows"
    );
    let old_child_inventory = child_vector_inventory_for(&db, "tx-replace").await;

    {
        let conn = db.conn.lock().await;
        conn.execute(
            "CREATE TRIGGER fail_tx_replacement
             BEFORE INSERT ON memories
             WHEN NEW.source = 'memory' AND NEW.source_id = 'tx-replace'
             BEGIN SELECT RAISE(ABORT, 'blocked replacement'); END",
            (),
        )
        .await
        .unwrap();
    }

    let replacement = memory_doc_with_fields(
        "tx-replace",
        "Replacement content must not partially overwrite the original.",
        "{\"status\":\"replacement\"}",
    );
    let error = db
        .upsert_documents_with_derived_channels_for_test(vec![replacement.clone()], false, true)
        .await
        .unwrap_err();
    assert!(
        error.to_string().contains("blocked replacement"),
        "expected trigger failure, got {error}"
    );

    let memories_after_failure = db
        .get_memories_by_source_id("memory", "tx-replace")
        .await
        .unwrap();
    assert_eq!(
        memories_after_failure.len(),
        old_memories.len(),
        "failed replacement must preserve every old chunk"
    );
    let mut chunk_inventory_after_failure: Vec<_> = memories_after_failure
        .iter()
        .map(|memory| (memory.id.clone(), memory.content.clone()))
        .collect();
    chunk_inventory_after_failure.sort();
    assert_eq!(
        chunk_inventory_after_failure, old_chunk_inventory,
        "failed replacement must preserve old chunk identity and content"
    );
    assert_eq!(
        count_child_vectors_for(&db, "tx-replace").await,
        old_child_count,
        "failed replacement must preserve derived child rows"
    );
    assert_eq!(
        child_vector_inventory_for(&db, "tx-replace").await,
        old_child_inventory,
        "failed replacement must preserve child identity and content"
    );

    {
        let conn = db.conn.lock().await;
        conn.execute("DROP TRIGGER fail_tx_replacement", ())
            .await
            .unwrap();
    }
    db.upsert_documents_with_derived_channels_for_test(vec![replacement], false, true)
        .await
        .expect("connection should accept a new transaction after rollback");

    let memories_after_retry = db
        .get_memories_by_source_id("memory", "tx-replace")
        .await
        .unwrap();
    assert_eq!(memories_after_retry.len(), 1);
    assert_eq!(
        memories_after_retry[0].content,
        "Replacement content must not partially overwrite the original."
    );
}

async fn seed_conflicting_replacement_spaces(
    db: &MemoryDB,
    source_id: &str,
) -> Vec<(String, String, Option<String>, i64)> {
    let original =
        "Original evidence must remain byte-for-byte available when replacement space inheritance is ambiguous. "
            .repeat(200);
    db.upsert_documents(vec![make_doc(
        "memory",
        source_id,
        "Original document",
        &original,
    )])
    .await
    .unwrap();

    {
        let conn = db.conn.lock().await;
        conn.execute(
            "UPDATE memories
             SET space = CASE WHEN chunk_index = 0 THEN 'alpha-space' ELSE 'zeta-space' END
             WHERE source = 'memory' AND source_id = ?1",
            libsql::params![source_id],
        )
        .await
        .unwrap();
    }

    let inventory = replacement_inventory(db, source_id).await;
    assert!(
        inventory.len() > 1,
        "fixture must cover replacement of multiple chunks"
    );
    assert!(
        inventory
            .iter()
            .any(|(_, _, space, _)| space.as_deref() == Some("alpha-space"))
            && inventory
                .iter()
                .any(|(_, _, space, _)| space.as_deref() == Some("zeta-space")),
        "fixture must contain conflicting non-NULL spaces"
    );
    inventory
}

async fn replacement_inventory(
    db: &MemoryDB,
    source_id: &str,
) -> Vec<(String, String, Option<String>, i64)> {
    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT id, content, space, version
             FROM memories
             WHERE source = 'memory' AND source_id = ?1
             ORDER BY id",
            libsql::params![source_id],
        )
        .await
        .unwrap();
    let mut inventory = Vec::new();
    while let Some(row) = rows.next().await.unwrap() {
        inventory.push((
            row.get(0).unwrap(),
            row.get(1).unwrap(),
            row.get(2).unwrap(),
            row.get(3).unwrap(),
        ));
    }
    inventory
}

#[tokio::test]
async fn omitted_replacement_space_rejects_conflicting_existing_spaces_without_mutation() {
    let (db, _dir) = test_db().await;
    let source_id = "ambiguous-replacement-space";
    let old_inventory = seed_conflicting_replacement_spaces(&db, source_id).await;

    let replacement = make_doc(
        "memory",
        source_id,
        "Replacement document",
        "Replacement content must be rejected before the old chunks are mutated.",
    );
    assert!(replacement.space.is_none());
    let error = db.upsert_documents(vec![replacement]).await.unwrap_err();
    assert!(
        error.to_string().contains("ambiguous replacement space"),
        "expected an ambiguity error, got {error}"
    );
    assert_eq!(
        replacement_inventory(&db, source_id).await,
        old_inventory,
        "an ambiguous omitted-space replacement must preserve every old row exactly"
    );
}

#[tokio::test]
async fn explicit_replacement_space_heals_conflicting_existing_spaces() {
    let (db, _dir) = test_db().await;
    let source_id = "explicit-heals-ambiguous-space";
    seed_conflicting_replacement_spaces(&db, source_id).await;

    let mut replacement = make_doc(
        "memory",
        source_id,
        "Replacement document",
        "An explicit incoming space remains authoritative.",
    );
    replacement.space = Some("healed-space".to_string());
    db.upsert_documents(vec![replacement]).await.unwrap();

    let inventory = replacement_inventory(&db, source_id).await;
    assert!(!inventory.is_empty());
    assert!(
        inventory.iter().all(
            |(_, _, space, version)| space.as_deref() == Some("healed-space") && *version == 2
        ),
        "the explicit replacement must heal every new chunk into its authoritative space"
    );
}

#[tokio::test]
async fn replacement_new_episode_inherits_the_parent_assigned_space() {
    let (db, _dir) = test_db().await;
    let initial = make_doc(
        "memory",
        "episode-space-transition",
        "Initial document",
        "The initial document generation has enough words for an episode but keeps it disabled.",
    );
    db.upsert_documents_with_derived_channels_for_test(vec![initial], false, false)
        .await
        .unwrap();
    db.update_memory_space("episode-space-transition", "m4-live")
        .await
        .unwrap();

    let replacement = make_doc(
        "memory",
        "episode-space-transition",
        "Replacement document",
        "transitionepisodetoken appears in this replacement generation with enough words to create a new episode.",
    );
    assert!(replacement.space.is_none());
    db.upsert_documents_with_derived_channels_for_test(vec![replacement], true, false)
        .await
        .unwrap();

    let (parent_space, episode_space) = {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT source, space FROM memories
                 WHERE source_id = 'episode-space-transition'
                 ORDER BY source",
                (),
            )
            .await
            .unwrap();
        let mut parent_space = None;
        let mut episode_space = None;
        while let Some(row) = rows.next().await.unwrap() {
            let source: String = row.get(0).unwrap();
            let space: String = row.get(1).unwrap();
            match source.as_str() {
                "memory" => parent_space = Some(space),
                "episode" => episode_space = Some(space),
                _ => {}
            }
        }
        (parent_space, episode_space)
    };
    assert_eq!(parent_space.as_deref(), Some("m4-live"));
    assert_eq!(
        episode_space, parent_space,
        "a newly derived episode must inherit its replacement parent's effective space"
    );

    let in_scope = db
        .search_episodes_scoped(
            "transitionepisodetoken",
            10,
            &ReadScope::Space("m4-live".to_string()),
        )
        .await
        .unwrap();
    assert!(
        in_scope
            .iter()
            .any(|hit| hit.source_id == "episode-space-transition"),
        "the new episode must be retrievable in the parent's assigned space"
    );
    let wrong_scope = db
        .search_episodes_scoped(
            "transitionepisodetoken",
            10,
            &ReadScope::Space("other-space".to_string()),
        )
        .await
        .unwrap();
    assert!(
        wrong_scope
            .iter()
            .all(|hit| hit.source_id != "episode-space-transition"),
        "the new episode must not leak into another space"
    );
}

