#[tokio::test]
async fn concurrent_resolve_or_create_entity_converges_on_one_identity() {
    let (db, _dir) = test_db().await;
    let db = Arc::new(db);
    let barrier = Arc::new(tokio::sync::Barrier::new(3));
    // Hold the connection until both tasks are queued at the first lookup.
    // Tokio's fair mutex then alternates the old multi-lock cascade,
    // deterministically exposing the resolve-then-create race.
    let conn_guard = db.conn.lock().await;

    let spawn_resolve = |db: Arc<MemoryDB>, barrier: Arc<tokio::sync::Barrier>| {
        tokio::spawn(async move {
            barrier.wait().await;
            db.resolve_or_create_entity(
                "Concurrent Canonical Entity",
                "concept",
                None,
                Some("test"),
                None,
            )
            .await
            .unwrap()
        })
    };
    let first = spawn_resolve(Arc::clone(&db), Arc::clone(&barrier));
    let second = spawn_resolve(Arc::clone(&db), Arc::clone(&barrier));
    barrier.wait().await;
    tokio::task::yield_now().await;
    drop(conn_guard);

    let (first, second) = tokio::join!(first, second);
    let first = first.unwrap();
    let second = second.unwrap();
    assert_eq!(first.0, second.0, "both callers must receive one id");
    assert_eq!(
        usize::from(first.1) + usize::from(second.1),
        1,
        "exactly one caller must report created=true"
    );

    // G6 Stage 2 PR 2c sub-step 3 item 5: `resolve_or_create_entity`'s
    // create branch (Step 4) calls `store_entity`, which is canonical-only
    // now -- a genuinely new entity like this one gets no `entities` row.
    // The old `entities`-by-name COUNT (and the shadow-count query's join
    // through `entities e ON e.id = m.entity_id`) would both silently read
    // 0 for a shadow-only entity, so check the winner id's shadow page
    // directly instead; there is no `entities` row to cross-check against.
    let winner_id = first.0.clone();
    let conn = db.conn.lock().await;
    let mut shadow_rows = conn
        .query(
            "SELECT COUNT(*)
             FROM entity_page_map m
             JOIN pages p ON p.id = m.page_id
             WHERE m.entity_id = ?1 AND p.kind = 'entity' AND p.status = 'active'",
            libsql::params![winner_id],
        )
        .await
        .unwrap();
    let shadow_count = shadow_rows
        .next()
        .await
        .unwrap()
        .unwrap()
        .get::<i64>(0)
        .unwrap();
    assert_eq!(shadow_count, 1, "one live shadow identity");
}

/// Differential oracle (discipline floor): both real callers must mint
/// the SAME entity id for the SAME input now that they share one
/// resolve-then-write core -- the exact divergence risk the goal prompt
/// flags ("kept hand-in-sync by comment") that a shared function removes
/// by construction instead of by discipline.
#[tokio::test]
async fn resolve_or_create_entity_agrees_across_both_real_callers() {
    let (db, _dir) = test_db().await;

    // Caller A: post_write::create_entity (agent/MCP/HTTP path).
    let req = wenlan_types::requests::CreateEntityRequest {
        name: "Convergence Test Entity".to_string(),
        entity_type: "concept".to_string(),
        space: None.into(),
        source_agent: Some("test".to_string()),
        confidence: None,
    };
    let result_a = crate::post_write::create_entity(&db, req, "test-agent")
        .await
        .unwrap();

    // Caller B: importer::resolve_entity_bulk (bulk-import path) resolving
    // the SAME name -- must land on caller A's id, not mint a second one.
    let extracted = crate::extract::ExtractedEntity {
        name: "Convergence Test Entity".to_string(),
        entity_type: "concept".to_string(),
    };
    let mut cache = std::collections::HashMap::new();
    let (id_b, created_b) =
        crate::importer::resolve_entity_bulk(&db, &mut cache, &extracted, "test-import")
            .await
            .unwrap();

    assert_eq!(
        result_a.id, id_b,
        "both callers must converge on one entity id"
    );
    assert!(
        !created_b,
        "second caller must resolve, not mint a duplicate"
    );
}

