/// G6 Stage 1.2 (relations-readers migration,
/// docs/plans/2026-08-05-g6-stage12-relations-readers-spec.md):
/// get_entity_detail now reads active `relates` edges instead of
/// `relations` rows. The relation `id` is therefore the edge's
/// content-addressed `edge_id`, not the legacy `relations` row's uuid (no
/// route dereferences it back into `relations`, so this wire-visible id
/// swap is safe), and `created_at` is sourced via `asserted_at`, which
/// mirrors the relations row's own `created_at`.
#[tokio::test]
async fn get_entity_detail_reads_relates_edge_fields() {
    let (db, _dir) = test_db().await;
    let alice_id = db
        .store_entity(
            "Alice G6",
            "person",
            Some("work"),
            Some("claude"),
            Some(0.9),
        )
        .await
        .unwrap();
    let wenlan_id = db
        .store_entity("Wenlan G6", "project", Some("work"), None, None)
        .await
        .unwrap();
    db.create_relation(
        &alice_id,
        &wenlan_id,
        "works_on",
        Some("claude"),
        Some(0.9),
        Some("seen"),
        None,
    )
    .await
    .unwrap();

    // G6 Stage 2 PR 2b: `relations` is frozen -- read the live `relates`
    // edge instead.
    let relation_type = {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT semantic_type FROM edges \
                 WHERE edge_type = 'relates' AND src_id = ?1 AND dst_id = ?2 \
                   AND valid_until IS NULL",
                libsql::params![alice_id.as_str(), wenlan_id.as_str()],
            )
            .await
            .unwrap();
        rows.next()
            .await
            .unwrap()
            .expect("relation row")
            .get::<String>(0)
            .unwrap()
    };
    let expected_edge_id = crate::provenance::compute_edge_id(
        "relates",
        "entity",
        &alice_id,
        "entity",
        &wenlan_id,
        &relation_type,
    );

    let detail = db.get_entity_detail(&alice_id).await.unwrap();
    assert_eq!(detail.relations.len(), 1);
    let relation = &detail.relations[0];
    assert_eq!(
        relation.id, expected_edge_id,
        "relation id must be the active edge's edge_id, not the relations row uuid"
    );
    assert_eq!(relation.relation_type, relation_type);
    assert_eq!(relation.source_agent.as_deref(), Some("claude"));
    assert_eq!(relation.direction, "outgoing");
    assert_eq!(relation.entity_id, wenlan_id);
    assert_eq!(relation.entity_name, "Wenlan G6");

    let stored_created_at: i64 = {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT created_at FROM edges \
                 WHERE edge_type = 'relates' AND src_id = ?1 AND dst_id = ?2 \
                   AND valid_until IS NULL",
                libsql::params![alice_id.as_str(), wenlan_id.as_str()],
            )
            .await
            .unwrap();
        rows.next()
            .await
            .unwrap()
            .expect("relation row")
            .get(0)
            .unwrap()
    };
    assert_eq!(
        relation.created_at, stored_created_at,
        "created_at must mirror the relations row's created_at via asserted_at"
    );
}

/// G6 Stage 2 PR 2c sub-step 3 item 4: the relations query's `entities` JOIN
/// (hydrating the OTHER side of each relation) now reads the target's
/// `kind='entity'` shadow page via `entity_page_map`/`pages` instead of
/// `entities` directly -- closing the site the G6 Stage 1.5b Part 3 port left
/// "out of scope per spec". Mutate ONLY the shadow page's `title`/
/// `entity_type` (leaving `entities` untouched, since sub-step 2's writers
/// still dual-write both stores) and assert the hydrated relation reflects
/// the page value: if this read were still on `entities`, it would see the
/// original name/type instead.
#[tokio::test]
async fn get_entity_detail_relations_hydrate_from_shadow_page() {
    let (db, _dir) = test_db().await;
    let alice_id = db
        .store_entity("Alice Shadow", "person", Some("work"), None, None)
        .await
        .unwrap();
    let wenlan_id = db
        .store_entity("Wenlan Shadow", "project", Some("work"), None, None)
        .await
        .unwrap();
    db.create_relation(&alice_id, &wenlan_id, "works_on", None, None, None, None)
        .await
        .unwrap();

    {
        let conn = db.conn.lock().await;
        conn.execute(
            "UPDATE pages SET title = 'Wenlan Retitled', entity_type = 'org' \
             WHERE id = (SELECT page_id FROM entity_page_map WHERE entity_id = ?1)",
            libsql::params![wenlan_id.as_str()],
        )
        .await
        .unwrap();
    }

    let detail = db.get_entity_detail(&alice_id).await.unwrap();
    assert_eq!(detail.relations.len(), 1);
    assert_eq!(
        detail.relations[0].entity_name, "Wenlan Retitled",
        "relation hydration must read the shadow page's title, not entities.name"
    );
    assert_eq!(
        detail.relations[0].entity_type, "org",
        "relation hydration must read the shadow page's entity_type, not entities.entity_type"
    );
}

