// A1b — the proof that eviction actually works end-to-end: an evicted row is
// EXCLUDED from a real `search_memory` call while a control row survives,
// the evicted row stays in the table (recoverable), and clearing
// supersede_mode makes it REAPPEAR in search. This is the load-bearing test
// that the retrieval exclusion (not just the marker flip) is wired up.
#[tokio::test]
async fn test_evict_stale_is_reversible_and_excluded_from_search() {
    let _serial = EVICT_ENV_LOCK.lock().await;
    let (db, _dir) = test_db().await;
    // Two rows with DISTINCT (so they survive search's near-dup collapse)
    // but topically-related content, both matching a "kubernetes" query.
    // rev_row: aged + low-confidence -> evicted. keep_row: aged but
    // high-confidence (above the floor) -> survives Gate 1.
    db.upsert_documents(vec![
        make_memory_doc(
            "rev_row",
            "the user prefers kubernetes for container orchestration at scale",
            "fact",
            "engineering",
            "claude",
        ),
        make_memory_doc(
            "keep_row",
            "the user runs kubernetes clusters across three cloud regions daily",
            "fact",
            "engineering",
            "claude",
        ),
    ])
    .await
    .unwrap();
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "UPDATE memories SET effective_confidence = 0.05,                  last_accessed = strftime('%s','now','-120 days')                  WHERE source_id = 'rev_row' AND source = 'memory'",
            (),
        )
        .await
        .unwrap();
        conn.execute(
            "UPDATE memories SET effective_confidence = 0.9,                  last_accessed = strftime('%s','now','-120 days')                  WHERE source_id = 'keep_row' AND source = 'memory'",
            (),
        )
        .await
        .unwrap();
    }

    let query = "kubernetes orchestration";

    // Pre-condition: both rows are searchable before eviction.
    let pre = db
        .search_memory(query, 10, None, &ReadScope::Global, None, None, None, None)
        .await
        .unwrap();
    let pre_ids: Vec<&str> = pre.iter().map(|r| r.source_id.as_str()).collect();
    assert!(
        pre_ids.contains(&"rev_row"),
        "rev_row searchable before eviction, got {:?}",
        pre_ids
    );
    assert!(
        pre_ids.contains(&"keep_row"),
        "keep_row searchable before eviction, got {:?}",
        pre_ids
    );

    // Evict.
    let report = temp_env::async_with_vars([("WENLAN_ENABLE_EVICTION", Some("1"))], async {
        db.evict_stale(&crate::tuning::EvictionConfig::default())
            .await
            .unwrap()
    })
    .await;
    assert_eq!(
        report.archived, 1,
        "only the low-confidence rev_row is evicted"
    );
    assert_eq!(report.deleted, 0, "Stage 1 never deletes");

    // Both rows still physically present — archive, not delete.
    assert_eq!(count_rows(&db).await, 2, "no rows deleted");

    // Real search now EXCLUDES the evicted row while the control survives.
    let post = db
        .search_memory(query, 10, None, &ReadScope::Global, None, None, None, None)
        .await
        .unwrap();
    let post_ids: Vec<&str> = post.iter().map(|r| r.source_id.as_str()).collect();
    assert!(
        !post_ids.contains(&"rev_row"),
        "evicted rev_row must be ABSENT from search, got {:?}",
        post_ids
    );
    assert!(
        post_ids.contains(&"keep_row"),
        "control keep_row must remain in search, got {:?}",
        post_ids
    );

    // Recoverable: clear the eviction marker (supersede_mode is NOT NULL with
    // DEFAULT 'hide', so recovery resets it to the visible default rather
    // than NULL) -> the row REAPPEARS in search.
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "UPDATE memories SET supersede_mode = 'hide' WHERE source_id = ?1 AND source = 'memory'",
            libsql::params!["rev_row"],
        )
        .await
        .unwrap();
    }
    let recovered = db
        .search_memory(query, 10, None, &ReadScope::Global, None, None, None, None)
        .await
        .unwrap();
    let rec_ids: Vec<&str> = recovered.iter().map(|r| r.source_id.as_str()).collect();
    assert!(
        rec_ids.contains(&"rev_row"),
        "un-evicted rev_row must REAPPEAR in search, got {:?}",
        rec_ids
    );
}

// Regression test for a prior incomplete flaky-test fix: `EVICT_ENV_LOCK`
// must be the ONE process-wide lock that every reader AND mutator of
// `WENLAN_ENABLE_EVICTION` shares. A "reader" future (mirroring
// `refinery::tests::test_daily_trigger_runs_only_maintenance_phases`,
// which holds the lock and depends on the ambient flag staying unset
// across an `.await`) races a "mutator" future that mirrors one of the 9
// `db.rs` `evict_stale` tests, which (per the same fix applied to those
// tests just above) now ALSO takes `EVICT_ENV_LOCK` before mutating —
// closing the gap the earlier fix left open (it serialized
// `refinery::tests`'s 5 call sites against each other, but not against
// `db::tests`'s own 9 tests mutating the same process-global env var).
// Note this is NOT protected by `temp_env`'s own internal `SERIAL_TEST`
// mutex either: that mutex only excludes OTHER `temp_env` callers, but
// the reader here (like the real Daily/Backstop tests) reads the ambient
// flag via a plain `eviction_enabled()` call, never going through
// `temp_env` itself. Uses `tokio::join!` (not `tokio::spawn`, which would
// require the `temp_env` future to be `Send` — it isn't, it holds a
// `parking_lot::ReentrantMutexGuard`) so both futures are polled
// cooperatively on the current task; the sleep windows are sized with
// generous margin (a 5x ratio between the mutator's active-flip duration
// and the reader's single check point) so the interleaving the test
// exercises is not scheduler-luck. Deleting the mutator's
// `EVICT_ENV_LOCK.lock().await` line reproduces the original gap and
// fails this test (verified before this fix landed).
#[tokio::test]
async fn test_evict_env_lock_shared_excludes_unlocked_mutator() {
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::sync::Arc;
    use std::time::Duration;

    let observed_flip = Arc::new(AtomicBool::new(false));
    let observed_flip_reader = observed_flip.clone();

    // Reader: acquires EVICT_ENV_LOCK, unsets the flag, and checks it
    // ONCE after a 50ms window — mirroring a Daily/Backstop trigger test
    // that reads the ambient flag after its own multi-phase `.await` run.
    let reader = async {
        let _serial = EVICT_ENV_LOCK.lock().await;
        temp_env::async_with_vars([("WENLAN_ENABLE_EVICTION", None::<&str>)], async {
            tokio::time::sleep(Duration::from_millis(50)).await;
            if eviction_enabled() {
                observed_flip_reader.store(true, Ordering::SeqCst);
            }
        })
        .await;
    };

    // Mutator: mirrors one of the (now-fixed) `db.rs` eviction tests —
    // takes EVICT_ENV_LOCK too, so it must wait for the reader's window
    // to close before it can flip the flag.
    let mutator = async {
        let _serial = EVICT_ENV_LOCK.lock().await;
        temp_env::async_with_vars([("WENLAN_ENABLE_EVICTION", Some("1"))], async {
            tokio::time::sleep(Duration::from_millis(80)).await;
        })
        .await;
    };

    tokio::join!(reader, mutator);

    assert!(
        !observed_flip.load(Ordering::SeqCst),
        "reader observed WENLAN_ENABLE_EVICTION flip to '1' mid-window: an \
         unlocked mutator raced a lock-holding reader — exactly the \
         corruption class left open when only refinery::tests declared its \
         own EVICT_ENV_LOCK instead of sharing db::tests's"
    );
}

// ==================== Decay Engine ====================

#[tokio::test]
async fn test_decay_update_confidence() {
    let (db, _dir) = test_db().await;

    // Insert memories with different tiers
    let mut doc1 = make_memory_doc(
        "decay_ephemeral",
        "Some recap content about coding",
        "goal",
        "engineering",
        "system",
    );
    doc1.confidence = Some(0.5);
    let mut doc2 = make_memory_doc(
        "decay_protected",
        "My name is Lucian",
        "identity",
        "personal",
        "claude",
    );
    doc2.confidence = Some(0.9);
    doc2.confirmed = Some(true);
    db.upsert_documents(vec![doc1, doc2]).await.unwrap();

    let count = db.decay_update_confidence().await.unwrap();
    assert!(count >= 2, "should update at least 2 memories");

    // Protected+confirmed should retain full confidence (decay_rate=0.0)
    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT effective_confidence FROM memories WHERE source_id = 'decay_protected' LIMIT 1",
            (),
        )
        .await
        .unwrap();
    let row = rows.next().await.unwrap().unwrap();
    let eff: f64 = row.get(0).unwrap();
    // Confirmed → decay_rate=0 → recency_boost=1.0, access_boost=1.0 → eff = confidence
    assert!(
        (eff - 0.9).abs() < 0.01,
        "confirmed memory should not decay, got {}",
        eff
    );
    drop(rows);
    drop(conn);
}

