#[tokio::test]
async fn test_list_spaces() {
    let (db, _dir) = test_db().await;
    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .unwrap();

    // No spaces initially
    let spaces = db.list_spaces().await.unwrap();
    assert!(spaces.is_empty());

    // Create a space
    let s = db
        .create_space("work", Some("Work stuff"), false)
        .await
        .unwrap();
    assert_eq!(s.name, "work");
    assert_eq!(s.description, Some("Work stuff".to_string()));
    assert!(!s.suggested);

    let spaces = db.list_spaces().await.unwrap();
    assert_eq!(spaces.len(), 1);
    assert_eq!(spaces[0].name, "work");
    assert_eq!(spaces[0].memory_count, 0);
}

/// M1 honest columns: `set_page_workspace` mirrors the scope onto BOTH
/// columns and normalizes `None` to the 'unfiled' sentinel (never NULL);
/// `row_to_page` hides that sentinel on the wire so an uncategorized page
/// surfaces as it did pre-M1. Load-bearing for the read-collapse (which now
/// reads `space` alone) and the NOT NULL rebuild.
#[tokio::test]
async fn set_page_workspace_mirrors_scope_and_wire_hides_unfiled_sentinel() {
    let (db, _dir) = test_db().await;
    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .unwrap();
    let now = chrono::Utc::now().to_rfc3339();

    db.insert_page_with_kind(
        "p-scoped",
        "Scoped",
        None,
        "body",
        None,
        None,
        &[],
        &now,
        "authored",
        "confirmed",
        None,
        None,
    )
    .await
    .unwrap();
    db.insert_page_with_kind(
        "p-unfiled",
        "Unfiled",
        None,
        "body",
        None,
        None,
        &[],
        &now,
        "authored",
        "confirmed",
        None,
        None,
    )
    .await
    .unwrap();

    // Some(x) mirrors x onto both columns; None mirrors the sentinel onto both.
    db.set_page_workspace("p-scoped", Some("career"))
        .await
        .unwrap();
    db.set_page_workspace("p-unfiled", None).await.unwrap();

    // Storage: both columns carry the resolved scope, neither is NULL.
    {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT space, workspace FROM pages WHERE id = ?1",
                libsql::params!["p-scoped"],
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().unwrap();
        assert_eq!(row.get::<String>(0).unwrap(), "career");
        assert_eq!(row.get::<String>(1).unwrap(), "career");
        let mut rows = conn
            .query(
                "SELECT space, workspace FROM pages WHERE id = ?1",
                libsql::params!["p-unfiled"],
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().unwrap();
        assert_eq!(row.get::<String>(0).unwrap(), UNFILED_SPACE_ID);
        assert_eq!(row.get::<String>(1).unwrap(), UNFILED_SPACE_ID);
    }

    // Wire: registered scope passes through; the sentinel is hidden (None).
    let scoped = db.get_page("p-scoped").await.unwrap().unwrap();
    assert_eq!(scoped.space.as_deref(), Some("career"));
    assert_eq!(scoped.workspace.as_deref(), Some("career"));
    let unfiled = db.get_page("p-unfiled").await.unwrap().unwrap();
    assert_eq!(
        unfiled.space, None,
        "unfiled sentinel must not leak onto the wire (space)"
    );
    assert_eq!(
        unfiled.workspace, None,
        "unfiled sentinel must not leak onto the wire (workspace)"
    );
}

#[tokio::test]
async fn test_space_crud() {
    let (db, _dir) = test_db().await;
    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .unwrap();

    // Create
    db.create_space("work", Some("Work things"), true)
        .await
        .unwrap();

    // Get
    let s = db.get_space("work").await.unwrap().unwrap();
    assert_eq!(s.name, "work");
    assert!(s.suggested);

    // Confirm
    db.confirm_space("work").await.unwrap();
    let s = db.get_space("work").await.unwrap().unwrap();
    assert!(!s.suggested);

    // Update (rename)
    db.update_space("work", "career", Some("Career stuff"))
        .await
        .unwrap();
    assert!(db.get_space("work").await.unwrap().is_none());
    let s = db.get_space("career").await.unwrap().unwrap();
    assert_eq!(s.description, Some("Career stuff".to_string()));

    // Delete
    db.delete_space("career", "keep").await.unwrap();
    assert!(db.get_space("career").await.unwrap().is_none());
}

#[tokio::test]
async fn update_space_cascades_pages_space_and_workspace() {
    let (db, _dir) = test_db().await;
    db.create_space("work", None, false).await.unwrap();
    db.upsert_documents(vec![make_memory_doc(
        "mem_space_rename_generation",
        "Memory moved by a space rename",
        "fact",
        "work",
        "agent",
    )])
    .await
    .unwrap();

    let now = chrono::Utc::now().to_rfc3339();
    db.insert_page_with_kind(
        "page_legacy_work",
        "Legacy Work",
        None,
        "legacy page using pages.space as the space axis",
        None,
        Some("work"),
        &[],
        &now,
        "authored",
        "confirmed",
        None,
        None,
    )
    .await
    .unwrap();
    db.insert_page_with_kind(
        "page_workspace_work",
        "Workspace Work",
        None,
        "newer page scoped by pages.workspace (single-axis: space mirrors workspace)",
        None,
        None,
        &[],
        &now,
        "authored",
        "confirmed",
        Some("work"),
        None,
    )
    .await
    .unwrap();

    db.update_space("work", "career", None).await.unwrap();

    let legacy = db.get_page("page_legacy_work").await.unwrap().unwrap();
    assert_eq!(
        legacy.space.as_deref(),
        Some("career"),
        "rename must update legacy pages.space values"
    );
    assert_eq!(
        legacy.version, 1,
        "renaming scope metadata must not advance an active Page content version"
    );

    let scoped = db.get_page("page_workspace_work").await.unwrap().unwrap();
    assert_eq!(
        scoped.space.as_deref(),
        Some("career"),
        "rename mirrors the scope onto pages.space -- one honest column, no independent category (spec §1)"
    );
    assert_eq!(
        scoped.workspace.as_deref(),
        Some("career"),
        "rename must update pages.workspace values"
    );
    assert_eq!(
        scoped.version, 1,
        "renaming scope metadata must not advance an active Page content version"
    );

    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT version FROM memories
             WHERE source_id = 'mem_space_rename_generation'
               AND source != 'episode' AND chunk_index = 0",
            (),
        )
        .await
        .unwrap();
    assert_eq!(
        rows.next().await.unwrap().unwrap().get::<i64>(0).unwrap(),
        2
    );
}

#[tokio::test]
async fn update_space_missing_source_does_not_cascade_orphaned_rows() {
    let (db, _dir) = test_db().await;
    db.create_space("career", None, false).await.unwrap();

    db.upsert_documents(vec![RawDocument {
        source: "memory".to_string(),
        source_id: "orphan_space_mem".to_string(),
        title: "Orphan Space Memory".to_string(),
        content: "orphaned memory row with a missing source space".to_string(),
        last_modified: chrono::Utc::now().timestamp(),
        memory_type: Some("fact".to_string()),
        space: Some("ghost".to_string()),
        ..Default::default()
    }])
    .await
    .unwrap();
    db.store_entity("Ghost Entity", "person", Some("ghost"), None, None)
        .await
        .unwrap();

    let now = chrono::Utc::now().to_rfc3339();
    db.insert_page_with_kind(
        "page_orphan_space",
        "Orphan Space Page",
        None,
        "orphaned page using pages.space as a missing source space",
        None,
        Some("ghost"),
        &[],
        &now,
        "authored",
        "confirmed",
        Some("ghost"),
        None,
    )
    .await
    .unwrap();

    let result = db.update_space("ghost", "career", None).await;
    assert!(result.is_err(), "renaming a missing source space must fail");

    let memory_space = db.get_memory_space("orphan_space_mem").await.unwrap();
    assert_eq!(
        memory_space.as_deref(),
        Some("ghost"),
        "failed rename must not cascade orphaned memory rows"
    );

    let entities = db.list_entities(None, None).await.unwrap();
    let entity = entities
        .iter()
        .find(|entity| entity.name == "Ghost Entity")
        .expect("ghost entity should exist");
    assert_eq!(
        entity.space.as_deref(),
        Some("ghost"),
        "failed rename must not cascade orphaned entity rows"
    );

    let page = db.get_page("page_orphan_space").await.unwrap().unwrap();
    assert_eq!(
        page.space.as_deref(),
        Some("ghost"),
        "failed rename must not cascade orphaned pages.space rows"
    );
    assert_eq!(
        page.workspace.as_deref(),
        Some("ghost"),
        "failed rename must not cascade orphaned pages.workspace rows"
    );
}

#[tokio::test]
async fn delete_space_move_cascades_pages_space_and_workspace() {
    let (db, _dir) = test_db().await;
    db.create_space("old", None, false).await.unwrap();
    db.create_space("new", None, false).await.unwrap();
    db.upsert_documents(vec![make_memory_doc(
        "mem_delete_space_move_generation",
        "Memory moved while deleting its old space",
        "fact",
        "old",
        "agent",
    )])
    .await
    .unwrap();

    let now = chrono::Utc::now().to_rfc3339();
    db.insert_page_with_kind(
        "page_delete_move_legacy",
        "Delete Move Legacy",
        None,
        "legacy page using pages.space as the space axis",
        None,
        Some("old"),
        &[],
        &now,
        "authored",
        "confirmed",
        None,
        None,
    )
    .await
    .unwrap();
    db.insert_page_with_kind(
        "page_delete_move_workspace",
        "Delete Move Workspace",
        None,
        "newer page scoped by pages.workspace (single-axis: space mirrors workspace)",
        None,
        None,
        &[],
        &now,
        "authored",
        "confirmed",
        Some("old"),
        None,
    )
    .await
    .unwrap();

    db.delete_space("old", "move:new").await.unwrap();

    assert!(
        db.get_space("old").await.unwrap().is_none(),
        "source space row must be deleted"
    );

    let legacy = db
        .get_page("page_delete_move_legacy")
        .await
        .unwrap()
        .unwrap();
    assert_eq!(
        legacy.space.as_deref(),
        Some("new"),
        "delete-space move must update legacy pages.space values"
    );
    assert_eq!(
        legacy.version, 1,
        "moving scope metadata must not advance an active Page content version"
    );

    let scoped = db
        .get_page("page_delete_move_workspace")
        .await
        .unwrap()
        .unwrap();
    assert_eq!(
        scoped.space.as_deref(),
        Some("new"),
        "delete-space move mirrors the scope onto pages.space -- one honest column, no independent category (spec §1)"
    );
    assert_eq!(
        scoped.workspace.as_deref(),
        Some("new"),
        "delete-space move must update pages.workspace values"
    );
    assert_eq!(
        scoped.version, 1,
        "moving scope metadata must not advance an active Page content version"
    );

    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT version FROM memories
             WHERE source_id = 'mem_delete_space_move_generation'
               AND source != 'episode' AND chunk_index = 0",
            (),
        )
        .await
        .unwrap();
    assert_eq!(
        rows.next().await.unwrap().unwrap().get::<i64>(0).unwrap(),
        2
    );
}

#[tokio::test]
async fn delete_space_unassigns_pages_and_advances_affected_tokens() {
    let (db, _dir) = test_db().await;
    db.create_space("unassign_me", None, false).await.unwrap();
    db.upsert_documents(vec![make_memory_doc(
        "mem_space_unassign_generation",
        "Memory whose scope is being removed",
        "fact",
        "unassign_me",
        "agent",
    )])
    .await
    .unwrap();

    let now = chrono::Utc::now().to_rfc3339();
    db.insert_page_with_kind(
        "page_space_unassign_generation",
        "Unassign Page",
        None,
        "Page whose space and workspace both reference the removed space",
        None,
        Some("unassign_me"),
        &["mem_space_unassign_generation"],
        &now,
        "authored",
        "confirmed",
        Some("unassign_me"),
        None,
    )
    .await
    .unwrap();

    db.delete_space("unassign_me", "unassign").await.unwrap();

    let conn = db.conn.lock().await;
    let mut memory_rows = conn
        .query(
            "SELECT space, version FROM memories
             WHERE source_id = 'mem_space_unassign_generation'
               AND source != 'episode' AND chunk_index = 0",
            (),
        )
        .await
        .unwrap();
    let memory = memory_rows.next().await.unwrap().unwrap();
    // memories.space is NOT NULL since migration 91: unassign folds to the sentinel.
    assert_eq!(
        memory.get::<Option<String>>(0).unwrap(),
        Some(UNFILED_SPACE_ID.to_string())
    );
    assert_eq!(memory.get::<i64>(1).unwrap(), 2);
    drop(memory_rows);

    let mut page_rows = conn
        .query(
            "SELECT space, workspace, version FROM pages
             WHERE id = 'page_space_unassign_generation'",
            (),
        )
        .await
        .unwrap();
    let page = page_rows.next().await.unwrap().unwrap();
    assert_eq!(page.get::<String>(0).unwrap(), UNFILED_SPACE_ID);
    assert_eq!(page.get::<String>(1).unwrap(), UNFILED_SPACE_ID);
    assert_eq!(
        page.get::<i64>(2).unwrap(),
        1,
        "unassigning scope metadata must not advance an active Page content version"
    );
}

