#[tokio::test]
async fn delete_space_unassign_folds_entity_and_shadow_space_to_sentinel() {
    // rework2 ITEM 2 (M3 PR-1) originally left entities.space NULL on
    // unassign while only the kind='entity' shadow's NOT NULL space/workspace
    // folded to the sentinel. G6 Stage 1.5b Part 2 made entities.space fold
    // the same way. G6 Stage 2 PR 2c sub-step 3 item 5: `store_entity` no
    // longer writes `entities` at all (see `store_entity`), so a post-flip
    // entity has no `entities` row to assert the fold against -- the shadow
    // page is now the only canonical space record, and its fold is what this
    // test checks.
    let (db, _dir) = test_db().await;
    db.create_space("old", None, false).await.unwrap();
    let id = db
        .store_entity(
            "Katherine Johnson",
            "person",
            Some("old"),
            Some("test"),
            None,
        )
        .await
        .unwrap();

    db.delete_space("old", "unassign").await.unwrap();

    let conn = db.conn.lock().await;
    let (space, workspace): (String, String) = {
        let mut rows = conn
            .query(
                "SELECT p.space, p.workspace FROM pages p \
                 JOIN entity_page_map m ON m.page_id = p.id \
                 WHERE m.entity_id = ?1 AND p.kind = 'entity'",
                libsql::params![id],
            )
            .await
            .unwrap();
        let row = rows
            .next()
            .await
            .unwrap()
            .expect("shadow page must survive unassign");
        (row.get(0).unwrap(), row.get(1).unwrap())
    };
    assert_eq!(
        space, UNFILED_SPACE_ID,
        "shadow space must fold to the sentinel, not keep the deleted space name"
    );
    assert_eq!(
        workspace, UNFILED_SPACE_ID,
        "shadow workspace must fold to the sentinel"
    );
}

/// G6 Stage 1.5b Part 2 writer-side fold invariant: `store_entity` and
/// `create_entity` must fold `space: None` to `UNFILED_SPACE_ID` at write
/// time, not pass NULL through -- else NULLs recur even after the fold
/// migration backfills existing rows.
#[tokio::test]
async fn store_entity_folds_none_space_to_sentinel_never_null() {
    let (db, _dir) = test_db().await;
    let store_id = db
        .store_entity("Ada Lovelace", "person", None, Some("test"), None)
        .await
        .unwrap();
    let create_id = db
        .create_entity("Grace Hopper", "person", None)
        .await
        .unwrap();

    let conn = db.conn.lock().await;
    let null_count: i64 = {
        let mut rows = conn
            .query(
                "SELECT COUNT(*) FROM pages WHERE kind = 'entity' AND space IS NULL",
                (),
            )
            .await
            .unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert_eq!(
        null_count, 0,
        "no entity shadow page's space may be NULL after a None-space write"
    );

    // G6 Stage 2 PR 2c sub-step 3 item 5 + G6 Stage 3: neither writer touches
    // `entities` any more (the table is gone as of migration 123), so both
    // folds are checked on the shadow page.
    let store_space: String = {
        let mut rows = conn
            .query(
                "SELECT space FROM pages \
                 WHERE kind = 'entity' \
                 AND id = (SELECT page_id FROM entity_page_map WHERE entity_id = ?1)",
                libsql::params![store_id],
            )
            .await
            .unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert_eq!(
        store_space, UNFILED_SPACE_ID,
        "an unfiled entity's shadow page must carry the sentinel, never NULL"
    );

    let create_space: String = {
        let mut rows = conn
            .query(
                "SELECT space FROM pages \
                 WHERE kind = 'entity' \
                 AND id = (SELECT page_id FROM entity_page_map WHERE entity_id = ?1)",
                libsql::params![create_id],
            )
            .await
            .unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert_eq!(
        create_space, UNFILED_SPACE_ID,
        "an unfiled entity must carry the sentinel, never NULL"
    );
}

