// hub filter holds, and the modes behave. Council-validated Tests A/B/C.

/// Minimal base SearchResult for graph-stream tests (source="memory").
fn mk_result(source_id: &str, content: &str, score: f32) -> SearchResult {
    SearchResult {
        id: format!("id_{source_id}"),
        content: content.to_string(),
        source: "memory".to_string(),
        source_id: source_id.to_string(),
        title: String::new(),
        url: None,
        chunk_index: 0,
        last_modified: 0,
        score,
        chunk_type: None,
        language: None,
        semantic_unit: None,
        memory_type: None,
        space: None,
        source_agent: None,
        confidence: None,
        confirmed: None,
        stability: None,
        supersedes: None,
        summary: None,
        entity_id: None,
        entity_name: None,
        quality: None,
        importance: None,
        event_date: None,
        is_archived: false,
        is_recap: false,
        structured_fields: None,
        retrieval_cue: None,
        source_text: None,
        content_hash: None,
        raw_score: 0.0,
        version: 0,
        pending_revision: false,
        merged_from: None,
        last_delta_summary: None,
    }
}

#[tokio::test]
async fn rerank_results_light_reorders_and_truncates() {
    use crate::reranker::Reranker;
    // Scores by position so the LAST candidate wins — proves the helper reorders
    // by CE score, not input order.
    struct RevReranker;
    impl Reranker for RevReranker {
        fn rerank(
            &self,
            _q: &str,
            c: &[(String, String)],
        ) -> Result<Vec<(String, f32)>, WenlanError> {
            Ok(c.iter()
                .enumerate()
                .map(|(i, (id, _))| (id.clone(), i as f32))
                .collect())
        }
        fn model_id(&self) -> &str {
            "rev"
        }
    }
    let results = vec![
        mk_result("a", "alpha", 0.9),
        mk_result("b", "bravo", 0.5),
        mk_result("c", "charlie", 0.1),
    ];
    let out = rerank_results_light(Arc::new(RevReranker), "q", results, 2).await;
    assert_eq!(out.len(), 2, "truncated to limit");
    assert_eq!(out[0].source_id, "c", "highest CE score first");
    assert_eq!(out[1].source_id, "b");
}

#[tokio::test]
async fn rerank_results_light_keeps_order_on_reranker_error() {
    use crate::reranker::Reranker;
    struct ErrReranker;
    impl Reranker for ErrReranker {
        fn rerank(
            &self,
            _q: &str,
            _c: &[(String, String)],
        ) -> Result<Vec<(String, f32)>, WenlanError> {
            Err(WenlanError::Llm("boom".into()))
        }
        fn model_id(&self) -> &str {
            "err"
        }
    }
    let results = vec![
        mk_result("a", "alpha", 0.9),
        mk_result("b", "bravo", 0.5),
        mk_result("c", "charlie", 0.1),
    ];
    let out = rerank_results_light(Arc::new(ErrReranker), "q", results, 2).await;
    // Reranker error -> original order preserved, still truncated to limit.
    assert_eq!(out.len(), 2);
    assert_eq!(out[0].source_id, "a");
    assert_eq!(out[1].source_id, "b");
}

/// Test A — boost-only: graph-ON lifts the concept-linked memory above an
/// unlinked competitor that the base ranked higher; person-linked hub and the
/// unlinked competitor are untouched; no ghost rows, no duplicate source_id.
#[tokio::test]
async fn graph_stream_boost_only_lifts_linked_memory_above_competitor() {
    let (db, _dir) = test_db().await;
    let concept = db
        .store_entity("photosynthesis", "concept", None, None, None)
        .await
        .unwrap();
    let person = db
        .store_entity("Caroline", "person", None, None, None)
        .await
        .unwrap();

    insert_memory_at(
        &db,
        "m_base",
        "base",
        "photosynthesis field notes",
        1,
        1,
        "enriched",
    )
    .await;
    insert_memory_at(
        &db,
        "m_comp",
        "comp",
        "photosynthesis lecture recap",
        1,
        1,
        "enriched",
    )
    .await;
    insert_memory_at(
        &db,
        "m_hub",
        "hub",
        "Caroline weekend plans",
        1,
        1,
        "enriched",
    )
    .await;
    db.link_memory_entities("m_base", &[concept.as_str()])
        .await
        .unwrap();
    db.link_memory_entities("m_hub", &[person.as_str()])
        .await
        .unwrap();

    // RRF-scale base pool: competitor ranks ABOVE the linked memory pre-graph.
    let base = vec![
        mk_result("m_comp", "photosynthesis lecture recap", 1.0 / 60.0),
        mk_result("m_base", "photosynthesis field notes", 1.0 / 61.0),
        mk_result("m_hub", "Caroline weekend plans", 1.0 / 70.0),
    ];
    let comp_before = base[0].score;
    let base_before = base[1].score;

    let out = temp_env::async_with_vars([("WENLAN_GRAPH_MEMORY_STREAM", Some("1"))], async {
        db.augment_with_graph("photosynthesis", base, 10)
            .await
            .unwrap()
    })
    .await;

    assert!(
        out.iter().all(|r| r.source != "knowledge_graph"),
        "stream emits no ghost knowledge_graph rows"
    );
    let mut sids: Vec<&str> = out.iter().map(|r| r.source_id.as_str()).collect();
    let n = sids.len();
    sids.sort();
    sids.dedup();
    assert_eq!(sids.len(), n, "no duplicate source_id");

    let pos = |sid: &str| out.iter().position(|r| r.source_id == sid).unwrap();
    let score = |sid: &str| out.iter().find(|r| r.source_id == sid).unwrap().score;

    assert!(
        score("m_base") > base_before,
        "graph boosted the linked memory"
    );
    assert!(
        pos("m_base") < pos("m_comp"),
        "linked memory now ranks above competitor"
    );
    assert!(
        (score("m_comp") - comp_before).abs() < 1e-6,
        "unlinked competitor unchanged"
    );
    assert!(
        (score("m_hub") - (1.0f32 / 70.0)).abs() < 1e-6,
        "person-linked hub not boosted (anchor filtered by type)"
    );
}

/// Test B — surface-new arm introduces a concept-linked bridge memory that is
