/// Test C — poison guard: an over-cap concept hub is excluded as an anchor
/// (degree > cap), so its memories never surface; a fine concept (degree 1)
/// under the cap DOES surface, proving exclusion is the cause, not silence.
#[tokio::test]
async fn graph_stream_excludes_over_cap_hub_anchor() {
    let (db, _dir) = test_db().await;
    let hub = db
        .store_entity("general topic", "concept", None, None, None)
        .await
        .unwrap();
    let fine = db
        .store_entity("photosynthesis", "concept", None, None, None)
        .await
        .unwrap();
    for sid in ["m_h1", "m_h2", "m_h3"] {
        insert_memory_at(&db, sid, "h", "general topic chatter", 1, 1, "enriched").await;
        db.link_memory_entities(sid, &[hub.as_str()]).await.unwrap();
    }
    insert_memory_at(
        &db,
        "m_fine",
        "f",
        "photosynthesis detail",
        1,
        1,
        "enriched",
    )
    .await;
    db.link_memory_entities("m_fine", &[fine.as_str()])
        .await
        .unwrap();

    let base = vec![mk_result("m_seed", "seed row", 1.0 / 60.0)];

    let out = temp_env::async_with_vars(
        [
            ("WENLAN_GRAPH_MEMORY_STREAM", Some("1")),
            ("WENLAN_GRAPH_SURFACE_NEW", Some("1")),
            ("WENLAN_GRAPH_HUB_CAP", Some("2")),
        ],
        async {
            db.augment_with_graph("general topic photosynthesis", base, 10)
                .await
                .unwrap()
        },
    )
    .await;

    for sid in ["m_h1", "m_h2", "m_h3"] {
        assert!(
            out.iter().all(|r| r.source_id != sid),
            "{sid} must not surface via the over-cap hub anchor"
        );
    }
    assert!(
        out.iter().any(|r| r.source_id == "m_fine"),
        "fine-concept memory surfaces (anchor under cap) — stream is live, not silent"
    );
}

/// G3 touch probe: the eval-side `graph_stream_touches` agrees with the live
/// `augment_with_memory_stream` anchor logic because both share
/// `stream_anchor_ids` (one source of truth, cannot drift). Three fixtures:
/// A — linked under-cap concept => probe true; B — unlinked fresh DB =>
/// probe false; C — same as A but the anchor degree is pushed OVER the hub
/// cap, so the shared filter drops it => probe false (drift guard: if the
/// probe ever stopped filtering hubs the live stream does, C would go red).
#[tokio::test]
async fn plan_graph_stream_touches_probe_agrees_with_stream() {
    // Fixture A — linked, under-cap, non-person anchor => probe true.
    {
        let (db, _dir) = test_db().await;
        let concept = db
            .store_entity("photosynthesis", "concept", None, None, None)
            .await
            .unwrap();
        insert_memory_at(
            &db,
            "m_link",
            "linked",
            "photosynthesis field notes",
            1,
            1,
            "enriched",
        )
        .await;
        db.link_memory_entities("m_link", &[concept.as_str()])
            .await
            .unwrap();
        assert!(
            db.graph_stream_touches("photosynthesis", 10).await.unwrap(),
            "fixture A: under-cap concept-linked memory must be touched by the stream probe"
        );
    }

    // Fixture B — fresh DB, one unlinked memory => probe false.
    {
        let (db, _dir) = test_db().await;
        insert_memory_at(
            &db,
            "m_orphan",
            "orphan",
            "photosynthesis field notes",
            1,
            1,
            "enriched",
        )
        .await;
        assert!(
            !db.graph_stream_touches("photosynthesis", 10).await.unwrap(),
            "fixture B: an unlinked memory has no anchor — probe must be false"
        );
    }

    // Fixture C — drift guard: anchor degree pushed OVER the hub cap, so the
    // SHARED anchor filter drops it exactly as the live stream would.
    {
        let (db, _dir) = test_db().await;
        let concept = db
            .store_entity("photosynthesis", "concept", None, None, None)
            .await
            .unwrap();
        // Three distinct memories linked to the one concept => degree 3 > cap 2.
        for sid in ["m_c1", "m_c2", "m_c3"] {
            insert_memory_at(
                &db,
                sid,
                "c",
                "photosynthesis field notes",
                1,
                1,
                "enriched",
            )
            .await;
            db.link_memory_entities(sid, &[concept.as_str()])
                .await
                .unwrap();
        }
        let touched = temp_env::async_with_vars([("WENLAN_GRAPH_HUB_CAP", Some("2"))], async {
            db.graph_stream_touches("photosynthesis", 10).await.unwrap()
        })
        .await;
        assert!(
            !touched,
            "fixture C: over-cap anchor is filtered like the stream filters it — probe false"
        );
    }
}

// ===== G4 standalone capability-liveness gate =====
// Eval-Trust v3 G4: per shipped retrieval capability, does flipping it ON
// actually change the FINAL public output via the shipped path? A capability
// whose OFF and ON outputs are indistinguishable is merged-but-inert — the
// boost-then-strip ghost (augment_with_graph adds source="knowledge_graph"
// rows at db.rs:~8420 that the retain() at db.rs:8524 strips). The temporal
// and page probes run the shipped CE-pool path `search_memory_cross_rerank_cued`
// (reranker=None → CE pass skipped → base pool; the page channel + strip live
// there). The graph-stream probe instead runs the shipped quick path
// `search_memory` — under a LIVE CE rescore the CE pool fetch hard-skips the
// stream (reranker.is_none() == false), so the quick path is where the stream
// actually rides and the only honest probe for its liveness. No GPU; needs
// only the CI-cached BGE embedder. Covered here: temporal (reorder), page
// (membership), legacy-graph (negative control), graph-stream (live).
// Episode/fact + the LLM-tier decompose probe are follow-ups.

/// Run the shipped CE-pool path with `flag` set to `off_val` then ON, holding
/// `cue` fixed in both arms. Returns (off_results, on_results). Caller seeds the
/// substrate and asserts the capability's contribution reaches the final Vec.
/// `off_val` is `None` (unset) for opt-in flags. Used by the temporal + page
/// probes; the graph-stream probe drives the quick path directly (the CE pool
/// fetch only carries the stream when reranker.is_none(), so toggling the
/// stream flag here would not isolate it).
async fn g4_probe(
    db: &MemoryDB,
    query: &str,
    limit: usize,
    flag: &str,
    off_val: Option<&str>,
    cue: Option<crate::temporal_query::DateRange>,
) -> (Vec<SearchResult>, Vec<SearchResult>) {
    let off = temp_env::async_with_vars([(flag, off_val)], async {
        db.search_memory_cross_rerank_cued(query, limit, None, &ReadScope::Global, None, cue, None)
            .await
            .expect("g4_probe OFF arm")
    })
    .await;
    let on = temp_env::async_with_vars([(flag, Some("1"))], async {
        db.search_memory_cross_rerank_cued(query, limit, None, &ReadScope::Global, None, cue, None)
            .await
            .expect("g4_probe ON arm")
    })
    .await;
    (off, on)
}

/// G4 temporal: the soft boost is the LME-S lever whose aggregate eval null is
/// suspected DEAD-TRIGGER (extract_cue fires <1% on real NL) rather than a
/// genuine neutral. This probe injects the cue DIRECTLY (bypassing extract_cue)
/// so it certifies the boost MECHANISM is live: an in-window dated row is lifted
/// ×(1+bonus) while an undated row stays neutral. Red here = the boost can't
/// move output even when a cue is present (a real ghost, not a dead trigger).
#[tokio::test]
async fn g4_temporal_boost_is_live() {
    let (db, _dir) = test_db().await;
    // Two rows the query retrieves; distinct text (sharing the query terms)
    // so the near-duplicate dedup at db.rs:8487 keeps both — only event_date
    // differs in what the boost can act on.
    db.upsert_documents(vec![
        make_memory_doc(
            "t_dated",
            "alpha launch milestone shipped to production",
            "knowledge",
            "work",
            "tester",
        ),
        make_memory_doc(
            "t_undated",
            "alpha launch milestone roadmap discussion draft",
            "knowledge",
            "work",
            "tester",
        ),
    ])
    .await
    .unwrap();

    // A single day in 2024; place t_dated's event_date inside it.
    let start = 1_704_067_200_i64; // 2024-01-01T00:00:00Z
    let end = 1_704_153_599_i64; //   2024-01-01T23:59:59Z
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "UPDATE memories SET event_date = ?1 WHERE source_id = ?2",
            libsql::params![start + 3600, "t_dated"],
        )
        .await
        .unwrap();
    }

    let cue = Some(crate::temporal_query::DateRange { start, end });
    let (off, on) = g4_probe(
        &db,
        "alpha launch milestone",
        5,
        "WENLAN_ENABLE_TEMPORAL_SOFT_BOOST",
        None, // opt-in flag: OFF = unset
        cue,
    )
    .await;

    let score =
        |v: &[SearchResult], sid: &str| v.iter().find(|r| r.source_id == sid).map(|r| r.score);
    let dated_off = score(&off, "t_dated").expect("t_dated retrieved OFF");
    let dated_on = score(&on, "t_dated").expect("t_dated retrieved ON");
    let undated_off = score(&off, "t_undated").expect("t_undated retrieved OFF");
    let undated_on = score(&on, "t_undated").expect("t_undated retrieved ON");

    // Ratio cancels the shared base (incl. sub-ms recency drift between runs).
    let dated_ratio = dated_on / dated_off;
    let undated_ratio = undated_on / undated_off;
    assert!(
        dated_ratio > 1.4,
        "G4 temporal DEAD: in-window row boost ratio {dated_ratio:.3} (expected ~1.5 = 1+bonus); the boost did not reach the shipped output"
    );
    assert!(
        (undated_ratio - 1.0).abs() < 0.02,
        "undated row must stay neutral: ratio {undated_ratio:.3}"
    );
}

