#[tokio::test]
async fn accepted_page_merge_advances_survivor_source_revision() {
    let (db, _dir) = test_db().await;
    let now = chrono::Utc::now().to_rfc3339();
    db.insert_page(
        "page-merge-revision-survivor",
        "Merge survivor",
        None,
        "Survivor body",
        None,
        None,
        &["source-survivor"],
        &now,
    )
    .await
    .unwrap();
    db.insert_page(
        "page-merge-revision-absorbed",
        "Merge absorbed",
        None,
        "Absorbed body",
        None,
        None,
        &["source-absorbed"],
        &now,
    )
    .await
    .unwrap();
    db.insert_refinement_proposal(
        "proposal-merge-revision",
        "page_merge",
        &[
            "page-merge-revision-survivor".to_string(),
            "page-merge-revision-absorbed".to_string(),
        ],
        None,
        1.0,
    )
    .await
    .unwrap();

    db.accept_page_merge(
        "proposal-merge-revision",
        "page-merge-revision-survivor",
        "page-merge-revision-absorbed",
    )
    .await
    .unwrap();

    assert_eq!(
        db.get_page_source_revision("page-merge-revision-survivor")
            .await
            .unwrap(),
        1
    );
    let survivor = db
        .get_page("page-merge-revision-survivor")
        .await
        .unwrap()
        .unwrap();
    let absorbed = db
        .get_page("page-merge-revision-absorbed")
        .await
        .unwrap()
        .unwrap();
    let survivor_history = db
        .list_page_history("page-merge-revision-survivor", 10)
        .await
        .unwrap();
    let absorbed_history = db
        .list_page_history("page-merge-revision-absorbed", 10)
        .await
        .unwrap();
    assert_eq!(
        survivor_history.first().map(|entry| entry.version),
        Some(survivor.version)
    );
    assert_eq!(
        absorbed_history.first().map(|entry| entry.version),
        Some(absorbed.version)
    );
    assert_eq!(
        survivor_history
            .first()
            .map(|entry| entry.edited_by.as_str()),
        Some("page_merge")
    );
    assert_eq!(
        absorbed_history
            .first()
            .map(|entry| entry.edited_by.as_str()),
        Some("archive")
    );
    assert_eq!(survivor.stale_reason.as_deref(), Some("source_updated"));
    assert_eq!(
        survivor
            .source_memory_ids
            .into_iter()
            .collect::<HashSet<_>>(),
        HashSet::from(["source-survivor".to_string(), "source-absorbed".to_string()])
    );
}

#[tokio::test]
async fn test_get_concept_sources_ordered() {
    let (db, _dir) = test_db().await;
    let now = chrono::Utc::now().to_rfc3339();

    db.insert_page(
        "c_ord",
        "Ordering test",
        None,
        "content",
        None,
        None,
        &[],
        &now,
    )
    .await
    .unwrap();

    // Insert two memories.
    db.upsert_documents(vec![make_memory_doc(
        "src_a",
        "Alpha content",
        "knowledge",
        "work",
        "agent",
    )])
    .await
    .unwrap();
    db.upsert_documents(vec![make_memory_doc(
        "src_b",
        "Beta content",
        "knowledge",
        "work",
        "agent",
    )])
    .await
    .unwrap();

    // Manually insert with controlled linked_at values so order is deterministic.
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "INSERT OR IGNORE INTO page_sources (page_id, memory_source_id, linked_at, link_reason) VALUES (?1, ?2, ?3, ?4)",
            libsql::params!["c_ord", "src_b", 200i64, "later"],
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT OR IGNORE INTO page_sources (page_id, memory_source_id, linked_at, link_reason) VALUES (?1, ?2, ?3, ?4)",
            libsql::params!["c_ord", "src_a", 100i64, "earlier"],
        )
        .await
        .unwrap();
        // G6 Stage 1.3: `get_page_sources` reads `edges`, ordering by
        // `COALESCE(json_extract(payload,'$.linked_at'), created_at)` -- mirror
        // the dual-write here (payload carries the controlled linked_at so
        // ordering stays deterministic), same pattern as the retro-scan fixture.
        for (memory_source_id, linked_at, link_reason) in
            [("src_b", 200i64, "later"), ("src_a", 100i64, "earlier")]
        {
            conn.execute(
                "INSERT INTO edges (edge_id, src_id, src_kind, dst_id, dst_kind, edge_type, \
                                     lineage, grounded, space, created_at, payload) \
                 VALUES (?1, 'c_ord', 'page', ?2, 'memory', 'cites', 'legacy', 0, ?5, ?3, ?4)",
                libsql::params![
                    format!("concept-sources-ordered-{memory_source_id}"),
                    memory_source_id,
                    linked_at,
                    serde_json::json!({"linked_at": linked_at, "link_reason": link_reason})
                        .to_string(),
                    crate::db::UNFILED_SPACE_ID,
                ],
            )
            .await
            .unwrap();
        }
    }

    let sources = db.get_page_sources("c_ord").await.unwrap();
    assert_eq!(sources.len(), 2);
    // Should be ordered by linked_at ASC: src_a first, src_b second.
    assert_eq!(sources[0].memory_source_id, "src_a");
    assert_eq!(sources[1].memory_source_id, "src_b");
}

