#[tokio::test]
async fn test_upsert_memory_in_place_updates_version() {
    let (db, _dir) = test_db().await;
    let doc = make_memory_doc(
        "mem_uip",
        "Original content for upsert test.",
        "knowledge",
        "work",
        "agent",
    );
    db.upsert_documents(vec![doc]).await.unwrap();

    // Compute an embedding for the new content.
    let new_content = "Updated content after in-place upsert.";
    let embedding = db
        .generate_embeddings(&[new_content.to_string()])
        .unwrap()
        .into_iter()
        .next()
        .unwrap();

    db.upsert_memory_in_place(
        "mem_uip",
        new_content,
        &embedding,
        Some("test-agent"),
        None,
        50,
    )
    .await
    .unwrap();

    // Verify content and version via direct DB query.
    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT content, version FROM memories WHERE source_id = 'mem_uip' AND chunk_index = 0",
            (),
        )
        .await
        .unwrap();
    let row = rows.next().await.unwrap().expect("row should exist");
    let content: String = row.get(0).unwrap();
    let version: i64 = row.get(1).unwrap();

    assert_eq!(content, new_content, "content should be updated");
    assert_eq!(version, 2, "version should be incremented to 2");
}

#[tokio::test]
async fn test_upsert_memory_in_place_invalidates_entity_projection() {
    let (db, _dir) = test_db().await;
    db.upsert_documents(vec![make_memory_doc(
        "mem_uip_entity",
        "Original linked entity content.",
        "knowledge",
        "work",
        "agent",
    )])
    .await
    .unwrap();
    assert!(db
        .commit_entity_enrichment_at_version(
            "mem_uip_entity",
            1,
            &extracted_entity("In-place Old Entity", "concept"),
            "In-place Old Entity",
        )
        .await
        .unwrap());
    let new_content = "Replacement content needs a fresh entity projection.";
    let embedding = db
        .generate_embeddings(&[new_content.to_string()])
        .unwrap()
        .into_iter()
        .next()
        .unwrap();

    db.upsert_memory_in_place("mem_uip_entity", new_content, &embedding, None, None, 50)
        .await
        .unwrap();

    assert_eq!(
        db.get_memory_entity_id("mem_uip_entity").await.unwrap(),
        None
    );
    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT COUNT(*) FROM memory_entities
             WHERE memory_id = 'mem_uip_entity'",
            (),
        )
        .await
        .unwrap();
    assert_eq!(
        rows.next().await.unwrap().unwrap().get::<i64>(0).unwrap(),
        0
    );
    drop(rows);
    drop(conn);
    assert_eq!(
        db.run_entity_enrichment_slice(|content| async move {
            assert_eq!(content, new_content);
            Ok(Vec::new())
        })
        .await
        .unwrap(),
        1
    );
}

