// `merge_entities_cleans_dangling_aliases_before_delete` retired at G6
// Stage 3. Its subject was `merge_entities` clearing `entity_aliases` rows
// that still pointed at the merge loser before the loser's `entities` row was
// deleted -- an ordering constraint imposed by the alias table's foreign key.
// Migration 123 dropped `entity_aliases`; aliases live in the winner's shadow
// page `aliases` JSON, which `merge_entities_registers_alias_name` covers via
// `resolve_entity_by_alias`. There is no dangling row left to clean.

#[tokio::test]
async fn merge_entities_idempotent() {
    let (db, _tmp) = test_db().await;
    let (canonical, alias) = seed_two_entities(&db).await;
    db.merge_entities(&canonical, &alias).await.unwrap();
    db.merge_entities(&canonical, &alias).await.unwrap();

    // Verify exact state: canonical still exists, alias still gone, exactly one
    // 'merge' alias row for "Acme Corporation"
    let conn = db.conn.lock().await;

    let mut rows = conn
        .query(
            "SELECT COUNT(*) FROM entity_page_map WHERE entity_id = ?1",
            libsql::params![canonical.clone()],
        )
        .await
        .unwrap();
    let count: i64 = rows.next().await.unwrap().unwrap().get(0).unwrap();
    assert_eq!(
        count, 1,
        "canonical should remain exactly once after idempotent calls"
    );

    let mut rows = conn
        .query(
            "SELECT COUNT(*) FROM entity_page_map WHERE entity_id = ?1",
            libsql::params![alias.clone()],
        )
        .await
        .unwrap();
    let count: i64 = rows.next().await.unwrap().unwrap().get(0).unwrap();
    assert_eq!(
        count, 0,
        "alias should remain deleted after idempotent calls"
    );

    drop(conn);
    // G6 Stage 2 PR 2c sub-step 3 item 4: the merge-source alias row is
    // retired -- assert the page-payload UNION stayed idempotent instead
    // (exactly one "acme corporation" entry, not duplicated by the repeat
    // merge call).
    let aliases = shadow_aliases(&db, &canonical).await.unwrap();
    let parsed: Vec<String> = serde_json::from_str(&aliases).unwrap();
    let occurrences = parsed
        .iter()
        .filter(|a| a.as_str() == "acme corporation")
        .count();
    assert_eq!(
        occurrences, 1,
        "the UNION-based alias write must stay idempotent across repeat merges: {aliases}"
    );
}

