/// Contract test for Task 11: `apply_enrichment` must persist
/// `event_date` and `event_end` to the `memories` table so the
/// extracted temporal fields survive the async enrichment phase.
#[tokio::test]
async fn test_store_memory_persists_event_date_and_end() {
    let (db, _dir) = test_db().await;
    let doc = make_memory_doc(
        "mem_evt",
        "Alice attended the PyCon conference from 2026-04-22 to 2026-04-23",
        "event",
        "work",
        "claude",
    );
    db.upsert_documents(vec![doc]).await.unwrap();

    // Simulates the async enrichment path that has the extracted values.
    db.apply_enrichment(
        "mem_evt",
        "event",
        None,
        None,
        "hide",
        None,
        None,
        Some(1779667200i64), // event_date
        Some(1779753599i64), // event_end
        None,
    )
    .await
    .unwrap();

    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT event_date, event_end FROM memories WHERE source_id = 'mem_evt' LIMIT 1",
            (),
        )
        .await
        .unwrap();
    let row = rows.next().await.unwrap().unwrap();
    let stored_date: Option<i64> = row.get(0).unwrap();
    let stored_end: Option<i64> = row.get(1).unwrap();
    assert_eq!(
        stored_date,
        Some(1779667200i64),
        "event_date must be persisted"
    );
    assert_eq!(
        stored_end,
        Some(1779753599i64),
        "event_end must be persisted"
    );
}

#[tokio::test]
async fn reassign_memories_space_rejects_unregistered_destination() {
    let (db, _td) = test_db().await;

    db.create_space("src", None, false).await.unwrap();

    let doc = make_memory_doc(
        "mem_autocreate_1",
        "Memory in src.",
        "knowledge",
        "src",
        "agent",
    );
    db.upsert_documents(vec![doc]).await.unwrap();

    let err = db
        .reassign_memories_space("src", "baz")
        .await
        .expect_err("move must reject an unregistered destination space");
    assert!(
        err.to_string().contains("destination space not found"),
        "unexpected error: {err}"
    );

    let source_count = db
        .list_memories(Some("src"), None, None, None, 10)
        .await
        .unwrap()
        .len();
    assert!(
        source_count >= 1,
        "failed move must leave source memories in place"
    );
    assert!(
        db.get_space("baz").await.unwrap().is_none(),
        "failed move must not auto-create destination space"
    );
}

