/// KG close plan G5: migration 113 repairs the entities #473's sweep already
/// wrote without shadow pages. Simulate the damage (a mapped-page-less
/// entity, the live drift shape), run the migration, and the parity sweep
/// must come back clean — the repaired shadow byte-identical in shape to a
/// live dual-written one, aliases folded in.
#[tokio::test]
async fn migration_113_backfills_missing_entity_shadow_pages() {
    let (db, _dir) = test_db().await;
    // G6 Stage 3: migration 113's body is a FROZEN replay that reads
    // `entities` and `entity_aliases`, and migration 123 has dropped both by
    // the time `test_db()` returns. Recreate them at their user_version-122
    // shape -- exactly what `ensure_legacy_entities_table` does for a real
    // pre-123 database -- so the frozen body replays against the substrate it
    // was specified against.
    db.test_create_legacy_entity_tables().await.unwrap();
    let eid = db
        .store_entity("Orphan", "concept", Some("work"), None, None)
        .await
        .unwrap();
    {
        let conn = db.conn.lock().await;
        // G6 Stage 2 PR 2c sub-step 3 item 5: `store_entity` no longer writes
        // `entities`, and migration 113 backfills a shadow FOR an existing
        // legacy row -- so seed the row store_entity used to write pre-flip.
        conn.execute(
            "INSERT INTO entities \
                 (id, name, entity_type, space, confidence, confirmed, created_at, updated_at) \
             VALUES (?1, 'Orphan', 'concept', 'work', NULL, 0, 1, 1)",
            libsql::params![eid.clone()],
        )
        .await
        .unwrap();
        conn.execute(
            "DELETE FROM pages WHERE id = \
             (SELECT page_id FROM entity_page_map WHERE entity_id = ?1)",
            libsql::params![eid.clone()],
        )
        .await
        .unwrap();
        conn.execute(
            "DELETE FROM entity_page_map WHERE entity_id = ?1",
            libsql::params![eid.clone()],
        )
        .await
        .unwrap();
    }
    // G6 Stage 2 PR 2c sub-step 3 item 6: `compute_entity_page_parity_report`
    // retired -- assert the simulated damage (no live shadow/map row for
    // `eid`) and the post-migration repair directly against
    // `pages`/`entity_page_map` instead.
    async fn shadow_exists(db: &MemoryDB, eid: &str) -> bool {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT COUNT(*) FROM entity_page_map m \
                 JOIN pages p ON p.id = m.page_id \
                 WHERE m.entity_id = ?1 AND p.kind = 'entity' AND p.status = 'active'",
                libsql::params![eid],
            )
            .await
            .unwrap();
        let count: i64 = rows.next().await.unwrap().unwrap().get(0).unwrap();
        count > 0
    }
    assert!(
        !shadow_exists(&db, &eid).await,
        "the simulated damage must leave no live shadow page"
    );

    db.migrate_113_entity_shadow_page_repair(112).await.unwrap();

    assert!(
        shadow_exists(&db, &eid).await,
        "migration 113 must repair the missing shadow"
    );
    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT p.title, p.entity_type, p.space FROM entity_page_map m \
             JOIN pages p ON p.id = m.page_id \
             WHERE m.entity_id = ?1 AND p.kind = 'entity' AND p.status = 'active'",
            libsql::params![eid.clone()],
        )
        .await
        .unwrap();
    let row = rows.next().await.unwrap().unwrap();
    let title: String = row.get(0).unwrap();
    let entity_type: String = row.get(1).unwrap();
    let space: String = row.get(2).unwrap();
    assert_eq!(title, "Orphan");
    assert_eq!(entity_type, "concept");
    assert_eq!(space, "work");
}

/// G6 Stage 2 PR 2c, independent-review finding 1: migration 113's body is a
/// FROZEN replay, so it must produce the same side effects it produced when it
/// shipped, not merely the same end state in `pages`. Migration 96 creates
/// `m4_page_community_page_insert_input` (AFTER INSERT ON pages),
/// `m4_page_community_page_invalidate` (AFTER UPDATE OF ... space, embedding
/// ... ON pages) and `m4_page_community_map_insert_invalidate` (AFTER INSERT ON
/// entity_page_map), all live by the time 113 replays -- so the community-route
/// generations 113 leaves behind depend on the exact column values it writes,
/// not just on the row it ends up with.
///
/// This is a golden differential rather than a hand-computed expectation: the
/// historical body is replayed inline against one database, the shipped
/// migration against an identically damaged one, and the complete
/// community-routing state must match. Seeding a placeholder row (NULL space
/// folding to the unfiled sentinel, NULL embedding) and repairing it by UPDATE
/// fails this -- it mints an unfiled-sentinel route row the historical replay
/// never created and bumps the repaired page's own route generation off the
/// value a direct insert leaves.
#[tokio::test]
async fn migration_113_repair_matches_historical_community_routing_side_effects() {
    /// The damage migration 113 exists to repair: an `entities` row whose
    /// shadow page and map row are both missing.
    /// A fixed id, so the two databases agree on the key the page-routing
    /// fingerprint is read by (`store_entity` mints a random uuid).
    const ORPHAN: &str = "ent-orphan-m113";

    async fn seed_unmapped_entity(db: &MemoryDB) {
        // An anchor entity written the normal way, so the 'work' space already
        // carries community-route state before the migration runs -- otherwise
        // the trigger arms that bump an EXISTING row would go unexercised.
        db.store_entity("Anchor", "concept", Some("work"), None, None)
            .await
            .unwrap();
        // MUST stay a raw `entities` row with NO shadow page and NO map row:
        // that absence IS the damage migration 113 repairs, so seeding via
        // `test_seed_entity_shadow_page` would leave the migration nothing to
        // do and make this golden differential vacuous. G6 Stage 3 dropped
        // `entities` (migration 123), so the pre-123 substrate the frozen body
        // reads is stood back up first.
        db.test_create_legacy_entity_tables().await.unwrap();
        let conn = db.conn.lock().await;
        conn.execute(
            "INSERT INTO entities (id, name, entity_type, space, created_at, updated_at) \
             VALUES (?1, 'Orphan', 'concept', 'work', unixepoch(), unixepoch())",
            libsql::params![ORPHAN],
        )
        .await
        .unwrap();
    }

    /// Every community-routing generation the m4 triggers maintain. Page rows
    /// are keyed by their entity id, not the random page id, so two
    /// independently repaired databases are comparable.
    async fn routing_fingerprint(
        db: &MemoryDB,
    ) -> (Vec<(String, i64)>, Vec<(String, String, i64)>) {
        let conn = db.conn.lock().await;
        let mut spaces = Vec::new();
        let mut rows = conn
            .query(
                "SELECT space, generation FROM community_route_space_inputs ORDER BY space",
                (),
            )
            .await
            .unwrap();
        while let Some(row) = rows.next().await.unwrap() {
            spaces.push((row.get::<String>(0).unwrap(), row.get::<i64>(1).unwrap()));
        }
        drop(rows);
        let mut pages = Vec::new();
        let mut rows = conn
            .query(
                "SELECT m.entity_id, r.space, r.generation \
                   FROM page_community_route_inputs r \
                   JOIN entity_page_map m ON m.page_id = r.page_id \
                  WHERE m.entity_id = ?1 \
                  ORDER BY m.entity_id",
                libsql::params![ORPHAN],
            )
            .await
            .unwrap();
        while let Some(row) = rows.next().await.unwrap() {
            pages.push((
                row.get::<String>(0).unwrap(),
                row.get::<String>(1).unwrap(),
                row.get::<i64>(2).unwrap(),
            ));
        }
        (spaces, pages)
    }

    // WAY A -- migration 113 exactly as it shipped, replayed inline. The two
    // statements are `insert_entity_shadow_page`'s and
    // `update_entity_shadow_page`'s pre-G6 bodies; both helpers have since
    // been rewritten for live callers, which is precisely why the frozen
    // replay is pinned here rather than routed back through them.
    let (db_historical, _dir_historical) = test_db().await;
    seed_unmapped_entity(&db_historical).await;
    {
        let conn = db_historical.conn.lock().await;
        let now_iso = chrono::Utc::now().to_rfc3339();
        let page_id = crate::pages::new_page_id();
        conn.execute(
            "INSERT INTO pages (
                id, title, summary, content, kind, entity_type, confidence, entity_confirmed,
                embedding, space, workspace, source_memory_ids, version, status,
                created_at, last_compiled, last_modified, creation_kind, review_status
             )
             SELECT ?1, name, NULL, '', 'entity', entity_type, confidence, confirmed,
                    embedding, COALESCE(space, ?2), COALESCE(space, ?2), '[]', 1, 'active',
                    ?3, ?3, ?3, 'entity', 'unconfirmed'
             FROM entities WHERE id = ?4",
            libsql::params![
                page_id.as_str(),
                crate::db::UNFILED_SPACE_ID,
                now_iso.as_str(),
                ORPHAN
            ],
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO entity_page_map (entity_id, page_id, created_at) VALUES (?1, ?2, ?3)",
            libsql::params![ORPHAN, page_id.as_str(), now_iso.as_str()],
        )
        .await
        .unwrap();
        conn.execute(
            "UPDATE pages SET
                title = (SELECT name FROM entities WHERE id = ?1),
                entity_type = (SELECT entity_type FROM entities WHERE id = ?1),
                confidence = (SELECT confidence FROM entities WHERE id = ?1),
                entity_confirmed = (SELECT confirmed FROM entities WHERE id = ?1),
                embedding = (SELECT embedding FROM entities WHERE id = ?1),
                space = COALESCE((SELECT space FROM entities WHERE id = ?1), ?2),
                workspace = COALESCE((SELECT space FROM entities WHERE id = ?1), ?2),
                aliases = (SELECT json_group_array(alias_name)
                           FROM (SELECT alias_name FROM entity_aliases
                                 WHERE canonical_entity_id = ?1 ORDER BY alias_name)),
                source_agent = (SELECT source_agent FROM entities WHERE id = ?1),
                entity_created_at = (SELECT created_at FROM entities WHERE id = ?1),
                entity_updated_at = (SELECT updated_at FROM entities WHERE id = ?1),
                community_id = (SELECT community_id FROM entities WHERE id = ?1),
                embedding_updated_at = (SELECT embedding_updated_at FROM entities WHERE id = ?1),
                last_modified = ?3
             WHERE kind = 'entity'
               AND id = (SELECT page_id FROM entity_page_map WHERE entity_id = ?1)",
            libsql::params![ORPHAN, crate::db::UNFILED_SPACE_ID, now_iso.as_str()],
        )
        .await
        .unwrap();
    }

    // WAY B -- the shipped migration against identical damage.
    let (db_shipped, _dir_shipped) = test_db().await;
    seed_unmapped_entity(&db_shipped).await;
    db_shipped
        .migrate_113_entity_shadow_page_repair(112)
        .await
        .unwrap();

    let (spaces_historical, pages_historical) = routing_fingerprint(&db_historical).await;
    let (spaces_shipped, pages_shipped) = routing_fingerprint(&db_shipped).await;

    assert_eq!(
        spaces_historical, spaces_shipped,
        "migration 113 must leave the same per-space community-route generations \
         as its historical body"
    );
    assert_eq!(
        pages_historical, pages_shipped,
        "migration 113 must leave the same per-page community-route generations \
         as its historical body"
    );
}

/// KG close plan G5: migration 114 repairs shadows the pre-fix sweep left
/// STALE — an alias inserted onto an existing entity without the shadow
/// re-sync drifts the mirrored `aliases` column (`corrupt` in the parity
/// report, observed live 2026-08-04). Simulate that damage, run the
/// migration, and the parity sweep must come back clean.
///
/// G6 Stage 2 PR 2c sub-step 3 item 4: the alias leg retired from
/// `compute_entity_page_parity_report` (`entity_aliases` stopped being
/// written), so the pre-migration "stale" state below is no longer visible
/// to `drift_count` — it was the ONLY drift this scenario produced (every
/// other shadowed field was already in sync). Assert the staleness directly
/// against `pages.aliases` instead; the migration body itself is frozen
/// historical replay and still re-derives `aliases` from `entity_aliases`
/// (the table still exists, just un-written by live code), so the raw seed
/// + resync behavior under test is unchanged.
#[tokio::test]
async fn migration_114_resyncs_stale_entity_shadow_pages() {
    let (db, _dir) = test_db().await;
    // G6 Stage 3: migration 114's body is a FROZEN replay that re-derives the
    // shadow from `entities` + `entity_aliases`, both dropped by migration
    // 123. Recreate them at their user_version-122 shape, exactly as
    // `ensure_legacy_entities_table` does for a real pre-123 database.
    db.test_create_legacy_entity_tables().await.unwrap();
    let eid = db
        .store_entity("Quality Gate", "concept", Some("work"), None, None)
        .await
        .unwrap();
    {
        let conn = db.conn.lock().await;
        // G6 Stage 2 PR 2c sub-step 3 item 5: `store_entity` no longer writes
        // `entities`, but `entity_aliases.canonical_entity_id` still FKs to
        // it and 114 re-derives from it -- seed the row store_entity used to
        // write pre-flip. `store_entity` already created the shadow page this
        // migration resyncs, so there is no second shadow seed here.
        conn.execute(
            "INSERT INTO entities \
                 (id, name, entity_type, space, confidence, confirmed, created_at, updated_at) \
             VALUES (?1, 'Quality Gate', 'concept', 'work', NULL, 0, 1, 1)",
            libsql::params![eid.clone()],
        )
        .await
        .unwrap();
        // A raw alias insert without update_entity_shadow_page — the exact
        // pre-fix sweep behavior.
        conn.execute(
            "INSERT INTO entity_aliases (alias_name, canonical_entity_id, created_at, source) \
             VALUES ('quality gates', ?1, unixepoch(), 'minhash')",
            libsql::params![eid.clone()],
        )
        .await
        .unwrap();
    }
    let stale_aliases = shadow_aliases(&db, &eid).await.unwrap_or_default();
    assert!(
        !stale_aliases.contains("quality gates"),
        "the shadow must still be stale before the migration runs: {stale_aliases}"
    );

    db.migrate_114_entity_shadow_resync(113).await.unwrap();

    let resynced_aliases = shadow_aliases(&db, &eid).await.unwrap_or_default();
    assert!(
        resynced_aliases.contains("quality gates"),
        "migration 114 must re-sync the stale alias: {resynced_aliases}"
    );
    // G6 Stage 2 PR 2c sub-step 3 item 6: the trailing full-report parity
    // assertion retired along with `compute_entity_page_parity_report` --
    // this migration's only job is the alias resync already checked above;
    // no other field was perturbed by the seeded damage, so there is
    // nothing left for a broader check to cover.
}

/// G6 Stage 1 (one source of truth, spec
/// docs/plans/2026-08-05-g6-edge-semantic-payload-spec.md): migration 115
/// backfills the semantic fields the dual-writes never carried —
/// `relation_type` onto `edges.semantic_type` (plus confidence /
/// explanation / source_agent in the payload), the `page_links` display
/// label, and source_kind / linked_at / link_reason / title for cites
/// edges — re-deriving each content-addressed edge id from its live legacy
/// row. The loop runs the migration twice: the second pass must land the
/// identical end-state (probe skips the ALTER, merges re-apply the same
/// values).
#[tokio::test]
async fn migration_115_backfills_edge_semantic_payload() {
    let (db, _dir) = test_db().await;

    // relates — live path (post-#486, dual-writes the edge with a
    // `relates_semantic_patch` payload -- `asserted_at` always, plus
    // `source_memory_id` when supplied -- never payload=NULL).
    let from = db
        .store_entity("Alice", "person", Some("work"), None, None)
        .await
        .unwrap();
    let to = db
        .store_entity("ProjectX", "project", Some("work"), None, None)
        .await
        .unwrap();
    db.create_relation(
        &from,
        &to,
        "works_on",
        Some("agent_smith"),
        Some(0.9),
        Some("seen in standup"),
        None,
    )
    .await
    .unwrap();

    // cites (memory + external) and links — live paths.
    let now = chrono::Utc::now().to_rfc3339();
    db.insert_page(
        "page_g6_sem",
        "Semantic Source",
        None,
        "content",
        None,
        None,
        &[],
        &now,
    )
    .await
    .unwrap();
    db.insert_page(
        "page_g6_sem_dst",
        "Semantic Target",
        None,
        "content",
        None,
        None,
        &[],
        &now,
    )
    .await
    .unwrap();
    let doc = make_memory_doc("mem_g6_sem", "Some content.", "knowledge", "work", "agent");
    db.upsert_documents(vec![doc]).await.unwrap();
    db.link_page_source("page_g6_sem", "mem_g6_sem", "distill")
        .await
        .unwrap();
    db.link_page_evidence(
        "page_g6_sem",
        "external_url",
        Some("https://example.com/doc"),
        Some("Example Doc"),
        "cited",
    )
    .await
    .unwrap();
    db.replace_page_links(
        "page_g6_sem",
        &[crate::synthesis::wikilinks::Wikilink {
            label: "Semantic Target".to_string(),
            target_page_id: Some("page_g6_sem_dst".to_string()),
        }],
    )
    .await
    .unwrap();
    // G6 Stage 2 PR 2b: parity oracle retired, correctness carried by per-writer regression tests (item 7).

    // Read the STORED discriminator back (create_relation normalizes the
    // relation type) so the test derives the relates edge id exactly the
    // way the migration does. G6 Stage 2 PR 2b: `create_relation` no longer
    // writes `relations` -- read the live `relates` edge's `semantic_type`
    // instead. `label_key` is just `link.label.to_lowercase()`
    // (`replace_page_links`, db.rs) and a resolved link's `page_links` row
    // stops at write time (item 3) -- compute it directly rather than
    // reading a row that no longer exists.
    let relation_type = {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT semantic_type FROM edges \
                 WHERE edge_type = 'relates' AND src_id = ?1 AND dst_id = ?2 \
                   AND valid_until IS NULL",
                libsql::params![from.as_str(), to.as_str()],
            )
            .await
            .unwrap();
        let relation_type: String = rows
            .next()
            .await
            .unwrap()
            .expect("relates edge")
            .get(0)
            .unwrap();
        relation_type
    };
    let label_key = "Semantic Target".to_lowercase();

    for pass in 1..=2 {
        db.migrate_115_edge_semantic_payload(114).await.unwrap();
        let conn = db.conn.lock().await;

        let relates_id = crate::provenance::compute_edge_id(
            "relates",
            "entity",
            &from,
            "entity",
            &to,
            &relation_type,
        );
        let mut rows = conn
            .query(
                "SELECT semantic_type, \
                        json_extract(payload, '$.confidence'), \
                        json_extract(payload, '$.explanation'), \
                        json_extract(payload, '$.source_agent') \
                 FROM edges WHERE edge_id = ?1 AND valid_until IS NULL",
                libsql::params![relates_id.as_str()],
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().expect("relates edge active");
        assert_eq!(
            row.get::<Option<String>>(0).unwrap().as_deref(),
            Some(relation_type.as_str()),
            "pass {pass}: semantic_type"
        );
        assert_eq!(
            row.get::<Option<f64>>(1).unwrap(),
            Some(0.9),
            "pass {pass}: confidence"
        );
        assert_eq!(
            row.get::<Option<String>>(2).unwrap().as_deref(),
            Some("seen in standup"),
            "pass {pass}: explanation"
        );
        assert_eq!(
            row.get::<Option<String>>(3).unwrap().as_deref(),
            Some("agent_smith"),
            "pass {pass}: source_agent"
        );

        let mem_cites_id = crate::provenance::compute_edge_id(
            "cites",
            "page",
            "page_g6_sem",
            "memory",
            "mem_g6_sem",
            "mem_g6_sem",
        );
        let mut rows = conn
            .query(
                "SELECT json_extract(payload, '$.source_kind'), \
                        json_extract(payload, '$.link_reason'), \
                        json_extract(payload, '$.linked_at') \
                 FROM edges WHERE edge_id = ?1 AND valid_until IS NULL",
                libsql::params![mem_cites_id.as_str()],
            )
            .await
            .unwrap();
        let row = rows
            .next()
            .await
            .unwrap()
            .expect("memory cites edge active");
        assert_eq!(
            row.get::<Option<String>>(0).unwrap().as_deref(),
            Some("memory"),
            "pass {pass}: memory cites source_kind"
        );
        assert_eq!(
            row.get::<Option<String>>(1).unwrap().as_deref(),
            Some("distill"),
            "pass {pass}: memory cites link_reason"
        );
        assert!(
            row.get::<Option<i64>>(2).unwrap().is_some(),
            "pass {pass}: memory cites linked_at"
        );

        let ext_cites_id = crate::provenance::compute_edge_id(
            "cites",
            "page",
            "page_g6_sem",
            "external",
            "https://example.com/doc",
            "https://example.com/doc",
        );
        let mut rows = conn
            .query(
                "SELECT json_extract(payload, '$.source_kind'), \
                        json_extract(payload, '$.title'), \
                        json_extract(payload, '$.link_reason') \
                 FROM edges WHERE edge_id = ?1 AND valid_until IS NULL",
                libsql::params![ext_cites_id.as_str()],
            )
            .await
            .unwrap();
        let row = rows
            .next()
            .await
            .unwrap()
            .expect("external cites edge active");
        assert_eq!(
            row.get::<Option<String>>(0).unwrap().as_deref(),
            Some("external_url"),
            "pass {pass}: external cites keeps the 4-way source_kind"
        );
        assert_eq!(
            row.get::<Option<String>>(1).unwrap().as_deref(),
            Some("Example Doc"),
            "pass {pass}: external cites title"
        );
        assert_eq!(
            row.get::<Option<String>>(2).unwrap().as_deref(),
            Some("cited"),
            "pass {pass}: external cites link_reason"
        );

        let links_id = crate::provenance::compute_edge_id(
            "links",
            "page",
            "page_g6_sem",
            "page",
            "page_g6_sem_dst",
            &label_key,
        );
        let mut rows = conn
            .query(
                "SELECT json_extract(payload, '$.label') \
                 FROM edges WHERE edge_id = ?1 AND valid_until IS NULL",
                libsql::params![links_id.as_str()],
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().expect("links edge active");
        assert_eq!(
            row.get::<Option<String>>(0).unwrap().as_deref(),
            Some("Semantic Target"),
            "pass {pass}: links display label"
        );
    }
}

/// G6 Stage 1.2 (docs/plans/2026-08-05-g6-stage12-relations-readers-spec.md):
/// migration 116 backfills `payload.asserted_at` (always) and fills
/// `payload.source_memory_id` only when absent, from the frozen `relations`
/// twin (backfill machinery, still read by migrations per the writer-
/// retirement spec). A pre-Stage-1.2 edge is simulated by clearing both keys after the
/// write (the writer now stamps them at insert time, so a fresh write is
/// never actually missing them). The loop runs the migration twice: the
/// second pass must converge on the identical end-state.
#[tokio::test]
async fn migration_116_backfills_asserted_at_and_fills_source_memory_id() {
    let (db, _dir) = test_db().await;
    let from = db
        .create_entity("G6 Backfill A", "person", Some("space_a"))
        .await
        .unwrap();
    let to = db
        .create_entity("G6 Backfill B", "project", Some("space_a"))
        .await
        .unwrap();
    db.create_relation(
        &from,
        &to,
        "relates_to",
        Some("agent"),
        Some(0.5),
        None,
        Some("mem_backfill"),
    )
    .await
    .unwrap();

    let forced_created_at = 1_000_000_000i64;
    {
        let conn = db.conn.lock().await;
        // G6 Stage 2 PR 2b: `create_relation` no longer writes `relations` --
        // migration 116 still reads it (backfill machinery, kept per the
        // writer-retirement spec) as the twin it backfills `asserted_at`/
        // `source_memory_id` from. Raw-insert the historical row the join
        // expects, using the edge's own (possibly-coerced) semantic_type so
        // the join key matches.
        let semantic_type: String = {
            let mut rows = conn
                .query(
                    "SELECT semantic_type FROM edges \
                     WHERE edge_type = 'relates' AND src_id = ?1 AND dst_id = ?2 \
                       AND valid_until IS NULL",
                    libsql::params![from.as_str(), to.as_str()],
                )
                .await
                .unwrap();
            rows.next()
                .await
                .unwrap()
                .expect("relates edge")
                .get(0)
                .unwrap()
        };
        conn.execute(
            "INSERT INTO relations (id, from_entity, to_entity, relation_type, created_at, source_memory_id) \
             VALUES ('rel_m116_backfill', ?1, ?2, ?3, ?4, 'mem_backfill')",
            libsql::params![from.as_str(), to.as_str(), semantic_type.as_str(), forced_created_at],
        )
        .await
        .unwrap();
        conn.execute(
            "UPDATE edges SET payload = json_remove(payload, '$.asserted_at', '$.source_memory_id') \
             WHERE edge_type = 'relates' AND src_id = ?1 AND dst_id = ?2",
            libsql::params![from.as_str(), to.as_str()],
        )
        .await
        .unwrap();
    }

    for pass in 1..=2 {
        db.migrate_116_relates_asserted_at(115).await.unwrap();
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT json_extract(payload, '$.asserted_at'), \
                        json_extract(payload, '$.source_memory_id') \
                 FROM edges WHERE edge_type = 'relates' AND src_id = ?1 AND dst_id = ?2",
                libsql::params![from.as_str(), to.as_str()],
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().expect("relates edge active");
        assert_eq!(
            row.get::<Option<i64>>(0).unwrap(),
            Some(forced_created_at),
            "pass {pass}: asserted_at must mirror the relations row's created_at"
        );
        assert_eq!(
            row.get::<Option<String>>(1).unwrap().as_deref(),
            Some("mem_backfill"),
            "pass {pass}: source_memory_id must fill in when absent"
        );
    }
}

// G6 Stage 2 PR 2b: parity oracle retired, correctness carried by per-writer
