/// A fresh database never materializes the four retired tables at all: they
/// are created transiently by migrations 82/94 during the same replay that
/// then drops them again at 120, so by the time `test_db()` returns, none of
/// them exist. Complements `fresh_and_upgraded_schemas_agree`, which proves
/// the fresh and upgraded paths converge on identical schemas overall.
#[tokio::test]
async fn migration_120_fresh_db_has_no_retired_tables() {
    let (db, _dir) = test_db().await;
    let conn = db.conn.lock().await;
    for table in [
        "edges_parity_watermark",
        "entity_page_parity_watermark",
        "edges_reader_cutover",
        "entity_reader_cutover",
    ] {
        let mut rows = conn
            .query(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?1",
                libsql::params![table],
            )
            .await
            .unwrap();
        assert!(
            rows.next().await.unwrap().is_none(),
            "a fresh database must not have {table}"
        );
    }
}

/// G6 Stage 1.2 divergence test (Sol review S3): no other test can tell
/// whether a migrated reader actually reads `edges` versus `relations`, since
/// every OTHER fixture keeps both stores in parity via the dual-write. Here
/// they're deliberately split: one relates fact exists ONLY in `edges`, and
/// TWO exist ONLY in `relations` (asymmetric counts so a reader that quietly
/// fell back to `relations` would report a different number, not the same
/// one by coincidence). Covers readers #1 (`expand_anchor_entities_khop`),
/// #2 (`expand_entities_khop_scoped`), #3 (`aggregate_counts`), #5
/// (`get_entity_detail`), #9 (`relation_vocabulary`), and #11
/// (`relation_integrity`) — each must see
/// the edge-only fact and stay blind to the relations-only orphans. Readers
/// #4 (`entity_scope_clause`) and #13 (`load_relations`, both in
/// `lint/semantic_candidates.rs`) are NOT exercised by this test.
#[tokio::test]
async fn migrated_readers_diverge_from_relations_and_follow_edges() {
    let (db, _dir) = test_db().await;
    let edge_src = db
        .create_entity("G6 Divergence EdgeSrc", "thing", None)
        .await
        .unwrap();
    let edge_dst = db
        .create_entity("G6 Divergence EdgeDst", "thing", None)
        .await
        .unwrap();
    let rel_src = db
        .create_entity("G6 Divergence RelSrc", "thing", None)
        .await
        .unwrap();
    let rel_dst = db
        .create_entity("G6 Divergence RelDst", "thing", None)
        .await
        .unwrap();

    {
        let conn = db.conn.lock().await;
        // Edge-only fact: no `relations` twin.
        conn.execute(
            "INSERT INTO edges (edge_id,src_id,src_kind,dst_id,dst_kind,edge_type,lineage,grounded,space,created_at,semantic_type)
             VALUES ('edge-only-1',?1,'entity',?2,'entity','relates','legacy',0,?3,1,'edge_only_type')",
            libsql::params![edge_src.clone(), edge_dst.clone(), UNFILED_SPACE_ID],
        )
        .await
        .unwrap();
        // Two relations-only orphans (asymmetric count vs the one edge-only
        // fact above): no `edges` twin for either.
        conn.execute(
            "INSERT INTO relations (id,from_entity,to_entity,relation_type,created_at)
             VALUES ('rel-only-1',?1,?2,'rel_only_type_a',1)",
            libsql::params![rel_src.clone(), rel_dst.clone()],
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO relations (id,from_entity,to_entity,relation_type,created_at)
             VALUES ('rel-only-2',?1,?2,'rel_only_type_b',1)",
            libsql::params![rel_src.clone(), rel_dst.clone()],
        )
        .await
        .unwrap();
    }

    // Reader #5: get_entity_detail.
    let edge_detail = db.get_entity_detail(&edge_src).await.unwrap();
    assert!(
        edge_detail
            .relations
            .iter()
            .any(|r| r.entity_id == edge_dst),
        "must see the edge-only relation"
    );
    let rel_detail = db.get_entity_detail(&rel_src).await.unwrap();
    assert!(
        rel_detail.relations.is_empty(),
        "must not see the relations-only orphans"
    );

    // Readers #1/#2: k-hop expansion.
    let expanded = temp_env::async_with_vars([("WENLAN_GRAPH_KHOP_DEPTH", Some("1"))], async {
        db.expand_anchor_entities_khop(std::slice::from_ref(&edge_src), &ReadScope::Global)
            .await
            .unwrap()
    })
    .await;
    assert!(
        expanded.contains(&edge_dst),
        "khop must reach the edge-only neighbor"
    );
    let not_expanded = temp_env::async_with_vars([("WENLAN_GRAPH_KHOP_DEPTH", Some("1"))], async {
        db.expand_anchor_entities_khop(std::slice::from_ref(&rel_src), &ReadScope::Global)
            .await
            .unwrap()
    })
    .await;
    assert!(
        !not_expanded.contains(&rel_dst),
        "khop must not reach a relations-only orphan"
    );

    // Reader #2: expand_entities_khop_scoped (explicit-param sibling of #1).
    let expanded_scoped = db
        .expand_entities_khop_scoped(std::slice::from_ref(&edge_src), 1, 64, &ReadScope::Global)
        .await
        .unwrap();
    assert!(
        expanded_scoped.contains(&edge_dst),
        "scoped khop must reach the edge-only neighbor"
    );
    let not_expanded_scoped = db
        .expand_entities_khop_scoped(std::slice::from_ref(&rel_src), 1, 64, &ReadScope::Global)
        .await
        .unwrap();
    assert!(
        !not_expanded_scoped.contains(&rel_dst),
        "scoped khop must not reach a relations-only orphan"
    );

    // Readers #3, #9, #11: Deep profile is a registered superset of General
    // (see deep_profile_is_a_registered_superset_without_duplicate_general_checks),
    // so one report covers relation_integrity + aggregate_counts (General/kg)
    // and relation_vocabulary (Deep).
    let report = crate::lint::runner::LintRunner::new(
        crate::lint::context::LintClock::fixed(),
        crate::lint::context::CancellationToken::new(),
    )
    .run(
        &db,
        &wenlan_types::lint::LintQuery {
            profile: Some(wenlan_types::lint::LintProfile::Deep),
            space: None,
        },
        None,
        false,
    )
    .await
    .unwrap();
    let find_check = |id: &str| {
        report
            .checks()
            .iter()
            .find(|check| check.check_id() == id)
            .unwrap_or_else(|| panic!("missing check {id}"))
    };
    assert_eq!(
        find_check("relations.integrity").coverage().denominator(),
        1,
        "relation_integrity population must come from edges (1), not relations (2)"
    );
    assert_eq!(
        find_check("relations.vocabulary_integrity")
            .coverage()
            .denominator(),
        1,
        "relation_vocabulary population must come from edges (1), not relations (2)"
    );
    let kg_relations_count = find_check("kg.aggregate_inventory")
        .metrics()
        .iter()
        .find_map(|metric| {
            (metric.code() == wenlan_types::lint::LintMetricCode::KgRelations).then(|| match metric
                .value()
            {
                wenlan_types::lint::LintMetricValue::Count { value } => *value,
                _ => 0,
            })
        })
        .unwrap();
    assert_eq!(
        kg_relations_count, 1,
        "aggregate_counts must count edges (1), not relations (2)"
    );
}

/// G6 Stage 1 writer teeth: the live producers must carry semantic fields at
/// write time, before any migration/backfill pass runs. The final parity check
/// proves the same writes still agree with their deriving legacy rows.
#[tokio::test]
async fn edge_semantic_payload_live_writers_leave_parity_clean() {
    let (db, _dir) = test_db().await;
    let from = db
        .create_entity("G6 Writer A", "person", Some("space_a"))
        .await
        .unwrap();
    let to = db
        .create_entity("G6 Writer B", "project", Some("space_a"))
        .await
        .unwrap();
    db.create_relation(
        &from,
        &to,
        "knows",
        Some("writer_agent"),
        Some(0.87),
        Some("writer explanation"),
        None,
    )
    .await
    .unwrap();

    {
        let conn = db.conn.lock().await;
        insert_raw_page_for_m81_test(&conn, "page_g6_writer", "space_a").await;
        insert_raw_page_for_m81_test(&conn, "page_g6_writer_target", "space_a").await;
        insert_raw_page_for_m81_test(&conn, "page_g6_orphan", "space_a").await;
        insert_raw_page_for_m81_test(&conn, "page_g6_orphan_target", "space_a").await;
        conn.execute(
            "UPDATE pages SET title = 'Orphan Target' WHERE id = 'page_g6_orphan_target'",
            (),
        )
        .await
        .unwrap();
    }
    seed_memory_with_source_id_and_space(&db, "mem_g6_writer", "writer source", "space_a").await;
    db.link_page_source("page_g6_writer", "mem_g6_writer", "page source")
        .await
        .unwrap();
    db.link_page_evidence(
        "page_g6_writer",
        "external_url",
        Some("https://example.com/g6-writer"),
        Some("G6 Writer Source"),
        "external evidence",
    )
    .await
    .unwrap();
    db.replace_page_links(
        "page_g6_writer",
        &[crate::synthesis::wikilinks::Wikilink {
            label: "Readable Target".to_string(),
            target_page_id: Some("page_g6_writer_target".to_string()),
        }],
    )
    .await
    .unwrap();

    // The orphan path starts with no edge, then resolves and mints one from
    // the stored display label.
    db.replace_page_links(
        "page_g6_orphan",
        &[crate::synthesis::wikilinks::Wikilink {
            label: "Orphan Target".to_string(),
            target_page_id: None,
        }],
    )
    .await
    .unwrap();
    assert_eq!(db.resolve_orphan_page_links().await.unwrap(), 1);

    {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT semantic_type, \
                        json_extract(payload, '$.confidence'), \
                        json_extract(payload, '$.explanation'), \
                        json_extract(payload, '$.source_agent') \
                 FROM edges WHERE edge_type = 'relates' AND src_id = ?1 AND dst_id = ?2
                   AND valid_until IS NULL",
                libsql::params![from.as_str(), to.as_str()],
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().expect("live relates edge");
        assert_eq!(
            row.get::<Option<String>>(0).unwrap().as_deref(),
            Some("knows")
        );
        assert_eq!(row.get::<Option<f64>>(1).unwrap(), Some(0.87));
        assert_eq!(
            row.get::<Option<String>>(2).unwrap().as_deref(),
            Some("writer explanation")
        );
        assert_eq!(
            row.get::<Option<String>>(3).unwrap().as_deref(),
            Some("writer_agent")
        );

        let mut rows = conn
            .query(
                "SELECT json_extract(payload, '$.source_kind'), \
                        json_extract(payload, '$.link_reason') \
                 FROM edges
                 WHERE edge_type = 'cites' AND src_id = 'page_g6_writer'
                   AND dst_kind = 'external' AND dst_id = 'https://example.com/g6-writer'
                   AND valid_until IS NULL",
                (),
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().expect("external cites edge");
        assert_eq!(
            row.get::<Option<String>>(0).unwrap().as_deref(),
            Some("external_url")
        );
        assert_eq!(
            row.get::<Option<String>>(1).unwrap().as_deref(),
            Some("external evidence")
        );

        let mut rows = conn
            .query(
                "SELECT json_extract(payload, '$.label') FROM edges
                 WHERE edge_type = 'links' AND src_id = 'page_g6_writer'
                   AND dst_id = 'page_g6_writer_target' AND valid_until IS NULL",
                (),
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().expect("live links edge");
        assert_eq!(
            row.get::<Option<String>>(0).unwrap().as_deref(),
            Some("Readable Target")
        );

        let mut rows = conn
            .query(
                "SELECT json_extract(payload, '$.label') FROM edges
                 WHERE edge_type = 'links' AND src_id = 'page_g6_orphan'
                   AND dst_id = 'page_g6_orphan_target' AND valid_until IS NULL",
                (),
            )
            .await
            .unwrap();
        let row = rows
            .next()
            .await
            .unwrap()
            .expect("resolved orphan links edge");
        assert_eq!(
            row.get::<Option<String>>(0).unwrap().as_deref(),
            Some("Orphan Target")
        );
    }
    // G6 Stage 2 PR 2b: parity oracle retired, correctness carried by per-writer regression tests (item 7).
}

// G6 Stage 2 PR 2b: `reconcile_edges_detects_semantic_drift` retired -- its
// entire subject was the parity oracle's own detection of semantic drift
// (`compute_edges_parity_report`'s corrupt/drift fields), no oracle-independent
// replacement needed yet.

/// KG close plan G1: the ambient lane's dedup DELETE hard-removes every
/// competing `relations` row between the same endpoints. It used to leave their
/// dual-written edges ACTIVE, which the parity sweep counts as drift forever.
/// The loser's edge must now be soft-invalidated the same way
/// `supersede_relation` does on the canonical delete path.
#[tokio::test]
async fn ambient_dedup_delete_retracts_the_losing_edge() {
    let (db, _dir) = test_db().await;
    let content = "Alice works on ProjectX.";
    db.upsert_documents(vec![make_memory_doc(
        "mem_g1_dedup",
        content,
        "fact",
        "work",
        "folder",
    )])
    .await
    .unwrap();

    let graph = |relation_type: &str| {
        vec![crate::extract::KgExtractionResult {
            index: 0,
            entities: vec![
                crate::extract::ExtractedEntity {
                    name: "Alice".to_string(),
                    entity_type: "person".to_string(),
                },
                crate::extract::ExtractedEntity {
                    name: "ProjectX".to_string(),
                    entity_type: "project".to_string(),
                },
            ],
            observations: Vec::new(),
            relations: vec![crate::extract::ExtractedRelation {
                from: "Alice".to_string(),
                to: "ProjectX".to_string(),
                relation_type: relation_type.to_string(),
                confidence: Some(0.9),
                explanation: None,
                span: None,
            }],
        }]
    };

    assert!(db
        .commit_entity_enrichment_at_version("mem_g1_dedup", 1, &graph("works_on"), content)
        .await
        .unwrap());
    // A second extraction of the same memory proposes a different type between
    // the same endpoints: the new row wins, the old row is DELETEd.
    assert!(db
        .commit_entity_enrichment_at_version("mem_g1_dedup", 1, &graph("related_to"), content)
        .await
        .unwrap());

    let conn = db.conn.lock().await;
    // G6 Stage 2 PR 2b: `relations` is frozen -- read the surviving relation
    // type off the live `relates` edge instead.
    let surviving_types: Vec<String> = {
        let mut rows = conn
            .query(
                "SELECT semantic_type FROM edges \
                 WHERE edge_type = 'relates' AND valid_until IS NULL",
                (),
            )
            .await
            .unwrap();
        let mut out = Vec::new();
        while let Some(row) = rows.next().await.unwrap() {
            out.push(row.get::<String>(0).unwrap());
        }
        out
    };
    assert_eq!(
        surviving_types,
        vec!["related_to".to_string()],
        "the dedup DELETE removed the losing relation row"
    );

    let mut active = 0i64;
    let mut retracted = 0i64;
    {
        let mut rows = conn
            .query(
                "SELECT valid_until FROM edges WHERE edge_type = 'relates'",
                (),
            )
            .await
            .unwrap();
        while let Some(row) = rows.next().await.unwrap() {
            if row.get::<Option<i64>>(0).unwrap().is_some() {
                retracted += 1;
            } else {
                active += 1;
            }
        }
    }
    assert_eq!(
        active, 1,
        "exactly the surviving relation keeps an active edge — no orphan"
    );
    assert_eq!(
        retracted, 1,
        "the deleted relation's edge is soft-invalidated, not left active or hard-deleted"
    );
}

/// KG close plan G1 steps 2-4: migration 111 repairs what the ambient lane
/// already wrote — backfills the missing edges, retracts the orphans its hard
/// DELETE left behind, retires the pre-repair parity epoch, and resets the
/// grounding cursor EXACTLY ONCE (a per-boot reset would re-spend the whole
/// entailment backlog on every launch).
#[tokio::test]
async fn migration_111_repairs_ambient_parity_and_resets_the_grounding_cursor_once() {
    let (db, _dir) = test_db().await;
    db.create_space("work", None, false).await.unwrap();
    let alice = db
        .store_entity("Alice", "person", Some("work"), Some("post_ingest"), None)
        .await
        .unwrap();
    let project = db
        .store_entity(
            "ProjectX",
            "project",
            Some("work"),
            Some("post_ingest"),
            None,
        )
        .await
        .unwrap();
    let orphan_src = db
        .store_entity(
            "Orphan Src",
            "concept",
            Some("work"),
            Some("post_ingest"),
            None,
        )
        .await
        .unwrap();
    let orphan_dst = db
        .store_entity(
            "Orphan Dst",
            "concept",
            Some("work"),
            Some("post_ingest"),
            None,
        )
        .await
        .unwrap();

    // G6 Stage 2 PR 2c sub-step 3 item 5: `store_entity` no longer writes
    // `entities`. Two reasons every entity above needs a legacy companion
    // row here: migration 111's frozen body LEFT JOINs `entities` for both
    // endpoint spaces (alice/project, used in the bare INSERT below), and the
    // chain this test replays (110 -> current) also re-fires migration 114,
    // whose frozen resync unconditionally re-derives `pages.title` etc. from
    // `entities` for EVERY mapped shadow -- a shadow with no `entities` row
    // (orphan_src/orphan_dst included) would NULL out `pages.title`, a NOT
    // NULL column.
    //
    // G6 Stage 3: migration 123 dropped `entities`, and `test_db()` runs the
    // full chain, so recreate the legacy tables at their user_version-122
    // shape first -- exactly what `ensure_legacy_entities_table` does for a
    // real pre-123 database before the frozen bodies replay. `store_entity`
    // already created all four shadow pages, so no second shadow seed here.
    db.test_create_legacy_entity_tables().await.unwrap();
    {
        let conn = db.conn.lock().await;
        for (id, name, entity_type) in [
            (alice.as_str(), "Alice", "person"),
            (project.as_str(), "ProjectX", "project"),
            (orphan_src.as_str(), "Orphan Src", "concept"),
            (orphan_dst.as_str(), "Orphan Dst", "concept"),
        ] {
            conn.execute(
                "INSERT INTO entities \
                     (id, name, entity_type, space, source_agent, confidence, confirmed, \
                      created_at, updated_at) \
                 VALUES (?1, ?2, ?3, 'work', 'post_ingest', NULL, 0, 1, 1)",
                libsql::params![id, name, entity_type],
            )
            .await
            .unwrap();
        }
    }

    // (a) The shape the old ambient INSERT left: a relation with no edge twin.
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "INSERT INTO relations
                 (id, from_entity, to_entity, relation_type, source_agent,
                  confidence, explanation, source_memory_id, created_at)
             VALUES ('rel_g1_bare', ?1, ?2, 'works_on', 'post_ingest', NULL, NULL, NULL, 1)",
            libsql::params![alice.as_str(), project.as_str()],
        )
        .await
        .unwrap();
    }

    // (b) The shape the old ambient DELETE left: an active edge with no
    //     relation behind it. Built by dual-writing properly, then removing the
    //     legacy row the way that lane did.
    db.create_relation_with_span(
        &orphan_src,
        &orphan_dst,
        "related_to",
        Some("post_ingest"),
        None,
        None,
        None,
        None,
        None,
        None,
        None,
    )
    .await
    .unwrap();
    let orphan_edge_id = crate::provenance::compute_edge_id(
        "relates",
        "entity",
        &orphan_src,
        "entity",
        &orphan_dst,
        "related_to",
    );
    let bare_edge_id = crate::provenance::compute_edge_id(
        "relates", "entity", &alice, "entity", &project, "works_on",
    );

    let epoch_before: i64;
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "DELETE FROM relations WHERE from_entity = ?1 AND to_entity = ?2",
            libsql::params![orphan_src.as_str(), orphan_dst.as_str()],
        )
        .await
        .unwrap();
        let mut rows = conn
            .query("SELECT epoch FROM edges_migration_state WHERE id = 1", ())
            .await
            .unwrap();
        epoch_before = rows.next().await.unwrap().unwrap().get(0).unwrap();
    }

    db.set_app_metadata(
        crate::edge_grounding::EDGE_GROUNDING_CURSOR_KEY,
        r#"{"cursor":9999,"stuck_rowid":null,"failures":0,"entailment_version":"v1|m"}"#,
    )
    .await
    .unwrap();

    // Wind back to the pre-repair boundary and run the chain.
    {
        let conn = db.conn.lock().await;
        conn.execute("PRAGMA user_version = 110", ()).await.unwrap();
    }
    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("migration 111 must apply");

    let conn = db.conn.lock().await;
    let bare_state: Option<(String, Option<i64>)> = {
        let mut rows = conn
            .query(
                "SELECT lineage, valid_until FROM edges WHERE edge_id = ?1",
                libsql::params![bare_edge_id.as_str()],
            )
            .await
            .unwrap();
        rows.next()
            .await
            .unwrap()
            .map(|row| (row.get(0).unwrap(), row.get::<Option<i64>>(1).unwrap()))
    };
    let (bare_lineage, bare_valid_until) =
        bare_state.expect("the backfill must mint the missing edge");
    assert_eq!(
        bare_lineage, "assertion",
        "both endpoints are in one Space, so the backfilled edge is first-class"
    );
    assert!(bare_valid_until.is_none(), "the backfilled edge is active");

    let orphan_valid_until: Option<i64> = {
        let mut rows = conn
            .query(
                "SELECT valid_until FROM edges WHERE edge_id = ?1",
                libsql::params![orphan_edge_id.as_str()],
            )
            .await
            .unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert!(
        orphan_valid_until.is_some(),
        "an active edge with no relation behind it is retracted, not left as drift"
    );

    let epoch_after: i64 = {
        let mut rows = conn
            .query("SELECT epoch FROM edges_migration_state WHERE id = 1", ())
            .await
            .unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert_eq!(
        epoch_after,
        epoch_before + 1,
        "the repair retires every parity watermark taken while coverage was lapsed"
    );
    drop(conn);

    assert!(
        db.get_app_metadata(crate::edge_grounding::EDGE_GROUNDING_CURSOR_KEY)
            .await
            .unwrap()
            .is_none(),
        "the grounding cursor is reset so backfilled relations get rescanned"
    );

    // Idempotence: the reset is tied to the migration number, not to boot. A
    // cursor written after the repair survives every later startup.
    db.set_app_metadata(
        crate::edge_grounding::EDGE_GROUNDING_CURSOR_KEY,
        r#"{"cursor":7,"stuck_rowid":null,"failures":0,"entailment_version":"v1|m"}"#,
    )
    .await
    .unwrap();
    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("a second startup is a no-op");
    let cursor_after = db
        .get_app_metadata(crate::edge_grounding::EDGE_GROUNDING_CURSOR_KEY)
        .await
        .unwrap();
    assert!(
        cursor_after.is_some_and(|value| value.contains("\"cursor\":7")),
        "the reset must not re-fire on every startup"
    );
    let conn = db.conn.lock().await;
    let epoch_final: i64 = {
        let mut rows = conn
            .query("SELECT epoch FROM edges_migration_state WHERE id = 1", ())
            .await
            .unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert_eq!(epoch_final, epoch_after, "and neither does the epoch bump");
}

/// The third damage shape: the relation is live but its edge is RETRACTED.
/// Reachable because a canonical delete retracts the edge and drops the legacy
/// row, and the OLD ambient lane then re-extracted the same triple and
/// raw-INSERTed the relation with no edge write. `reconcile_edges_parity`
/// compares against ACTIVE edges only, so this counts as drift to the sweep
/// forever — and `insert_backfilled_edge` is `ON CONFLICT DO NOTHING`, so a
/// backfill can never heal it. The repair must route these through the live
/// writer instead. The settling assertion is the oracle itself: drift 0.
#[tokio::test]
async fn migration_111_reactivates_a_retracted_edge_and_settles_parity_at_zero() {
    let (db, _dir) = test_db().await;
    db.create_space("work", None, false).await.unwrap();
    let src = db
        .store_entity("Retracted Src", "concept", Some("work"), Some("test"), None)
        .await
        .unwrap();
    let dst = db
        .store_entity("Retracted Dst", "concept", Some("work"), Some("test"), None)
        .await
        .unwrap();

    // Canonical write, then the canonical delete — which retracts the edge and
    // hard-deletes the legacy row.
    let relation_id = db
        .create_relation_with_span(
            &src,
            &dst,
            "related_to",
            Some("test"),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        )
        .await
        .unwrap();
    db.supersede_relation(&relation_id, "some-other-relation")
        .await
        .unwrap()
        .expect("the canonical delete must find the relation");

    let edge_id =
        crate::provenance::compute_edge_id("relates", "entity", &src, "entity", &dst, "related_to");
    {
        let conn = db.conn.lock().await;
        let valid_until: Option<i64> = {
            let mut rows = conn
                .query(
                    "SELECT valid_until FROM edges WHERE edge_id = ?1",
                    libsql::params![edge_id.as_str()],
                )
                .await
                .unwrap();
            rows.next().await.unwrap().unwrap().get(0).unwrap()
        };
        assert!(
            valid_until.is_some(),
            "fixture precondition: the canonical delete retracted the edge"
        );
    }

    // Now the old ambient lane re-extracts the same triple: a bare relation
    // INSERT with no edge write.
    // G6 Stage 3: migration 111's frozen body reads both endpoint spaces from
    // `entities`, which migration 123 dropped -- recreate the legacy tables at
    // their user_version-122 shape (what `ensure_legacy_entities_table` does
    // for a real pre-123 database) and seed the rows `store_entity` used to
    // write pre-flip. `store_entity` already created both shadow pages, so
    // there is no second shadow seed here.
    db.test_create_legacy_entity_tables().await.unwrap();
    {
        let conn = db.conn.lock().await;
        for (id, name) in [
            (src.as_str(), "Retracted Src"),
            (dst.as_str(), "Retracted Dst"),
        ] {
            conn.execute(
                "INSERT INTO entities \
                     (id, name, entity_type, space, source_agent, confidence, confirmed, \
                      created_at, updated_at) \
                 VALUES (?1, ?2, 'concept', 'work', 'test', NULL, 0, 1, 1)",
                libsql::params![id, name],
            )
            .await
            .unwrap();
        }
    }
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "INSERT INTO relations
                 (id, from_entity, to_entity, relation_type, source_agent,
                  confidence, explanation, source_memory_id, created_at)
             VALUES ('rel_g1_retracted', ?1, ?2, 'related_to', 'post_ingest', NULL, NULL, NULL, 1)",
            libsql::params![src.as_str(), dst.as_str()],
        )
        .await
        .unwrap();
        conn.execute("PRAGMA user_version = 110", ()).await.unwrap();
    }

    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("migration 111 must apply");

    {
        let conn = db.conn.lock().await;
        let (lineage, valid_until): (String, Option<i64>) = {
            let mut rows = conn
                .query(
                    "SELECT lineage, valid_until FROM edges WHERE edge_id = ?1",
                    libsql::params![edge_id.as_str()],
                )
                .await
                .unwrap();
            let row = rows.next().await.unwrap().unwrap();
            (row.get(0).unwrap(), row.get::<Option<i64>>(1).unwrap())
        };
        assert!(
            valid_until.is_none(),
            "a live relation's retracted edge must be reactivated, not left as drift"
        );
        assert_eq!(
            lineage, "assertion",
            "reactivation re-derives lineage from the CURRENT endpoint spaces"
        );
    }
    // G6 Stage 2 PR 2b: parity oracle retired, correctness carried by per-writer regression tests (item 7).
}

/// The damage gate is the detector, not the version number: an undamaged
/// database that crosses 110 -> 111 must keep its epoch and its grounding
/// cursor, or every healthy install pays a full entailment rescan and loses a
/// clean parity watermark for a repair that had nothing to repair.
#[tokio::test]
async fn migration_111_is_a_no_op_on_an_undamaged_database() {
    let (db, _dir) = test_db().await;
    db.create_space("work", None, false).await.unwrap();
    let src = db
        .store_entity("Healthy Src", "concept", Some("work"), Some("test"), None)
        .await
        .unwrap();
    let dst = db
        .store_entity("Healthy Dst", "concept", Some("work"), Some("test"), None)
        .await
        .unwrap();
    // Canonically written and left alone: relation live, edge active.
    db.create_relation_with_span(
        &src,
        &dst,
        "related_to",
        Some("test"),
        None,
        None,
        None,
        None,
        None,
        None,
        None,
    )
    .await
    .unwrap();
    // G6 Stage 2 PR 2b: `create_relation_with_span` no longer writes
    // `relations` -- migration 111 still reads it (backfill machinery, m81/
    // m111-only, deliberately kept per the writer-retirement spec) to decide
    // whether an edge is "expected". Raw-insert the historical twin so an
    // "undamaged" database looks the way one actually did pre-cutover:
    // relation and edge both present and in parity, not a live edge with no
    // twin at all (which m111 would otherwise read as an orphan and retract).
    // G6 Stage 3: migration 111's frozen body reads both endpoint spaces from
    // `entities`, which migration 123 dropped -- recreate the legacy tables at
    // their user_version-122 shape (what `ensure_legacy_entities_table` does
    // for a real pre-123 database) and seed the rows `store_entity` used to
    // write pre-flip. `store_entity` already created both shadow pages, so
    // there is no second shadow seed here.
    db.test_create_legacy_entity_tables().await.unwrap();
    {
        let conn = db.conn.lock().await;
        for (id, name) in [(src.as_str(), "Healthy Src"), (dst.as_str(), "Healthy Dst")] {
            conn.execute(
                "INSERT INTO entities \
                     (id, name, entity_type, space, source_agent, confidence, confirmed, \
                      created_at, updated_at) \
                 VALUES (?1, ?2, 'concept', 'work', 'test', NULL, 0, 1, 1)",
                libsql::params![id, name],
            )
            .await
            .unwrap();
        }
    }
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "INSERT INTO relations (id, from_entity, to_entity, relation_type, created_at) \
             VALUES ('rel_m111_healthy', ?1, ?2, 'related_to', strftime('%s','now'))",
            libsql::params![src.as_str(), dst.as_str()],
        )
        .await
        .unwrap();
    }

    db.set_app_metadata(
        crate::edge_grounding::EDGE_GROUNDING_CURSOR_KEY,
        r#"{"cursor":42,"stuck_rowid":null,"failures":0,"entailment_version":"v1|m"}"#,
    )
    .await
    .unwrap();

    let epoch_before: i64;
    {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query("SELECT epoch FROM edges_migration_state WHERE id = 1", ())
            .await
            .unwrap();
        epoch_before = rows.next().await.unwrap().unwrap().get(0).unwrap();
        drop(rows);
        conn.execute("PRAGMA user_version = 110", ()).await.unwrap();
    }

    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("migration 111 must apply");

    let conn = db.conn.lock().await;
    let epoch_after: i64 = {
        let mut rows = conn
            .query("SELECT epoch FROM edges_migration_state WHERE id = 1", ())
            .await
            .unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert_eq!(
        epoch_after, epoch_before,
        "a database that never lapsed keeps its epoch, so a clean watermark stays current"
    );
    drop(conn);

    let cursor = db
        .get_app_metadata(crate::edge_grounding::EDGE_GROUNDING_CURSOR_KEY)
        .await
        .unwrap();
    assert!(
        cursor.is_some_and(|value| value.contains("\"cursor\":42")),
        "and keeps its grounding cursor, so it does not re-spend the entailment backlog"
    );
}

/// Seed one memory through the real write path, then strip its `origin_class`
/// so the row looks the way a pre-112 database's rows look.
async fn seed_pre_112_memory(db: &MemoryDB, source_id: &str, agent: Option<&str>) {
    db.upsert_documents(vec![wenlan_types::RawDocument {
        source: "memory".to_string(),
        source_id: source_id.to_string(),
        title: source_id.to_string(),
        content: format!("Content for {source_id}, long enough to chunk cleanly."),
        last_modified: 1,
        space: Some("work".to_string()),
        source_agent: agent.map(str::to_string),
        confirmed: Some(true),
        ..Default::default()
    }])
    .await
    .unwrap();
    let conn = db.conn.lock().await;
    conn.execute(
        "UPDATE memories SET origin_class = NULL WHERE source_id = ?1",
        libsql::params![source_id],
    )
    .await
    .unwrap();
}

async fn community_parity_generation(db: &MemoryDB) -> i64 {
    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT generation FROM community_parity_input_state WHERE singleton = 1",
            (),
        )
        .await
        .unwrap();
    rows.next().await.unwrap().unwrap().get(0).unwrap()
}

async fn origin_class_of(db: &MemoryDB, source_id: &str) -> Option<String> {
    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT origin_class FROM memories WHERE source_id = ?1 AND chunk_index = 0",
            libsql::params![source_id],
        )
        .await
        .unwrap();
    rows.next()
        .await
        .unwrap()
        .and_then(|row| row.get::<Option<String>>(0).unwrap_or(None))
}

/// KG close plan G2 / Part A item 1: migration 112 gives every historical row
/// the daemon's origin verdict, derived by the same classifier the write path
/// now applies — so a backfilled row and a freshly-written one are
/// indistinguishable to the grounding gate.
#[tokio::test]
async fn migration_112_backfills_origin_class_from_the_ingest_path() {
    let (db, _dir) = test_db().await;
    db.create_space("work", None, false).await.unwrap();
    seed_pre_112_memory(&db, "doc_folder", Some("folder")).await;
    seed_pre_112_memory(&db, "doc_obsidian", Some("obsidian")).await;
    seed_pre_112_memory(&db, "doc_obsidian_projection", Some("obsidian")).await;
    seed_pre_112_memory(&db, "cap_agent", Some("claude-code")).await;
    seed_pre_112_memory(&db, "rev_reconcile", Some("reconcile")).await;
    seed_pre_112_memory(&db, "cap_anonymous", None).await;

    let parity_generation_before = community_parity_generation(&db).await;
    {
        let conn = db.conn.lock().await;
        conn.execute("PRAGMA user_version = 111", ()).await.unwrap();
    }
    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("migration 112 must apply");

    // The backfill runs with `m4_parity_input_memory_update` suspended:
    // `origin_class` is a derived provenance label, not a community-parity
    // input, and an unqualified AFTER UPDATE trigger would otherwise bump the
    // generation once per row and invalidate every parity proof.
    assert_eq!(
        community_parity_generation(&db).await,
        parity_generation_before,
        "classifying rows must not move the community parity generation"
    );
    {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT COUNT(*) FROM sqlite_master WHERE type = 'trigger' \
                 AND name = 'm4_parity_input_memory_update'",
                (),
            )
            .await
            .unwrap();
        let restored: i64 = rows.next().await.unwrap().unwrap().get(0).unwrap();
        assert_eq!(restored, 1, "the suspended trigger must be restored");
    }

    assert_eq!(
        origin_class_of(&db, "doc_folder").await.as_deref(),
        Some("document_ingest"),
        "`folder` is the one class the pre-112 gate already promoted, so \
         backfilling it changes nothing about what grounds"
    );
    for generated in [
        "doc_obsidian",
        "doc_obsidian_projection",
        "cap_agent",
        "rev_reconcile",
        "cap_anonymous",
    ] {
        assert_eq!(
            origin_class_of(&db, generated).await.as_deref(),
            Some("generated"),
            "{generated} must not become groundable"
        );
    }
}

/// The backfill must not hand `document_ingest` to a pre-112 `obsidian` row.
///
/// Some of those rows are Wenlan's own projected pages, re-ingested before the
/// frontmatter skip existed — the `knowledge_path`-inside-the-vault setup that
/// `sources/obsidian.rs` describes. Promoting them would let the graph ground
/// on its own distilled prose (invariant #11). The migration cannot tell them
/// apart from a genuine vault note: `note_to_documents` stores the
/// frontmatter-STRIPPED body, so the `origin_id` marker never reaches
/// `memories.content` (this test seeds it anyway, to pin that a content-based
/// predicate would be the wrong instrument even if one were added), and the
/// page↔file mapping lives in `state.json`, not in a joinable table.
///
/// So the whole class stays `generated` and a re-sync reclassifies. This test
/// is the teeth on that decision: if someone later "fixes" the backfill to read
/// `DOCUMENT_INGEST_SOURCE_AGENTS`, both assertions here fail.
#[tokio::test]
async fn migration_112_leaves_pre_112_obsidian_rows_generated() {
    let (db, _dir) = test_db().await;
    db.create_space("work", None, false).await.unwrap();
    seed_pre_112_memory(&db, "vault_note", Some("obsidian")).await;
    seed_pre_112_memory(&db, "reingested_projection", Some("obsidian")).await;
    seed_pre_112_memory(&db, "real_document", Some("folder")).await;
    // Shape the projection row the way a re-ingest would have, marker included.
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "UPDATE memories SET content = ?1 WHERE source_id = 'reingested_projection'",
            libsql::params![
                "---\norigin_id: page_abc\n---\n\nDistilled prose Wenlan wrote about ProjectX."
            ],
        )
        .await
        .unwrap();
        conn.execute("PRAGMA user_version = 111", ()).await.unwrap();
    }

    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .unwrap();

    assert_eq!(
        origin_class_of(&db, "reingested_projection")
            .await
            .as_deref(),
        Some("generated"),
        "a re-ingested projection must never be backfilled groundable"
    );
    assert_eq!(
        origin_class_of(&db, "vault_note").await.as_deref(),
        Some("generated"),
        "and the honest vault note goes with it — the migration cannot \
         distinguish the two, so the whole pre-112 obsidian class waits for a \
         re-sync rather than being trusted on a guess"
    );
    assert_eq!(
        origin_class_of(&db, "real_document").await.as_deref(),
        Some("document_ingest"),
        "the exclusion must be scoped to obsidian, not blanket-deny the backfill"
    );
}

/// Re-running the migration must not reclassify anything. The ALTER is skipped
/// when the column exists and both backfills are scoped to `origin_class IS
/// NULL`, so a second pass over a healthy database is a no-op — the same
/// property migration 111 holds.
#[tokio::test]
async fn migration_112_is_a_no_op_on_a_second_pass() {
    let (db, _dir) = test_db().await;
    db.create_space("work", None, false).await.unwrap();
    seed_pre_112_memory(&db, "doc_folder", Some("folder")).await;
    seed_pre_112_memory(&db, "cap_agent", Some("claude-code")).await;

    {
        let conn = db.conn.lock().await;
        conn.execute("PRAGMA user_version = 111", ()).await.unwrap();
    }
    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .unwrap();

    // A row the daemon later reclassified by hand (the shape a future repair
    // would leave): a second pass must leave it exactly as found, not
    // re-derive it from the string.
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "UPDATE memories SET origin_class = 'generated' WHERE source_id = 'doc_folder'",
            (),
        )
        .await
        .unwrap();
        conn.execute("PRAGMA user_version = 111", ()).await.unwrap();
    }
    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("a second pass must apply cleanly, not fail on a duplicate column");

    assert_eq!(
        origin_class_of(&db, "doc_folder").await.as_deref(),
        Some("generated"),
        "the backfill only ever fills NULLs; it never overwrites a recorded verdict"
    );
    assert_eq!(
        origin_class_of(&db, "cap_agent").await.as_deref(),
        Some("generated")
    );
}

/// The healthy-database property (mirrors
/// `migration_111_is_a_no_op_on_an_undamaged_database`): a store whose rows
/// were all written by a post-112 daemon already carries the column, so the
/// migration classifies nothing and, in particular, does not disturb the
/// grounding cursor — nothing here invalidates a decision the sweep made.
#[tokio::test]
async fn migration_112_is_a_no_op_on_an_already_classified_database() {
    let (db, _dir) = test_db().await;
    db.create_space("work", None, false).await.unwrap();
    // Written by the current write path: origin_class already stamped.
    db.upsert_documents(vec![wenlan_types::RawDocument {
        source: "memory".to_string(),
        source_id: "doc_healthy".to_string(),
        title: "doc".to_string(),
        content: "A document long enough to chunk, ingested by the folder watcher.".to_string(),
        last_modified: 1,
        space: Some("work".to_string()),
        source_agent: Some("folder".to_string()),
        confirmed: Some(true),
        ..Default::default()
    }])
    .await
    .unwrap();
    assert_eq!(
        origin_class_of(&db, "doc_healthy").await.as_deref(),
        Some("document_ingest"),
        "the write path stamps the class; the migration is only for history"
    );

    db.set_app_metadata(
        crate::edge_grounding::EDGE_GROUNDING_CURSOR_KEY,
        r#"{"cursor":42,"stuck_rowid":null,"failures":0,"entailment_version":"v1|m"}"#,
    )
    .await
    .unwrap();
    {
        let conn = db.conn.lock().await;
        conn.execute("PRAGMA user_version = 111", ()).await.unwrap();
    }
    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .unwrap();

    assert_eq!(
        origin_class_of(&db, "doc_healthy").await.as_deref(),
        Some("document_ingest")
    );
    let cursor = db
        .get_app_metadata(crate::edge_grounding::EDGE_GROUNDING_CURSOR_KEY)
        .await
        .unwrap();
    assert!(
        cursor.is_some_and(|value| value.contains("\"cursor\":42")),
        "112 classifies rows; it does not invalidate grounding decisions"
    );
}

#[tokio::test]
async fn linked_new_generation_repairs_entity_receipt_without_inference() {
    use std::sync::atomic::{AtomicUsize, Ordering};

    let (db, _dir) = test_db().await;
    let entity_id = db
        .store_entity(
            "Accepted revision entity",
            "concept",
            None,
            Some("test"),
            Some(1.0),
        )
        .await
        .unwrap();
    let mut doc = make_memory_doc(
        "mem_linked_new_generation",
        "Accepted revision entity",
        "fact",
        "work",
        "reconcile",
    );
    doc.entity_id = Some(entity_id.clone());
    db.upsert_documents(vec![doc]).await.unwrap();
    assert!(db
        .record_enrichment_step_at_version(
            "mem_linked_new_generation",
            "entity_extract",
            "skipped",
            None,
            1,
        )
        .await
        .unwrap());
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "INSERT INTO memory_entities (memory_id, entity_id) VALUES (?1, ?2)",
            libsql::params!["mem_linked_new_generation", entity_id.as_str()],
        )
        .await
        .unwrap();
        conn.execute(
            "UPDATE memories SET version=2 WHERE source_id='mem_linked_new_generation'",
            (),
        )
        .await
        .unwrap();
    }
    let calls = Arc::new(AtomicUsize::new(0));
    let observed = calls.clone();

    assert_eq!(
        db.run_entity_enrichment_slice(move |_| {
            observed.fetch_add(1, Ordering::SeqCst);
            async move { Ok(Vec::new()) }
        })
        .await
        .unwrap(),
        1
    );
    assert_eq!(calls.load(Ordering::SeqCst), 0);
    let steps = db
        .get_enrichment_steps("mem_linked_new_generation")
        .await
        .unwrap();
    let entity = steps
        .iter()
        .find(|step| step.step == "entity_extract")
        .expect("repaired entity receipt");
    assert_eq!(entity.status, "ok");
    assert_eq!(entity.input_version, Some(2));
    assert!(db
        .get_page_growth_candidate(3, true)
        .await
        .unwrap()
        .is_some());
    assert_eq!(
        db.run_entity_enrichment_slice(|_| async move { Ok(Vec::new()) })
            .await
            .unwrap(),
        0,
        "a repaired linked generation must be terminal"
    );
}

/// The ambient enrichment cascade must gate its vector-similarity auto-merge
/// by the same `has_high_entropy` check `resolve_or_create_entity` step 3
/// applies. Without it "API" and "APIs" embed inside the 0.1 merge distance
/// and collapse into one entity through post-ingest enrichment even though the
/// user-facing create path keeps them apart.
#[tokio::test]
async fn enrichment_cascade_skips_vector_merge_for_low_entropy_names() {
    let (db, _dir) = test_db().await;
    for (index, source_id) in ["mem_entropy_api", "mem_entropy_apis"]
        .into_iter()
        .enumerate()
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "INSERT INTO memories
                 (id, content, source, source_id, title, chunk_index,
                  last_modified, chunk_type, pending_revision, version)
             VALUES (?1, 'entropy gate fixture', 'memory', ?2, '', 0, 1, 'text', 0, 1)",
            libsql::params![format!("c_entropy_{index}"), source_id],
        )
        .await
        .unwrap();
    }

    assert!(db
        .commit_entity_enrichment_at_version(
            "mem_entropy_api",
            1,
            &extracted_entity("API", "concept"),
            "entropy gate fixture",
        )
        .await
        .unwrap());
    assert!(db
        .commit_entity_enrichment_at_version(
            "mem_entropy_apis",
            1,
            &extracted_entity("APIs", "concept"),
            "entropy gate fixture",
        )
        .await
        .unwrap());

    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT p.title FROM entity_page_map epm
             JOIN pages p ON p.id = epm.page_id
             WHERE p.kind = 'entity' AND p.status = 'active'
               AND p.title IN ('API', 'APIs')
             ORDER BY p.title",
            (),
        )
        .await
        .unwrap();
    let mut titles: Vec<String> = Vec::new();
    while let Some(row) = rows.next().await.unwrap() {
        titles.push(row.get::<String>(0).unwrap());
    }
    assert_eq!(
        titles,
        vec!["API".to_string(), "APIs".to_string()],
        "low-entropy names must not vector-auto-merge through the enrichment cascade"
    );
}

#[tokio::test]
async fn entity_reenrichment_replaces_only_source_owned_observations() {
    let (db, _dir) = test_db().await;
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "INSERT INTO memories
                 (id, content, source, source_id, title, chunk_index,
                  last_modified, chunk_type, pending_revision, version)
             VALUES ('c_observation_owner', 'first generation', 'memory',
                     'mem_observation_owner', '', 0, 1, 'text', 0, 1)",
            (),
        )
        .await
        .unwrap();
    }

    assert!(db
        .commit_entity_enrichment_at_version(
            "mem_observation_owner",
            1,
            &extracted_entity_with_observation(
                "Shared Topic",
                "concept",
                "old source-owned observation",
            ),
            "old source-owned observation",
        )
        .await
        .unwrap());
    let entity_id = db
        .search_entities_by_name("Shared Topic")
        .await
        .unwrap()
        .into_iter()
        .next()
        .unwrap()
        .id;
    db.add_observation(
        &entity_id,
        "manual observation must survive",
        Some("manual"),
        None,
    )
    .await
    .unwrap();
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "UPDATE memories
             SET content = 'second generation', version = 2
             WHERE source_id = 'mem_observation_owner'",
            (),
        )
        .await
        .unwrap();
    }

    assert!(db
        .commit_entity_enrichment_at_version(
            "mem_observation_owner",
            2,
            &extracted_entity_with_observation(
                "Shared Topic",
                "concept",
                "new source-owned observation",
            ),
            "new source-owned observation",
        )
        .await
        .unwrap());

    let conn = db.conn.lock().await;
    let mut owned = conn
        .query(
            "SELECT content FROM observations
             WHERE entity_id = ?1 AND source_memory_id = 'mem_observation_owner'
             ORDER BY content",
            libsql::params![entity_id.as_str()],
        )
        .await
        .unwrap();
    let mut owned_contents = Vec::new();
    while let Some(row) = owned.next().await.unwrap() {
        owned_contents.push(row.get::<String>(0).unwrap());
    }
    assert_eq!(owned_contents, vec!["new source-owned observation"]);
    drop(owned);

    let mut manual = conn
        .query(
            "SELECT content FROM observations
             WHERE entity_id = ?1 AND source_memory_id IS NULL",
            libsql::params![entity_id.as_str()],
        )
        .await
        .unwrap();
    assert_eq!(
        manual
            .next()
            .await
            .unwrap()
            .unwrap()
            .get::<String>(0)
            .unwrap(),
        "manual observation must survive"
    );
    assert!(manual.next().await.unwrap().is_none());
}

