#[tokio::test]
async fn fact_channel_excludes_pending_and_hide_superseded_parents() {
    let (db, _dir) = test_db().await;
    temp_env::async_with_vars([("WENLAN_ENABLE_FACT_CHANNEL", Some("1"))], async {
        let active = memory_doc_with_fields(
            "fact_visible_parent",
            "The active record contains an unusual retrieval key.",
            r#"{"thermal_marker":"cobalt orchard"}"#,
        );
        let mut pending = memory_doc_with_fields(
            "fact_pending_parent",
            "This pending revision must stay out of retrieval.",
            r#"{"thermal_marker":"cobalt orchard"}"#,
        );
        pending.pending_revision = true;
        let hidden = memory_doc_with_fields(
            "fact_hidden_parent",
            "This old fact has already been replaced.",
            r#"{"thermal_marker":"cobalt orchard"}"#,
        );
        let mut replacement = make_memory_doc(
            "fact_replacement",
            "The replacement deliberately omits the old retrieval key.",
            "fact",
            "work",
            "agent",
        );
        replacement.supersedes = Some("fact_hidden_parent".to_string());
        db.upsert_documents(vec![active, pending, hidden, replacement])
            .await
            .unwrap();
    })
    .await;

    let hits = db
        .search_facts_channel("cobalt orchard", 20, &ReadScope::Global)
        .await
        .unwrap();
    let source_ids: Vec<&str> = hits.iter().map(|hit| hit.source_id.as_str()).collect();
    assert!(
        source_ids.contains(&"fact_visible_parent"),
        "control parent must prove the fact channel ran: {source_ids:?}"
    );
    assert!(!source_ids.contains(&"fact_pending_parent"));
    assert!(!source_ids.contains(&"fact_hidden_parent"));
}

#[tokio::test]
async fn fact_channel_absent_when_flag_off() {
    let (db, _dir) = test_db().await;
    // Store WITH flag on so children exist, then read with flag OFF.
    temp_env::async_with_vars([("WENLAN_ENABLE_FACT_CHANNEL", Some("1"))], async {
        db.upsert_documents(vec![memory_doc_with_fields(
            "m_offread",
            "The contract auto-renews and finance reconciles the invoice monthly.",
            "{\"renewal_date\":\"November 3\"}",
        )])
        .await
        .unwrap();
    })
    .await;
    // Read with flag OFF: the channel must not run. Compare to a query that
    // only the buried field would match.
    let off_hits =
        temp_env::async_with_vars([("WENLAN_ENABLE_FACT_CHANNEL", None::<&str>)], async {
            db.search_memory_cross_rerank(
                "November 3 renewal date specific",
                10,
                None,
                &ReadScope::Global,
                None,
                None,
            )
            .await
            .unwrap()
        })
        .await;
    let on_hits = temp_env::async_with_vars([("WENLAN_ENABLE_FACT_CHANNEL", Some("1"))], async {
        db.search_memory_cross_rerank(
            "November 3 renewal date specific",
            10,
            None,
            &ReadScope::Global,
            None,
            None,
        )
        .await
        .unwrap()
    })
    .await;
    // ON must surface >= as many results as OFF for this query (channel only
    // adds mass). At minimum, flag-OFF produces an unchanged base result.
    assert!(
        on_hits.len() >= off_hits.len(),
        "fact channel ON never returns fewer than OFF (ON={}, OFF={})",
        on_hits.len(),
        off_hits.len()
    );
}

