// G6 Stage 2 PR 2a retired `edges_reconcile_enabled_is_explicit_opt_in` and
// `entity_page_reconcile_enabled_is_explicit_opt_in` along with the flags
// and parsing functions they tested (`WENLAN_ENABLE_EDGES_RECONCILE` /
// `edges_reconcile_enabled`+`edges_reconcile_enabled_value`,
// `WENLAN_ENABLE_ENTITY_PAGE_RECONCILE` /
// `entity_page_reconcile_enabled`+`entity_page_reconcile_enabled_value`):
// both flags gated only the now-retired production reconcile sweeps.

#[test]
fn community_leiden_enabled_is_explicit_opt_in() {
    for value in [
        None,
        Some(""),
        Some("0"),
        Some("false"),
        Some("off"),
        Some("garbage"),
    ] {
        assert!(
            !community_leiden_enabled_value(value),
            "{value:?} must preserve the legacy-only community phase"
        );
    }
    for value in [Some("1"), Some("true"), Some("yes"), Some(" TRUE ")] {
        assert!(
            community_leiden_enabled_value(value),
            "{value:?} must enable the M4 write-only shadow"
        );
    }
}

#[test]
fn genesis_shadow_enabled_is_explicit_opt_in() {
    // Unset is the case that matters most: it is what every install that never
    // heard of M6 evaluates, and it must leave the sub-second lane unspawned.
    for value in [
        None,
        Some(""),
        Some("0"),
        Some("false"),
        Some("no"),
        Some("off"),
        Some("garbage"),
    ] {
        assert!(
            !genesis_shadow_enabled_value(value),
            "{value:?} must leave the M6 genesis shadow lane unspawned"
        );
    }
    // `on` is accepted here although the sibling lane flags do not take it —
    // it is the natural partner of the `off` the falsey list already rejects.
    for value in [
        Some("1"),
        Some("true"),
        Some("yes"),
        Some("on"),
        Some(" TRUE "),
        Some("On"),
    ] {
        assert!(
            genesis_shadow_enabled_value(value),
            "{value:?} must enable the M6 genesis shadow lane"
        );
    }
}

