/// Migration 63 (P3): pages.workspace is added and backfilled from the
/// source memories' `space` column via the page_sources join.
#[tokio::test]
async fn m_ws_backfills_workspace_from_source_memory_space() {
    use crate::sources::RawDocument;
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let emitter: std::sync::Arc<dyn crate::EventEmitter> = std::sync::Arc::new(crate::NoopEmitter);
    let db = MemoryDB::new(&db_path, emitter).await.unwrap();

    // Two memories in distinct workspaces.
    db.upsert_documents(vec![
        RawDocument {
            source: "memory".into(),
            source_id: "mem_work_1".into(),
            title: "mem_work_1".into(),
            content: "alpha work fact".into(),
            memory_type: Some("fact".into()),
            space: Some("work".into()),
            last_modified: 1_700_000_000,
            ..Default::default()
        },
        RawDocument {
            source: "memory".into(),
            source_id: "mem_pers_1".into(),
            title: "mem_pers_1".into(),
            content: "beta personal fact".into(),
            memory_type: Some("fact".into()),
            space: Some("personal".into()),
            last_modified: 1_700_000_000,
            ..Default::default()
        },
    ])
    .await
    .unwrap();

    // A page per workspace whose source is the matching memory.
    let now = chrono::Utc::now().to_rfc3339();
    db.insert_page(
        "page_work",
        "Work Topic",
        Some("s"),
        "body",
        None,
        Some("recap"),
        &["mem_work_1"],
        &now,
    )
    .await
    .unwrap();
    db.insert_page(
        "page_pers",
        "Personal Topic",
        Some("s"),
        "body",
        None,
        Some("recap"),
        &["mem_pers_1"],
        &now,
    )
    .await
    .unwrap();

    // Roll user_version back so migration 63 re-runs over the seeded rows.
    {
        let conn = db.conn.lock().await;
        // M1: migration 80 made the scope columns NOT NULL. Relax them first so
        // the rollback can null out `workspace`; the migration 80 re-run below
        // rebuilds the NOT NULL constraint after migration 63 backfills.
        relax_pages_scope_columns_to_nullable(&conn).await;
        conn.execute("UPDATE pages SET workspace = NULL", ())
            .await
            .unwrap();
        // G6 Stage 2 PR 2b: `insert_page` no longer writes `page_sources`
        // post-cutover, so migration 63's `page_sources`-driven backfill SQL
        // would find nothing to read from a modern fixture. Raw-INSERT the
        // legacy rows migration 63 expects, simulating the pre-migration-63
        // historical DB state (same seeding pattern as migration_81's tests).
        conn.execute(
            "INSERT INTO page_sources (page_id, memory_source_id, linked_at, link_reason) VALUES ('page_work', 'mem_work_1', 1700000000, 'distill')",
            (),
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO page_sources (page_id, memory_source_id, linked_at, link_reason) VALUES ('page_pers', 'mem_pers_1', 1700000000, 'distill')",
            (),
        )
        .await
        .unwrap();
        conn.execute("PRAGMA user_version = 62", ()).await.unwrap();
    }
    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .unwrap();

    let conn = db.conn.lock().await;
    let mut rows = conn
        .query("SELECT id, workspace FROM pages ORDER BY id", ())
        .await
        .unwrap();
    let mut got = std::collections::HashMap::new();
    while let Some(r) = rows.next().await.unwrap() {
        got.insert(
            r.get::<String>(0).unwrap(),
            r.get::<Option<String>>(1).unwrap(),
        );
    }
    assert_eq!(
        got.get("page_pers").unwrap().as_deref(),
        Some("personal"),
        "page_pers workspace should be 'personal'"
    );
    assert_eq!(
        got.get("page_work").unwrap().as_deref(),
        Some("work"),
        "page_work workspace should be 'work'"
    );
}

