// ===== M3g Stage A: span capture payload tests =====

#[tokio::test]
async fn create_relation_with_span_writes_payload_and_keeps_parity_clean() {
    // A relation extracted with a locatable verbatim quote must carry
    // {source_memory_id, span, model_version, prompt_version} in
    // edges.payload. payload is a non-structural column, so
    // reconcile_edges_parity (which matches structural columns only)
    // must stay clean.
    let (db, _dir) = test_db().await;
    let e1 = db
        .create_entity("Alice", "person", Some("space_a"))
        .await
        .unwrap();
    let e2 = db
        .create_entity("Acme", "org", Some("space_a"))
        .await
        .unwrap();
    let content = "Alice works at Acme Corp.";
    seed_memory_with_source_id_and_space(&db, "mem_1", content, "space_a").await;

    db.create_relation_with_span(
        &e1,
        &e2,
        "works_at",
        Some("test"),
        None,
        None,
        Some("mem_1"),
        Some(content),
        Some(content),
        Some("qwen3-4b-instruct-2507"),
        Some(crate::extract::EXTRACT_KNOWLEDGE_GRAPH_PROMPT_VERSION),
    )
    .await
    .unwrap();
    // G6 Stage 2 PR 2b: parity oracle retired, correctness carried by per-writer regression tests (item 7).

    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT payload FROM edges WHERE edge_type = 'relates' AND src_id = ?1 AND dst_id = ?2",
            libsql::params![e1.clone(), e2.clone()],
        )
        .await
        .unwrap();
    let payload_text: String = rows
        .next()
        .await
        .unwrap()
        .expect("relates edge row")
        .get(0)
        .expect("payload must be non-NULL for a span-carrying write");
    let payload: serde_json::Value = serde_json::from_str(&payload_text).unwrap();
    assert_eq!(payload["source_memory_id"], serde_json::json!("mem_1"));
    assert_eq!(payload["span"]["quote"], serde_json::json!(content));
    assert_eq!(payload["span"]["char_start"], serde_json::json!(0));
    assert_eq!(
        payload["span"]["char_end"],
        serde_json::json!(content.chars().count())
    );
    assert_eq!(
        payload["model_version"],
        serde_json::json!("qwen3-4b-instruct-2507")
    );
    assert_eq!(
        payload["prompt_version"],
        serde_json::json!(crate::extract::EXTRACT_KNOWLEDGE_GRAPH_PROMPT_VERSION)
    );
}

#[tokio::test]
async fn source_backed_relation_retry_preserves_original_relation_and_edge_provenance() {
    let (db, _dir) = test_db().await;
    let e1 = db
        .create_entity("Alice", "person", Some("space_a"))
        .await
        .unwrap();
    let e2 = db
        .create_entity("Acme", "org", Some("space_a"))
        .await
        .unwrap();
    let content_a = "Alice works at Acme.";
    let content_b = "Acme employs Alice.";
    seed_memory_with_source_id_and_space(&db, "mem_a", content_a, "space_a").await;
    seed_memory_with_source_id_and_space(&db, "mem_b", content_b, "space_a").await;

    let first_id = db
        .create_relation_with_span(
            &e1,
            &e2,
            "works_at",
            Some("extractor"),
            Some(0.8),
            None,
            Some("mem_a"),
            Some(content_a),
            Some(content_a),
            Some("model-a"),
            Some("prompt-a"),
        )
        .await
        .unwrap();
    // G6 Stage 2 PR 2b: `relations` is frozen -- `asserted_at` must mirror
    // the ORIGINAL mint's stamp across the retry's re-assert, so capture it
    // here (before the retry) as the independent oracle, instead of reading
    // a `relations.created_at` that no longer exists.
    let original_asserted_at: i64 = {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT json_extract(payload, '$.asserted_at') FROM edges WHERE edge_id = ?1",
                libsql::params![first_id.clone()],
            )
            .await
            .unwrap();
        rows.next()
            .await
            .unwrap()
            .expect("relates edge")
            .get(0)
            .unwrap()
    };
    let retry_id = db
        .create_relation_with_span(
            &e1,
            &e2,
            "works_at",
            Some("extractor"),
            Some(0.9),
            None,
            Some("mem_b"),
            Some(content_b),
            Some(content_b),
            Some("model-b"),
            Some("prompt-b"),
        )
        .await
        .unwrap();
    assert_eq!(retry_id, first_id, "retry must converge on one relation");

    let conn = db.conn.lock().await;
    // G6 Stage 2 PR 2b: `relations` is frozen -- `edges` is the sole live
    // producer, so the "relation store" and "extraction edge" reads below
    // both resolve to the same edge (`first_id`/`retry_id` are the
    // content-addressed `edges.edge_id`, item 3 compat note).
    let mut relation_rows = conn
        .query(
            "SELECT json_extract(payload, '$.source_memory_id') FROM edges WHERE edge_id = ?1",
            libsql::params![first_id],
        )
        .await
        .unwrap();
    let relation_source: String = relation_rows
        .next()
        .await
        .unwrap()
        .expect("relates edge")
        .get(0)
        .unwrap();
    drop(relation_rows);

    let mut edge_rows = conn
        .query(
            "SELECT payload FROM edges
             WHERE edge_type = 'relates' AND src_id = ?1 AND dst_id = ?2",
            libsql::params![e1, e2],
        )
        .await
        .unwrap();
    let payload_text: String = edge_rows
        .next()
        .await
        .unwrap()
        .expect("relates edge row")
        .get(0)
        .expect("extraction edge payload");
    let payload: serde_json::Value = serde_json::from_str(&payload_text).unwrap();
    let edge_source = payload["source_memory_id"].as_str().unwrap();

    assert_eq!(relation_source, "mem_a");
    assert_eq!(edge_source, "mem_a");
    assert_eq!(payload["span"]["quote"], serde_json::json!(content_a));
    assert_eq!(payload["span"]["char_start"], serde_json::json!(0));
    assert_eq!(
        payload["span"]["char_end"],
        serde_json::json!(content_a.chars().count())
    );
    assert_eq!(payload["model_version"], serde_json::json!("model-a"));
    assert_eq!(payload["prompt_version"], serde_json::json!("prompt-a"));
    assert_eq!(
        relation_source, edge_source,
        "relation and extraction edge provenance must agree after retry"
    );

    // G6 Stage 1.2: asserted_at must still mirror the ORIGINAL stored row's
    // created_at (immutable under the upsert), never `now` at the retry;
    // confidence keeps the higher (0.9) value the retry supplied.
    assert_eq!(
        payload["asserted_at"],
        serde_json::json!(original_asserted_at),
        "asserted_at must mirror the ORIGINAL stored relation's created_at across the re-assert"
    );
    assert_eq!(
        payload["confidence"],
        serde_json::json!(0.9),
        "confidence must reflect the STORED (higher) value after the re-assert"
    );
}

#[tokio::test]
async fn create_relation_with_span_stores_unlocated_quote_as_null_offsets() {
    // §2.3: if the model's quote is not an exact substring of the
    // source memory's content, char_start/char_end are stored null --
    // the quote itself is still recorded, never guessed at or dropped.
    let (db, _dir) = test_db().await;
    let e1 = db
        .create_entity("Alice", "person", Some("space_a"))
        .await
        .unwrap();
    let e2 = db
        .create_entity("Acme", "org", Some("space_a"))
        .await
        .unwrap();
    let content = "Alice works at Acme Corp.";
    seed_memory_with_source_id_and_space(&db, "mem_2", content, "space_a").await;
    let fabricated_quote = "Alice is the CEO of Acme"; // not a substring of `content`

    db.create_relation_with_span(
        &e1,
        &e2,
        "works_at",
        Some("test"),
        None,
        None,
        Some("mem_2"),
        Some(fabricated_quote),
        Some(content),
        Some("qwen3-4b-instruct-2507"),
        Some(crate::extract::EXTRACT_KNOWLEDGE_GRAPH_PROMPT_VERSION),
    )
    .await
    .unwrap();

    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT payload FROM edges WHERE edge_type = 'relates' AND src_id = ?1 AND dst_id = ?2",
            libsql::params![e1.clone(), e2.clone()],
        )
        .await
        .unwrap();
    let payload_text: String = rows
        .next()
        .await
        .unwrap()
        .expect("relates edge row")
        .get(0)
        .expect("payload must be non-NULL for a span-carrying write");
    let payload: serde_json::Value = serde_json::from_str(&payload_text).unwrap();
    assert_eq!(
        payload["span"]["quote"],
        serde_json::json!(fabricated_quote),
        "the quote is stored even when it cannot be located"
    );
    assert!(
        payload["span"]["char_start"].is_null(),
        "an unlocated quote must not fabricate an offset"
    );
    assert!(payload["span"]["char_end"].is_null());
}

#[tokio::test]
async fn resolved_space_downgrades_gates_lineage_through_real_resolver() {
    // Round-5: the cross-space downgrade reason MUST come from the
    // destination's RESOLVED space, never be reconstructed from
    // `(lineage, dst_kind)`. This is the reviewer's negative test: a
    // same-space, DETERMINATE, non-external destination through the REAL
    // resolver must NOT downgrade (its edge stays typed, never `legacy`);
    // a differing space (cross-space) or an unresolved one (indeterminate)
    // MUST. Nothing here trusts the lineage label to infer the reason.

    // The pure seam every producer feeds the resolver's output through.
    assert!(
        !MemoryDB::resolved_space_downgrades(Some("space_a"), "space_a"),
        "same determinate space must NOT be a downgrade"
    );
    assert!(
        MemoryDB::resolved_space_downgrades(Some("space_b"), "space_a"),
        "a differing space (cross-space) must be a downgrade"
    );
    assert!(
        MemoryDB::resolved_space_downgrades(None, "space_a"),
        "an unresolved / indeterminate space must be a downgrade"
    );

    // The REAL resolver (`resolve_memory_space`) feeds the same seam.
    let (db, _dir) = test_db().await;
    seed_memory_with_source_id_and_space(&db, "mem_same", "content", "space_a").await;
    seed_memory_with_source_id_and_space(&db, "mem_cross", "content", "space_b").await;
    {
        let conn = db.conn.lock().await;
        let same = MemoryDB::resolve_memory_space(&conn, "mem_same")
            .await
            .unwrap();
        assert_eq!(same.as_deref(), Some("space_a"));
        assert!(
            !MemoryDB::resolved_space_downgrades(same.as_deref(), "space_a"),
            "a same-space memory resolved through the REAL resolver must not downgrade"
        );
        let cross = MemoryDB::resolve_memory_space(&conn, "mem_cross")
            .await
            .unwrap();
        assert!(
            MemoryDB::resolved_space_downgrades(cross.as_deref(), "space_a"),
            "a cross-space memory resolved through the REAL resolver must downgrade"
        );
        let absent = MemoryDB::resolve_memory_space(&conn, "mem_ghost")
            .await
            .unwrap();
        assert_eq!(absent, None, "an absent memory resolves to None");
        assert!(
            MemoryDB::resolved_space_downgrades(absent.as_deref(), "space_a"),
            "an unresolvable memory must downgrade (indeterminate)"
        );
        insert_raw_page_for_m81_test(&conn, "page_rr", "space_a").await;
    }

    // End-to-end: a same-space memory citation through the REAL producer
    // (`link_page_evidence` -> `resolve_memory_space` -> `dual_write_edge`)
    // must land `evidence`, never `legacy`. This is the property the proxy
    // could not guarantee: a non-external destination is legacy ONLY on a
    // genuine cross-space/indeterminate resolution.
    db.link_page_evidence("page_rr", "memory", Some("mem_same"), None, "test")
        .await
        .unwrap();
    let conn = db.conn.lock().await;
    let (lineage, _, _) = edge_row(&conn, "cites", "page_rr", "mem_same")
        .await
        .unwrap();
    assert_eq!(
        lineage, "evidence",
        "a same-space memory citation through the real producer must be 'evidence', never 'legacy'"
    );
}

#[tokio::test]
async fn dual_write_edge_reactivation_adopts_fresh_lineage() {
    // Item 4: reactivating a soft-invalidated edge must adopt the fresh
    // classification, not resurrect a stale lineage. An edge written
    // 'evidence' (same-space), invalidated, then reasserted after its
    // memory moved cross-space (caller passes 'legacy') must come back
    // 'legacy', not stale 'evidence'.
    let (db, _dir) = test_db().await;
    seed_memory_with_source_id_and_space(&db, "mem_r", "content", "space_a").await;
    let conn = db.conn.lock().await;
    insert_raw_page_for_m81_test(&conn, "page_r", "space_a").await;
    let edge_id = MemoryDB::dual_write_edge(
        &conn, "cites", "page", "page_r", "memory", "mem_r", "mem_r", "evidence", "space_a", false,
        None,
    )
    .await
    .unwrap();
    MemoryDB::dual_write_invalidate_edge(&conn, &edge_id, None)
        .await
        .unwrap();
    // The memory moved cross-space, so the caller now classifies 'legacy'.
    conn.execute(
        "UPDATE memories SET space = 'space_b' WHERE source_id = 'mem_r'",
        (),
    )
    .await
    .unwrap();
    MemoryDB::dual_write_edge(
        &conn, "cites", "page", "page_r", "memory", "mem_r", "mem_r", "legacy", "space_a", true,
        None,
    )
    .await
    .unwrap();
    let (lineage, _, _) = edge_row(&conn, "cites", "page_r", "mem_r").await.unwrap();
    assert_eq!(
        lineage, "legacy",
        "reactivation must adopt fresh 'legacy', not stale 'evidence'"
    );
    let valid_until: Option<i64> = {
        let mut rows = conn
            .query(
                "SELECT valid_until FROM edges WHERE edge_id = ?1",
                libsql::params![edge_id.clone()],
            )
            .await
            .unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert_eq!(valid_until, None, "reactivation must clear valid_until");
}

#[tokio::test]
async fn edges_after_update_fence_rejects_cross_space_reactivation() {
    // Item 4: the fence must validate UPDATEs, not only INSERTs. A buggy
    // caller that reactivates a typed edge whose endpoint has moved to a
    // different space must be rejected by the AFTER UPDATE fence.
    let (db, _dir) = test_db().await;
    seed_memory_with_source_id_and_space(&db, "mem_f", "content", "space_a").await;
    let conn = db.conn.lock().await;
    insert_raw_page_for_m81_test(&conn, "page_f", "space_a").await;
    let edge_id = MemoryDB::dual_write_edge(
        &conn, "cites", "page", "page_f", "memory", "mem_f", "mem_f", "evidence", "space_a", false,
        None,
    )
    .await
    .unwrap();
    MemoryDB::dual_write_invalidate_edge(&conn, &edge_id, None)
        .await
        .unwrap();
    conn.execute(
        "UPDATE memories SET space = 'space_b' WHERE source_id = 'mem_f'",
        (),
    )
    .await
    .unwrap();
    // Buggy reassert: keeps evidence/space_a though the memory is now cross-space.
    let result = MemoryDB::dual_write_edge(
        &conn, "cites", "page", "page_f", "memory", "mem_f", "mem_f", "evidence", "space_a", false,
        None,
    )
    .await;
    assert!(
        result.is_err(),
        "AFTER UPDATE fence must reject reactivating a typed edge whose dst is now cross-space"
    );
}

