#[tokio::test]
async fn cleanup_orphaned_page_sources_rolls_back_edge_invalidate_on_failure() {
    // Item 3: cleanup owns its BEGIN/COMMIT, so a mid-transaction fault
    // rolls back the edge soft-invalidate together with the legacy delete
    // -- not two independent autocommit writes.
    let edge_id =
        crate::provenance::compute_edge_id("cites", "page", "page_cl", "memory", "ghost", "ghost");
    let (db, _dir) = test_db().await;
    {
        let conn = db.conn.lock().await;
        insert_raw_page_for_m81_test(&conn, "page_cl", "space_a").await;
        conn.execute(
            "INSERT INTO page_sources (page_id, memory_source_id, linked_at, link_reason) \
             VALUES ('page_cl', 'ghost', 1, 'test')",
            (),
        )
        .await
        .unwrap();
        conn.execute("BEGIN", ()).await.unwrap();
        MemoryDB::dual_write_edge(
            &conn, "cites", "page", "page_cl", "memory", "ghost", "ghost", "legacy", "space_a",
            true, None,
        )
        .await
        .unwrap();
        conn.execute("COMMIT", ()).await.unwrap();
        conn.execute(
            "CREATE TRIGGER test_abort_pages_update BEFORE UPDATE ON pages \
             BEGIN SELECT RAISE(ABORT, 'test: pages update blocked'); END",
            (),
        )
        .await
        .unwrap();
    }
    let result = db.cleanup_orphaned_page_sources().await;
    assert!(result.is_err(), "the injected fault must fail the cleanup");
    let conn = db.conn.lock().await;
    let valid_until: Option<i64> = {
        let mut rows = conn
            .query(
                "SELECT valid_until FROM edges WHERE edge_id = ?1",
                libsql::params![edge_id],
            )
            .await
            .unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert_eq!(
        valid_until, None,
        "the edge invalidate must roll back with the legacy delete (single transaction)"
    );
}

// ===== M3 PR-1 stage (g): D7 shared citation-edge refcount =====

async fn edge_valid_until(conn: &libsql::Connection, edge_id: &str) -> Option<i64> {
    let mut rows = conn
        .query(
            "SELECT valid_until FROM edges WHERE edge_id = ?1",
            libsql::params![edge_id],
        )
        .await
        .unwrap();
    rows.next().await.unwrap().unwrap().get(0).unwrap()
}

#[tokio::test]
async fn cleanup_orphaned_page_sources_retracts_edge_even_when_backed_by_page_citations() {
    // G6 Stage 2 PR 2b (item 4): D7 (spec v3 M3) retired. Pruning an
    // orphaned page_sources row now retracts the shared `cites` edge_id
    // unconditionally -- `pages.citations` independently backing the same
    // (page, locator) pair no longer grants immunity; the column is a pure
    // render cache.
    let (db, _dir) = test_db().await;
    let edge_id = crate::provenance::compute_edge_id(
        "cites", "page", "page_pc", "memory", "mem_gone", "mem_gone",
    );
    {
        let conn = db.conn.lock().await;
        insert_raw_page_for_m81_test(&conn, "page_pc", "space_a").await;
        seed_page_source(&conn, "page_pc", "mem_gone").await;
        let citations = serde_json::json!([
            {"occurrence": 1, "marker": 1, "source_kind": "memory", "locator": "mem_gone",
             "score": 0.9, "status": "verified", "scope": "sentence"}
        ]);
        conn.execute(
            "UPDATE pages SET citations = ?1 WHERE id = 'page_pc'",
            libsql::params![citations.to_string()],
        )
        .await
        .unwrap();
        conn.execute("BEGIN", ()).await.unwrap();
        MemoryDB::dual_write_edge(
            &conn, "cites", "page", "page_pc", "memory", "mem_gone", "mem_gone", "legacy",
            "space_a", true, None,
        )
        .await
        .unwrap();
        conn.execute("COMMIT", ()).await.unwrap();
    }

    let removed = db.cleanup_orphaned_page_sources().await.unwrap();
    assert_eq!(removed, 1, "the orphaned edge must still be retracted");

    let conn = db.conn.lock().await;
    // G6 Stage 2 PR 2b (item 2, carried forward): `page_sources` is frozen
    // -- this sweep stopped deleting from it, so the seeded row persists.
    // The `edges` invalidate below is the sole canonical signal now.
    let ps_count: i64 = {
        let mut rows = conn
            .query(
                "SELECT COUNT(*) FROM page_sources WHERE page_id = 'page_pc'",
                (),
            )
            .await
            .unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert_eq!(
        ps_count, 1,
        "page_sources is frozen -- the orphaned row is untouched, not pruned"
    );
    assert!(
        edge_valid_until(&conn, &edge_id).await.is_some(),
        "D7 retired (item 4) -- pages.citations backing mem_gone no longer \
         keeps the shared edge active"
    );
}

/// G6 Stage 2 PR 2b (item 4): D7 retired. What used to be the "D7 survivor"
/// case -- an edge kept alive only by `pages.citations` backing after its
/// `page_sources` row was pruned -- no longer survives: cleanup retracts
/// the edge unconditionally, so `get_page_sources` reports nothing for it.
#[tokio::test]
async fn get_page_sources_omits_edge_retracted_despite_citations_backing() {
    let (db, _dir) = test_db().await;
    {
        let conn = db.conn.lock().await;
        insert_raw_page_for_m81_test(&conn, "page_d7", "space_a").await;
        seed_page_source(&conn, "page_d7", "mem_d7_gone").await;
        let citations = serde_json::json!([
            {"occurrence": 1, "marker": 1, "source_kind": "memory", "locator": "mem_d7_gone",
             "score": 0.9, "status": "verified", "scope": "sentence"}
        ]);
        conn.execute(
            "UPDATE pages SET citations = ?1 WHERE id = 'page_d7'",
            libsql::params![citations.to_string()],
        )
        .await
        .unwrap();
        conn.execute("BEGIN", ()).await.unwrap();
        MemoryDB::dual_write_edge(
            &conn,
            "cites",
            "page",
            "page_d7",
            "memory",
            "mem_d7_gone",
            "mem_d7_gone",
            "legacy",
            "space_a",
            true,
            None,
        )
        .await
        .unwrap();
        conn.execute("COMMIT", ()).await.unwrap();
    }

    // mem_d7_gone was never a real memory, so its page_sources row is an
    // orphan -- pruned by the cleanup sweep. D7 is retired (item 4), so
    // pages.citations backing no longer keeps the edge alive either; it
    // retracts along with the row.
    let removed = db.cleanup_orphaned_page_sources().await.unwrap();
    assert_eq!(removed, 1);

    let sources = db.get_page_sources("page_d7").await.unwrap();
    assert_eq!(
        sources.len(),
        0,
        "D7 retired (item 4) -- pages.citations backing no longer keeps the \
         edge active, so the retracted source must not be reported"
    );
}

/// G6 Stage 1.3 pin (closure ruling, 2026-08-05): `get_page_sources` is an
/// ENUMERATION reader and must return every `dst_kind`, not just `memory` --
/// the `dst_kind='memory'` filter this reader carried before the ruling
/// narrowed it below what legacy `page_sources` actually returned (that
/// table's dual-write, `insert_page`'s `INSERT OR IGNORE INTO page_sources`,
/// has no kind check -- see the spec's "Reader migration table" note). Seeds
/// one memory-kind and one external-kind cites edge on the same page and
/// asserts both come back, ordering discipline intact.
#[tokio::test]
async fn get_page_sources_returns_external_kind_locators_alongside_memory() {
    let (db, _dir) = test_db().await;
    {
        let conn = db.conn.lock().await;
        insert_raw_page_for_m81_test(&conn, "page_ext_pin", "space_a").await;
        conn.execute("BEGIN", ()).await.unwrap();
        MemoryDB::dual_write_edge(
            &conn,
            "cites",
            "page",
            "page_ext_pin",
            "memory",
            "mem_ext_pin",
            "mem_ext_pin",
            "legacy",
            "space_a",
            true,
            None,
        )
        .await
        .unwrap();
        MemoryDB::dual_write_edge(
            &conn,
            "cites",
            "page",
            "page_ext_pin",
            "external",
            "https://example.test/g6-ext-pin",
            "https://example.test/g6-ext-pin",
            "legacy",
            "space_a",
            true,
            None,
        )
        .await
        .unwrap();
        conn.execute("COMMIT", ()).await.unwrap();
        // `dual_write_edge` (the test helper above) writes a NULL payload, and
        // `json_set(NULL, ...)` is a SQLite no-op -- seed a valid JSON object
        // first so the linked_at write actually lands.
        conn.execute(
            "UPDATE edges SET payload = json_set(COALESCE(payload, '{}'), '$.linked_at', 100) \
             WHERE edge_type = 'cites' AND src_id = 'page_ext_pin' AND dst_kind = 'memory'",
            (),
        )
        .await
        .unwrap();
        conn.execute(
            "UPDATE edges SET payload = json_set(COALESCE(payload, '{}'), '$.linked_at', 200) \
             WHERE edge_type = 'cites' AND src_id = 'page_ext_pin' AND dst_kind = 'external'",
            (),
        )
        .await
        .unwrap();
    }

    let sources = db.get_page_sources("page_ext_pin").await.unwrap();
    assert_eq!(
        sources.len(),
        2,
        "an external-kind cites edge must not be filtered out of page-source enumeration"
    );
    assert_eq!(sources[0].memory_source_id, "mem_ext_pin");
    assert_eq!(sources[0].linked_at, 100);
    assert_eq!(
        sources[1].memory_source_id,
        "https://example.test/g6-ext-pin"
    );
    assert_eq!(sources[1].linked_at, 200);
}

