#[tokio::test]
async fn dual_write_page_citations_retracts_dropped_citation_when_unbacked() {
    // D7: a citation dropped from pages.citations with NO other legacy
    // store backing it must actually retract the edge -- including via
    // the NULL failure-fallback write (round-2 item #2's "returns
    // without cleanup for NULL/malformed JSON" gap) -- never leaving a
    // removed citation's edge dangling active.
    let (db, _dir) = test_db().await;
    let edge_id =
        crate::provenance::compute_edge_id("cites", "page", "page_dc2", "memory", "mem_x", "mem_x");
    {
        let conn = db.conn.lock().await;
        insert_raw_page_for_m81_test(&conn, "page_dc2", "space_a").await;
    }
    let initial = serde_json::json!([
        {"occurrence": 1, "marker": 1, "source_kind": "memory", "locator": "mem_x",
         "score": 0.9, "status": "verified", "scope": "sentence"}
    ]);
    db.set_page_citations("page_dc2", Some(&initial.to_string()))
        .await
        .unwrap();
    {
        let conn = db.conn.lock().await;
        assert_eq!(
            edge_valid_until(&conn, &edge_id).await,
            None,
            "sanity: the edge is asserted active by the initial citation write"
        );
    }

    // Explicit failure-fallback reset to NULL -- no other store backs
    // mem_x, so the edge must retract.
    db.set_page_citations("page_dc2", None).await.unwrap();

    let conn = db.conn.lock().await;
    assert!(
        edge_valid_until(&conn, &edge_id).await.is_some(),
        "no legacy store backs mem_x anymore -- the edge must retract, not dangle active"
    );
}

// G6 Stage 2 PR 2b (item 4) retired `refcount_retracts_only_after_last_
// backing_store_drops_citation`: it asserted D7's order-independent refcount
// -- an edge stays active until BOTH page_evidence and pages.citations drop
// their backing, whichever goes first. D7 itself is retired (`dual_write_
// page_citations`, db.rs: no more `cites_backed_by_page_citations`/`cites_
// backed_outside_page_citations` helpers); pages.citations is a pure render
// cache now and grants the shared edge no immunity. The post-item-4 contract
// (edge retires when the ONE remaining backing store -- a live `memories`
// row -- drops, regardless of citations JSON) is pinned by
// `cleanup_orphaned_page_sources_retracts_edge_even_when_backed_by_page_
// citations` and `get_page_sources_omits_edge_retracted_despite_citations_
// backing` above -- both renamed and flipped in this PR from their
// pre-item-4 D7-survivor assertions, not pre-existing coverage.

// ---- G6 Stage 0: dual-write gap regression tests (parity oracle) ----

/// `fold_relation_type` mutates `relation_type` — a structural field of the
/// content-addressed edge id — so it must retire the old-type edge and assert
/// the canonical-type one, in both the simple-rename and the collision-merge
/// branch. The oracle is the ambient parity sweep itself: drift 0 after a fold.
#[tokio::test]
async fn fold_relation_type_dual_writes_edges() {
    let (db, _dir) = test_db().await;
    db.create_space("work", None, false).await.unwrap();
    let a = db
        .store_entity("Fold A", "concept", Some("work"), Some("test"), None)
        .await
        .unwrap();
    let b = db
        .store_entity("Fold B", "concept", Some("work"), Some("test"), None)
        .await
        .unwrap();
    let c = db
        .store_entity("Fold C", "concept", Some("work"), Some("test"), None)
        .await
        .unwrap();

    // Simple rename: a->c carries only the old type (both are vocabulary
    // canonicals) and a source memory whose id must survive the fold.
    db.create_relation(
        &a,
        &c,
        "works_on",
        Some("test"),
        None,
        None,
        Some("mem_fold_ac"),
    )
    .await
    .unwrap();
    // Collision merge: a->b carries BOTH the old and the canonical type.
    db.create_relation(&a, &b, "works_on", Some("test"), None, None, None)
        .await
        .unwrap();
    db.create_relation(&a, &b, "leads", Some("test"), None, None, None)
        .await
        .unwrap();
    // G6 Stage 2 PR 2b: parity oracle retired, correctness carried by per-writer regression tests (item 7).

    let folded = db.fold_relation_type("works_on", "leads").await.unwrap();
    assert_eq!(folded, 2);

    // Belt-and-braces: the old-type edges are retired, superseded by canonical.
    let conn = db.conn.lock().await;
    for to in [&b, &c] {
        let old_edge_id =
            crate::provenance::compute_edge_id("relates", "entity", &a, "entity", to, "works_on");
        let new_edge_id =
            crate::provenance::compute_edge_id("relates", "entity", &a, "entity", to, "leads");
        let mut rows = conn
            .query(
                "SELECT valid_until, superseded_by FROM edges WHERE edge_id = ?1",
                libsql::params![old_edge_id.as_str()],
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().expect("old-type edge exists");
        assert!(
            row.get::<Option<i64>>(0).unwrap().is_some(),
            "old-type edge is retired"
        );
        assert_eq!(
            row.get::<Option<String>>(1).unwrap().as_deref(),
            Some(new_edge_id.as_str()),
            "old-type edge points at its canonical successor"
        );
    }
    // Review finding #11: the simple-rename branch mints the canonical-type
    // edge WITH the retired edge's payload, so `source_memory_id` survives.
    let new_ac = crate::provenance::compute_edge_id("relates", "entity", &a, "entity", &c, "leads");
    let mut rows = conn
        .query(
            "SELECT json_extract(payload,'$.source_memory_id') FROM edges \
             WHERE edge_id = ?1 AND valid_until IS NULL",
            libsql::params![new_ac.as_str()],
        )
        .await
        .unwrap();
    let row = rows
        .next()
        .await
        .unwrap()
        .expect("canonical a->c edge exists");
    assert_eq!(
        row.get::<Option<String>>(0).unwrap().as_deref(),
        Some("mem_fold_ac"),
        "folded edge keeps the retired edge's source_memory_id"
    );
}

/// `replace_page_sources` prunes `page_sources` + memory-kind `page_evidence`
/// rows and NULLs `pages.citations` — every legacy backing of a pruned sid's
