/// A crash between m81's COMMIT and its `user_version = 81` stamp on a
/// pre-G6 binary leaves an `edges` table WITHOUT `semantic_type` at
/// user_version 80. The m81 rerun's CREATE IF NOT EXISTS cannot widen it,
/// and its backfill INSERTs name the column — the rerun must probe-add it
/// instead of failing startup (G6 Stage 1 post-merge review finding #2).
#[tokio::test]
async fn migration_81_rerun_recovers_pre_semantic_type_edges_table() {
    let (db, _dir) = test_db().await;
    // A live relation guarantees the rerun actually executes a backfill
    // INSERT that names `semantic_type` (an empty store would pass
    // vacuously and m98's guard would mask the defect).
    let e1 = db.create_entity("G6RerunA", "person", None).await.unwrap();
    let e2 = db.create_entity("G6RerunB", "person", None).await.unwrap();
    db.create_relation(&e1, &e2, "knows", Some("claude"), None, None, None)
        .await
        .unwrap();
    {
        let conn = db.conn.lock().await;
        conn.execute("ALTER TABLE edges DROP COLUMN semantic_type", ())
            .await
            .expect("drop semantic_type to emulate the pre-G6 partial state");
        conn.execute("PRAGMA user_version = 80", ()).await.unwrap();
    }
    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("m81 rerun must widen the pre-existing edges table, not fail its backfill INSERTs");
    let conn = db.conn.lock().await;
    let mut rows = conn
        .query(
            "SELECT COUNT(*) FROM pragma_table_info('edges') WHERE name = 'semantic_type'",
            (),
        )
        .await
        .unwrap();
    let present: i64 = rows.next().await.unwrap().unwrap().get(0).unwrap();
    assert_eq!(present, 1, "semantic_type restored by the m81 rerun guard");
    drop(rows);
    let mut vrows = conn.query("PRAGMA user_version", ()).await.unwrap();
    let uv: i64 = vrows.next().await.unwrap().unwrap().get(0).unwrap();
    assert_eq!(
        uv as u32,
        crate::db::SCHEMA_VERSION,
        "chain completes back to the current schema version"
    );
}

/// G6 Stage 2 PR 2c frozen-replay fix, RED control. Simulates the exact
/// upgrade window the bug was in: an old DB reaching migration 97 (just
/// before migration 98 installs the space fence in its M5-widened shape),
/// with an entity missing its shadow page (shadow-page completeness is not
/// guaranteed until migrations 113/114/117 run) and a bare `relations` row
/// migration 111 will backfill into an edge -- the exact shape migration
/// 111's own tests already use for the ambient-lane-left-no-edge damage.
///
/// Rolling `PRAGMA user_version` back only to 110 cannot reproduce this: it
/// skips re-running migrations 81/98 (both guarded by `version < N` below
/// 110), so the fence trigger stays whatever the DB's ORIGINAL `test_db()`
/// build already installed, and neither code path is exercised. Rolling
/// back to 97 puts migration 98 back in the replay path, so it reinstalls
/// the fence trigger from `edges_rebuild.rs`'s current `FENCE_BODY` --
/// exactly the historical-vs-ported distinction under test.
///
/// Falsifiability (hand-verified, not asserted here since this test can only
/// run against one tree at a time): temporarily reverting `FENCE_BODY`'s
/// `entity` arm back to the ported `entity_page_map` form reproduces the
/// original defect -- migration 111's backfill aborts with
/// `edges_space_fence: cross-space edge rejected` and `run_migrations`
/// returns `Err`, bricking the chain. Restoring the frozen historical form
/// (this tree) lets migration 111 replay under the fence active at ITS
/// point in the timeline, which does not consult the shadow page, so the
/// backfill succeeds; migration 121 only re-installs the pages-reading
/// fence afterward, once migrations 113/114/117 have already run.
#[tokio::test]
async fn migration_121_split_survives_shadow_gap_during_m111_replay() {
    let (db, _dir) = test_db().await;
    db.create_space("work", None, false).await.unwrap();
    let a = db
        .store_entity("A", "concept", Some("work"), Some("test"), None)
        .await
        .unwrap();
    let b = db
        .store_entity("B", "concept", Some("work"), Some("test"), None)
        .await
        .unwrap();
    db.test_create_legacy_entity_tables().await.unwrap();
    {
        let conn = db.conn.lock().await;
        // G6 Stage 2 PR 2c sub-step 3 item 5: `store_entity` no longer
        // writes `entities`, but `relations.from_entity`/`to_entity` still
        // FK-reference it -- raw-seed the legacy rows (mirroring what
        // store_entity used to write pre-flip). This is a SEPARATE row
        // from the shadow-page gap simulated below (entity_page_map, not
        // entities), so it doesn't undo that damage. NOT converted to
        // `test_seed_entity_shadow_page`: `store_entity` above already
        // minted a's and b's shadow pages + `entity_page_map` rows, so a
        // second seed call per id would collide on `entity_page_map`'s
        // `entity_id` PRIMARY KEY. G6 Stage 3 migration 123 dropped
        // `entities` entirely, so the pre-123 table is stood back up above
        // via `test_create_legacy_entity_tables` for this frozen replay.
        conn.execute(
            "INSERT INTO entities (id, name, entity_type, space, source_agent, created_at, updated_at) \
             VALUES (?1, 'A', 'concept', 'work', 'test', unixepoch(), unixepoch()), \
                    (?2, 'B', 'concept', 'work', 'test', unixepoch(), unixepoch())",
            libsql::params![a.as_str(), b.as_str()],
        )
        .await
        .unwrap();
        // The damage: a's shadow page is missing, simulating an upgrade
        // reaching migration 98 before migrations 113/114/117 repair it.
        conn.execute(
            "DELETE FROM entity_page_map WHERE entity_id = ?1",
            libsql::params![a.as_str()],
        )
        .await
        .unwrap();
        // The shape the old ambient lane left: a relation with no edge twin,
        // same as migration 111's own bare-relation tests above.
        conn.execute(
            "INSERT INTO relations
                 (id, from_entity, to_entity, relation_type, source_agent,
                  confidence, explanation, source_memory_id, created_at)
             VALUES ('rel_g6_shadow_gap', ?1, ?2, 'related_to', 'post_ingest', NULL, NULL, NULL, 1)",
            libsql::params![a.as_str(), b.as_str()],
        )
        .await
        .unwrap();
        conn.execute("PRAGMA user_version = 97", ()).await.unwrap();
    }

    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("migration 111's backfill must not abort on a's missing shadow page");

    let edge_id =
        crate::provenance::compute_edge_id("relates", "entity", &a, "entity", &b, "related_to");
    let conn = db.conn.lock().await;
    let (lineage, valid_until): (String, Option<i64>) = {
        let mut rows = conn
            .query(
                "SELECT lineage, valid_until FROM edges WHERE edge_id = ?1",
                libsql::params![edge_id.as_str()],
            )
            .await
            .unwrap();
        let row = rows
            .next()
            .await
            .unwrap()
            .expect("migration 111 must have backfilled the bare relation into an edge");
        (row.get(0).unwrap(), row.get::<Option<i64>>(1).unwrap())
    };
    assert_eq!(
        lineage, "assertion",
        "both entities share one Space, so the backfilled edge is first-class"
    );
    assert!(valid_until.is_none(), "the backfilled edge is active");

    let mut vrows = conn.query("PRAGMA user_version", ()).await.unwrap();
    let uv: i64 = vrows.next().await.unwrap().unwrap().get(0).unwrap();
    assert_eq!(
        uv as u32,
        crate::db::SCHEMA_VERSION,
        "chain completes back to the current schema version, past migration 121"
    );
}

/// G6 Stage 2 PR 2c sub-step 3 (m122), acceptance criterion (b): once
/// `entity_page_map`/`observations`/`memory_entities`/`entity_minhash_bands`
/// no longer carry `REFERENCES entities(id)`, a shadow-only entity id (a
/// `kind='entity'` page + `entity_page_map` row with deliberately NO
/// `entities` row -- the ordinary post-flip state once item 4, this same
/// PR, stops writing `entities` at all) must be linkable through every one
/// of the four rebuilt tables with `foreign_keys` left ON throughout.
/// Reverting migration 122 (restoring any one table's `entities` FK) flips
/// this from pass to fail with a `FOREIGN KEY constraint failed` error.
#[tokio::test]
async fn migration_122_shadow_only_entity_links_insert_with_fk_on() {
    let (db, _dir) = test_db().await;
    const SHADOW_ONLY_ID: &str = "m122-shadow-only-entity";
    let now_iso = chrono::Utc::now().to_rfc3339();
    let now_unix = chrono::Utc::now().timestamp();

    let conn = db.conn.lock().await;
    let fk_state: i64 = {
        let mut rows = conn.query("PRAGMA foreign_keys", ()).await.unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert_eq!(
        fk_state, 1,
        "foreign_keys must be ON for this to be a real test of the relaxed FK"
    );

    conn.execute(
        "INSERT INTO pages (
            id, title, summary, content, kind, entity_type, confidence, entity_confirmed,
            embedding, space, workspace, source_memory_ids, version, status,
            created_at, last_compiled, last_modified, creation_kind, review_status
         ) VALUES (
            'm122-shadow-only-page', 'M122 Shadow Only', NULL, '', 'entity', 'concept', NULL, 0,
            NULL, 'unfiled', 'unfiled', '[]', 1, 'active', ?1, ?1, ?1, 'entity', 'unconfirmed'
         )",
        libsql::params![now_iso.clone()],
    )
    .await
    .expect("shadow page insert must succeed with foreign_keys ON");

    conn.execute(
        "INSERT INTO entity_page_map (entity_id, page_id, created_at)
         VALUES (?1, 'm122-shadow-only-page', ?2)",
        libsql::params![SHADOW_ONLY_ID, now_iso.clone()],
    )
    .await
    .expect(
        "entity_page_map insert for a shadow-only entity must succeed \
         with foreign_keys ON (migration 122)",
    );

    conn.execute(
        "INSERT INTO memory_entities (memory_id, entity_id) VALUES ('m122-mem', ?1)",
        libsql::params![SHADOW_ONLY_ID],
    )
    .await
    .expect(
        "memory_entities insert for a shadow-only entity must succeed \
         with foreign_keys ON (migration 122)",
    );

    // Same fix, same shape -- the other two m122-rebuilt tables accept a
    // shadow-only entity id too.
    conn.execute(
        "INSERT INTO observations
            (id, entity_id, content, source_memory_id, source_agent, confidence, confirmed, created_at)
         VALUES ('m122-obs', ?1, 'shadow-only observation', NULL, 'test', NULL, 0, ?2)",
        libsql::params![SHADOW_ONLY_ID, now_unix],
    )
    .await
    .expect(
        "observations insert for a shadow-only entity must succeed \
         with foreign_keys ON (migration 122)",
    );

    conn.execute(
        "INSERT INTO entity_minhash_bands (band_key, entity_id) VALUES (12345, ?1)",
        libsql::params![SHADOW_ONLY_ID],
    )
    .await
    .expect(
        "entity_minhash_bands insert for a shadow-only entity must succeed \
         with foreign_keys ON (migration 122)",
    );
}

/// G6 Stage 2 PR 2c sub-step 3 (m122), acceptance criterion (c): the
/// create/copy/drop/rename rebuild must not lose data. Seeds rows in all
/// four tables migration 122 rebuilds (mixing a real entity id with a
/// shadow-only one, so the rebuild's blind `SELECT ... FROM X` copy is
/// proven indifferent to which kind of row it is moving), rolls
/// `user_version` back to 121, then reruns `run_migrations` -- the table
/// SHAPES are already the rebuilt shape from `test_db()`'s initial
/// migration pass, but the dispatch chain only consults `user_version`, so
/// this exercises `migrate_122_relax_entity_fk_dependents`'s rebuild again
/// exactly as an upgrading database's replay would, and doubles as an
/// idempotent-rerun check. Row counts and spot-checked content must survive
/// unchanged.
#[tokio::test]
async fn migration_122_rebuild_preserves_existing_rows_across_replay() {
    let (db, _dir) = test_db().await;
    let real_entity = db
        .store_entity("M122 Preserve", "concept", None, Some("test"), None)
        .await
        .unwrap();
    const SHADOW_ONLY_ID: &str = "m122-preserve-shadow";
    let now_iso = chrono::Utc::now().to_rfc3339();
    let now_unix = chrono::Utc::now().timestamp();

    {
        let conn = db.conn.lock().await;
        conn.execute(
            "INSERT INTO pages (
                id, title, summary, content, kind, entity_type, confidence, entity_confirmed,
                embedding, space, workspace, source_memory_ids, version, status,
                created_at, last_compiled, last_modified, creation_kind, review_status
             ) VALUES (
                'm122-preserve-page', 'M122 Preserve Shadow', NULL, '', 'entity', 'concept', NULL, 0,
                NULL, 'unfiled', 'unfiled', '[]', 1, 'active', ?1, ?1, ?1, 'entity', 'unconfirmed'
             )",
            libsql::params![now_iso.clone()],
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO entity_page_map (entity_id, page_id, created_at)
             VALUES (?1, 'm122-preserve-page', ?2)",
            libsql::params![SHADOW_ONLY_ID, now_iso.clone()],
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO observations
                (id, entity_id, content, source_memory_id, source_agent, confidence, confirmed, created_at)
             VALUES ('m122-preserve-obs', ?1, 'preserve me across the rebuild', NULL, 'test', 0.5, 1, ?2)",
            libsql::params![real_entity.as_str(), now_unix],
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO memory_entities (memory_id, entity_id) VALUES ('m122-preserve-mem-real', ?1)",
            libsql::params![real_entity.as_str()],
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO memory_entities (memory_id, entity_id) VALUES ('m122-preserve-mem-shadow', ?1)",
            libsql::params![SHADOW_ONLY_ID],
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO entity_minhash_bands (band_key, entity_id) VALUES (54321, ?1)",
            libsql::params![SHADOW_ONLY_ID],
        )
        .await
        .unwrap();
    }

    async fn table_count(conn: &libsql::Connection, table: &str) -> i64 {
        let mut rows = conn
            .query(&format!("SELECT COUNT(*) FROM {table}"), ())
            .await
            .unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    }

    // Index + trigger inventory for the four m122-rebuilt tables, normalized
    // (whitespace collapsed) so a DROP TABLE followed by a byte-identical
    // recreate can't silently pass while a REFORMATTED-but-different
    // recreate would fail loud. sqlite_autoindex_* entries (SQL is NULL,
    // auto-generated from PRIMARY KEY/UNIQUE column constraints already in
    // the CREATE TABLE body) are excluded on purpose -- they need no replay
    // code of their own, so comparing them would only assert that SQLite's
    // own autoindex-naming scheme is stable, not that migration 122 did its
    // job.
    async fn schema_objects(conn: &libsql::Connection) -> Vec<(String, String, String)> {
        let mut rows = conn
            .query(
                "SELECT type, name, sql FROM sqlite_master \
                 WHERE tbl_name IN ('entity_page_map','observations','memory_entities','entity_minhash_bands') \
                 AND type IN ('index','trigger') \
                 AND name NOT LIKE 'sqlite_autoindex_%' \
                 ORDER BY type, name",
                (),
            )
            .await
            .unwrap();
        let mut objects = Vec::new();
        while let Some(row) = rows.next().await.unwrap() {
            let obj_type: String = row.get(0).unwrap();
            let name: String = row.get(1).unwrap();
            let sql: String = row.get::<String>(2).unwrap();
            let normalized: String = sql.split_whitespace().collect::<Vec<_>>().join(" ");
            objects.push((obj_type, name, normalized));
        }
        objects
    }

    let (before_epm, before_obs, before_me, before_bands, before_schema) = {
        let conn = db.conn.lock().await;
        (
            table_count(&conn, "entity_page_map").await,
            table_count(&conn, "observations").await,
            table_count(&conn, "memory_entities").await,
            table_count(&conn, "entity_minhash_bands").await,
            schema_objects(&conn).await,
        )
    };

    {
        let conn = db.conn.lock().await;
        conn.execute("PRAGMA user_version = 121", ()).await.unwrap();
    }

    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("migration 122 rerun must not fail or lose data on an already-rebuilt table");

    let conn = db.conn.lock().await;
    let after_epm = table_count(&conn, "entity_page_map").await;
    let after_obs = table_count(&conn, "observations").await;
    let after_me = table_count(&conn, "memory_entities").await;
    let after_bands = table_count(&conn, "entity_minhash_bands").await;
    let after_schema = schema_objects(&conn).await;
    assert_eq!(
        before_schema, after_schema,
        "the rebuild's index + trigger inventory (name, normalized SQL) for \
         entity_page_map/observations/memory_entities/entity_minhash_bands \
         must be identical before and after the replay -- a dropped index \
         or trigger that DROP TABLE destroys and the migration forgets to \
         recreate would otherwise pass silently on row counts alone"
    );
    assert_eq!(
        before_epm, after_epm,
        "entity_page_map row count must survive the rebuild"
    );
    assert_eq!(
        before_obs, after_obs,
        "observations row count must survive the rebuild"
    );
    assert_eq!(
        before_me, after_me,
        "memory_entities row count must survive the rebuild"
    );
    assert_eq!(
        before_bands, after_bands,
        "entity_minhash_bands row count must survive the rebuild"
    );

    let preserved_page_id: String = {
        let mut rows = conn
            .query(
                "SELECT page_id FROM entity_page_map WHERE entity_id = ?1",
                libsql::params![SHADOW_ONLY_ID],
            )
            .await
            .unwrap();
        rows.next()
            .await
            .unwrap()
            .expect("shadow-only entity_page_map row must survive")
            .get(0)
            .unwrap()
    };
    assert_eq!(preserved_page_id, "m122-preserve-page");

    let preserved_content: String = {
        let mut rows = conn
            .query(
                "SELECT content FROM observations WHERE id = 'm122-preserve-obs'",
                (),
            )
            .await
            .unwrap();
        rows.next()
            .await
            .unwrap()
            .expect("observation row must survive")
            .get(0)
            .unwrap()
    };
    assert_eq!(preserved_content, "preserve me across the rebuild");

    let band_entity: String = {
        let mut rows = conn
            .query(
                "SELECT entity_id FROM entity_minhash_bands WHERE band_key = 54321",
                (),
            )
            .await
            .unwrap();
        rows.next()
            .await
            .unwrap()
            .expect("entity_minhash_bands row must survive")
            .get(0)
            .unwrap()
    };
    assert_eq!(band_entity, SHADOW_ONLY_ID);

    let mut vrows = conn.query("PRAGMA user_version", ()).await.unwrap();
    let uv: i64 = vrows.next().await.unwrap().unwrap().get(0).unwrap();
    assert_eq!(
        uv as u32,
        crate::db::SCHEMA_VERSION,
        "chain completes back to the current schema version, past migration 122"
    );
}

// ---------------------------------------------------------------------------
// G6 Stage 3 -- migration 123, the point of no return.
// ---------------------------------------------------------------------------

/// Snapshot of `sqlite_master` names for one object type.
async fn schema_names(conn: &libsql::Connection, object_type: &str) -> Vec<String> {
    let mut rows = conn
        .query(
            "SELECT name FROM sqlite_master WHERE type = ?1 ORDER BY name",
            libsql::params![object_type],
        )
        .await
        .unwrap();
    let mut names = Vec::new();
    while let Some(row) = rows.next().await.unwrap() {
        names.push(row.get::<String>(0).unwrap());
    }
    names
}

/// The upgrade-chain replay. Stands a database back up in its pre-123 shape --
/// `entities` + `entity_aliases` present, and `relations` carrying the two
/// `REFERENCES entities(id) ON DELETE CASCADE` foreign keys migration 123 is
/// specified to remove -- rewinds `user_version` to 122, and replays the chain
/// through `run_migrations`. Restoring the pre-123 `relations` shape is what
/// makes the FK assertion real: asserting against the shape `test_db()` already
/// left behind would only re-observe the migration that already ran.
///
/// Mutation control: delete the `relations` rebuild from
/// `migrate_123_retire_legacy_entity_tables` and the `REFERENCES` assertion
/// goes red; delete the two `DROP TABLE` statements and the drop assertion
/// goes red; delete the trigger port and the trigger assertions go red.
#[tokio::test]
async fn migration_123_drops_legacy_tables_relaxes_relations_and_ports_triggers() {
    let (db, _dir) = test_db().await;
    db.test_create_legacy_entity_tables().await.unwrap();

    {
        let conn = db.conn.lock().await;
        conn.execute_batch(
            "INSERT INTO entities
                 (id, name, entity_type, space, confidence, confirmed, created_at, updated_at)
             VALUES ('m123-ent-a', 'M123 A', 'concept', 'work', NULL, 0, 1, 1),
                    ('m123-ent-b', 'M123 B', 'concept', 'work', NULL, 0, 1, 1);
             INSERT INTO entity_aliases (alias_name, canonical_entity_id, created_at)
             VALUES ('m123 a alias', 'm123-ent-a', 1);

             -- The pre-123 `relations` shape, foreign keys and all.
             DROP TABLE relations;
             CREATE TABLE relations (
                 id TEXT PRIMARY KEY,
                 from_entity TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE,
                 to_entity TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE,
                 relation_type TEXT NOT NULL,
                 source_agent TEXT,
                 created_at INTEGER NOT NULL,
                 confidence REAL,
                 explanation TEXT,
                 source_memory_id TEXT
             );
             CREATE INDEX idx_relations_from ON relations(from_entity, to_entity);
             CREATE INDEX idx_relations_to ON relations(to_entity, from_entity);
             CREATE UNIQUE INDEX idx_relations_unique
                 ON relations(from_entity, to_entity, relation_type);
             INSERT INTO relations
                 (id, from_entity, to_entity, relation_type, source_agent,
                  created_at, confidence, explanation, source_memory_id)
             VALUES ('m123-rel', 'm123-ent-a', 'm123-ent-b', 'relates', 'test',
                     1, 0.5, 'survives the rebuild', 'm123-mem');

             PRAGMA user_version = 122;",
        )
        .await
        .unwrap();
    }

    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("migration 123 must replay from a pre-123 database");

    let conn = db.conn.lock().await;

    let tables = schema_names(&conn, "table").await;
    for dropped in ["entities", "entity_aliases"] {
        assert!(
            !tables.iter().any(|name| name == dropped),
            "migration 123 must drop `{dropped}`; tables: {tables:?}"
        );
    }
    // The survivors. `memory_entities`, `observations`, `entity_page_map`,
    // `relations`, `page_sources`, and `page_links` are explicitly NOT in the
    // drop set -- they hold live data keyed by entity id or page id.
    for survivor in [
        "memory_entities",
        "observations",
        "entity_page_map",
        "relations",
        "page_sources",
        "page_links",
        "pages",
    ] {
        assert!(
            tables.iter().any(|name| name == survivor),
            "migration 123 must leave `{survivor}` in place; tables: {tables:?}"
        );
    }

    let relations_sql: String = {
        let mut rows = conn
            .query(
                "SELECT sql FROM sqlite_master WHERE type='table' AND name='relations'",
                (),
            )
            .await
            .unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert!(
        !relations_sql.contains("REFERENCES"),
        "relations must be rebuilt without its entity foreign keys: {relations_sql}"
    );

    let indexes = schema_names(&conn, "index").await;
    for index in [
        "idx_relations_from",
        "idx_relations_to",
        "idx_relations_unique",
    ] {
        assert!(
            indexes.iter().any(|name| name == index),
            "the relations rebuild must recreate `{index}`; indexes: {indexes:?}"
        );
    }

    let (explanation, row_count): (String, i64) = {
        let mut rows = conn
            .query(
                "SELECT explanation, (SELECT COUNT(*) FROM relations) FROM relations WHERE id='m123-rel'",
                (),
            )
            .await
            .unwrap();
        let row = rows
            .next()
            .await
            .unwrap()
            .expect("the seeded relation must survive the rebuild");
        (row.get(0).unwrap(), row.get(1).unwrap())
    };
    assert_eq!(explanation, "survives the rebuild");
    assert_eq!(row_count, 1);

    let triggers = schema_names(&conn, "trigger").await;
    for ported in [
        "m4_grouping_entity_insert",
        "m4_grouping_entity_delete",
        "m4_grouping_entity_update",
        "m4_parity_input_entity_insert",
        "m4_parity_input_entity_delete",
        "m4_parity_input_entity_update",
    ] {
        let mut rows = conn
            .query(
                "SELECT tbl_name FROM sqlite_master WHERE type='trigger' AND name=?1",
                libsql::params![ported],
            )
            .await
            .unwrap();
        let target: String = rows
            .next()
            .await
            .unwrap()
            .unwrap_or_else(|| panic!("`{ported}` must survive the port; triggers: {triggers:?}"))
            .get(0)
            .unwrap();
        assert_eq!(
            target, "pages",
            "`{ported}` must be re-anchored on `pages`, not `{target}`"
        );
    }
    // The seventh entity trigger was vestigial (created and dropped inside one
    // function, no DML between). Its DROP is retained so an old database is
    // cleaned up; nothing recreates it.
    assert!(
        !triggers
            .iter()
            .any(|name| name == "m4_community_parity_entity_update"),
        "the vestigial parity trigger must not come back: {triggers:?}"
    );

    let version: i64 = {
        let mut rows = conn.query("PRAGMA user_version", ()).await.unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert_eq!(version, i64::from(SCHEMA_VERSION));
}

/// The FK relaxation, exercised as a writer would. After migration 123 there is
/// no `entities` row anywhere, so every relation endpoint is by definition a
/// shadow-only id; the insert has to succeed with `foreign_keys` ON.
#[tokio::test]
async fn migration_123_relations_accept_shadow_only_endpoints_with_fk_on() {
    let (db, _dir) = test_db().await;
    let conn = db.conn.lock().await;

    let fk_state: i64 = {
        let mut rows = conn.query("PRAGMA foreign_keys", ()).await.unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert_eq!(
        fk_state, 1,
        "foreign_keys must be ON for this to be a real test of the relaxed FK"
    );

    conn.execute(
        "INSERT INTO relations
             (id, from_entity, to_entity, relation_type, source_agent, created_at)
         VALUES ('m123-shadow-rel', 'm123-shadow-a', 'm123-shadow-b', 'relates', 'test', 1)",
        (),
    )
    .await
    .expect("a relation between two shadow-only entity ids must insert with foreign_keys ON");
}

/// The resurrection oracle. `SCHEMA` is `execute_batch`'d on every open, before
/// `run_migrations` -- so a `CREATE TABLE IF NOT EXISTS entities` left in it
/// would hand the dropped table back on the next restart, silently and forever.
/// Open, close, reopen: the tables must still be gone, and the version must
/// still be 123 (proving the reopen replayed nothing).
#[tokio::test]
async fn migration_123_retirement_survives_a_reopen() {
    let dir = tempdir().unwrap();
    let embedder = shared_embedder();

    let first = MemoryDB::new_with_shared_embedder(
        dir.path(),
        Arc::new(crate::events::NoopEmitter),
        Arc::clone(&embedder),
    )
    .await
    .unwrap();
    {
        let conn = first.conn.lock().await;
        let tables = schema_names(&conn, "table").await;
        assert!(!tables.iter().any(|name| name == "entities"));
    }
    drop(first);

    let reopened = MemoryDB::new_with_shared_embedder(
        dir.path(),
        Arc::new(crate::events::NoopEmitter),
        embedder,
    )
    .await
    .expect("a retired database must reopen cleanly");

    let conn = reopened.conn.lock().await;
    let tables = schema_names(&conn, "table").await;
    for dropped in ["entities", "entity_aliases"] {
        assert!(
            !tables.iter().any(|name| name == dropped),
            "`{dropped}` must not be resurrected by a reopen; tables: {tables:?}"
        );
    }
    let version: i64 = {
        let mut rows = conn.query("PRAGMA user_version", ()).await.unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert_eq!(version, i64::from(SCHEMA_VERSION));
}

/// The timeline oracle: at `user_version = 0` the legacy substrate must be
/// stood up, not skipped.
///
/// `ensure_legacy_entities_table` runs unconditionally at the top of
/// `run_migrations`, BEFORE `if version < 1`. That ordering is the whole design:
/// a fresh install replays the entire chain from zero, and ten frozen bodies
/// plus migration 12's `CREATE INDEX ... ON entities(domain)` read the table
/// mid-chain. Re-gating the creation on the FINAL version -- "123 dropped it, so
/// don't make it" -- would invert the timeline and break the replay at its first
/// entity reference, so the version-0 branch gets its own test rather than
/// resting on the fresh-database tests that happen to exercise it.
///
/// It must be the version-0 shape, with `domain`, because migration 50 is what
/// renames that column to `space` and has not run yet. And `entity_aliases` must
/// be ABSENT: migration 41 creates it, so handing it over early would give a
/// version-0 database a shape its own position does not imply.
#[tokio::test]
async fn the_legacy_substrate_is_live_for_a_replay_from_version_zero() {
    let dir = tempdir().unwrap();
    let raw =
        libsql::Builder::new_local(dir.path().join("replay.db").to_string_lossy().to_string())
            .build()
            .await
            .unwrap();
    let conn = raw.connect().unwrap();

    let version: i64 = {
        let mut rows = conn.query("PRAGMA user_version", ()).await.unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    };
    assert_eq!(
        version, 0,
        "fixture precondition: a brand-new database is at 0"
    );

    ensure_legacy_entities_table(&conn)
        .await
        .expect("the version-0 branch must stand the legacy substrate up");

    let mut rows = conn
        .query(
            "SELECT name FROM sqlite_master WHERE type='table' \
               AND name IN ('entities', 'entity_aliases') ORDER BY name",
            (),
        )
        .await
        .unwrap();
    let mut tables = Vec::new();
    while let Some(row) = rows.next().await.unwrap() {
        tables.push(row.get::<String>(0).unwrap());
    }
    assert_eq!(
        tables,
        vec!["entities".to_string()],
        "a version-0 database gets `entities` and only `entities`; migration 41 owns the aliases"
    );

    // The version-0 shape, so migration 12's `entities(domain)` index compiles.
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_entities_domain ON entities(domain) WHERE domain IS NOT NULL",
        (),
    )
    .await
    .expect("migration 12 indexes `entities(domain)`, so the version-0 shape must carry it");
}

/// The downgrade barrier, with its own control. `SCHEMA_VERSION` is what stops
/// a build that predates migration 123 from writing to a retired store: every
/// migration is gated `if version < N`, so an older daemon would skip all of
/// them and write against a schema it cannot see. A `user_version` above this
/// build's must refuse the open.
///
/// The control is the second half: at exactly `SCHEMA_VERSION` the same call
/// succeeds. Without it, an unrelated failure would read as a passing barrier.
#[tokio::test]
async fn migration_123_downgrade_barrier_refuses_a_newer_database() {
    let (db, _dir) = test_db().await;

    {
        let conn = db.conn.lock().await;
        conn.execute(&format!("PRAGMA user_version = {}", SCHEMA_VERSION + 1), ())
            .await
            .unwrap();
    }
    let refusal = db
        .run_migrations(&crate::events::NoopEmitter)
        .await
        .expect_err("a database newer than this build must refuse to open");
    let refusal = refusal.to_string();
    assert!(
        refusal.contains("newer than this build supports"),
        "the barrier must say why it refused: {refusal}"
    );

    // Control: the same call at exactly this build's version proceeds, so the
    // refusal above is the barrier and not an unrelated failure.
    {
        let conn = db.conn.lock().await;
        conn.execute(&format!("PRAGMA user_version = {SCHEMA_VERSION}"), ())
            .await
            .unwrap();
    }
    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("a database at this build's own version must open");
}

/// The restore drill for the point of no return. Migration 123 is the one
/// migration whose damage cannot be undone by a later migration -- the tables
/// are gone -- so its `backup_before_migration` restore point is the entire
/// rollback plan, and a rollback plan that has never been opened is a wish.
///
/// The load-bearing assertion is structural, not the filename. A snapshot taken
/// AFTER the drop would still exist, still pass `integrity_check`, and still
/// open -- and would restore to a database with no `entities`, which is the
/// state being rolled back FROM. So the drill asserts both legacy tables are
/// PRESENT in the snapshot. That is the exact mirror of the migration-97 drill
/// (`db/edges_rebuild_test.rs`), which asserts the tables migration 98 CREATES
/// are absent; here the migration destroys rather than creates, so presence is
/// what proves the snapshot predates it.
#[tokio::test]
async fn the_pre_migration_123_backup_is_a_usable_restore_point() {
    let (db, dir) = test_db().await;
    let dest = dir.path().join("pre_migration_123_backup.db");
    assert!(
        dest.exists(),
        "migration 123 must leave a restore point at {}",
        dest.display()
    );

    let receipt = db
        .get_app_metadata("backup_before_migration_123")
        .await
        .unwrap()
        .expect("the backup receipt must be recorded, or the drill has nothing to verify");
    let receipt: serde_json::Value = serde_json::from_str(&receipt).unwrap();
    assert_eq!(
        receipt["integrity_ok"], true,
        "a restore point that failed integrity_check is not a rollback plan"
    );

    // Open the snapshot directly -- never through `MemoryDB`, which would
    // migrate the very file whose pre-123 state is the thing under test, and
    // drop the tables this drill exists to find.
    let snapshot = libsql::Builder::new_local(dest.to_string_lossy().to_string())
        .build()
        .await
        .unwrap();
    let conn = snapshot.connect().unwrap();

    let mut rows = conn.query("PRAGMA user_version", ()).await.unwrap();
    let stamped: i64 = rows.next().await.unwrap().unwrap().get(0).unwrap();
    assert!(
        stamped < 123,
        "the restore point must predate the retirement it protects against, got {stamped}"
    );

    for table in ["entities", "entity_aliases"] {
        let mut rows = conn
            .query(
                "SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name = ?1",
                libsql::params![table],
            )
            .await
            .unwrap();
        let present: i64 = rows.next().await.unwrap().unwrap().get(0).unwrap();
        assert_eq!(
            present, 1,
            "{table} is dropped BY migration 123, so a restore point missing it was taken \
             after the drop and rolls back to nothing"
        );
    }

    // The pre-migration schema is intact and queryable, so the file is a real
    // database rather than a valid-but-empty shell -- and `relations` still
    // carries its pre-rebuild shape.
    let mut rows = conn
        .query("SELECT COUNT(*) FROM entities", ())
        .await
        .unwrap();
    let _: i64 = rows.next().await.unwrap().unwrap().get(0).unwrap();
    let mut rows = conn
        .query("SELECT COUNT(*) FROM relations", ())
        .await
        .unwrap();
    let _: i64 = rows.next().await.unwrap().unwrap().get(0).unwrap();
}

/// The M4 trigger rebuild, proven at the only entity write that still exists.
/// Before migration 123 these triggers were anchored on `entities`, so the
/// legacy INSERT is what fired them and the paired shadow-page INSERT fired
/// nothing; the port re-anchors them on `pages` alone (`WHEN NEW.kind =
/// 'entity'`), so the canonical write now carries the firing. Each ported
/// trigger must fire exactly once.
///
/// The parity generation moves by TWO per shadow-page write, and that is the
/// pre-123 number, not a double-fire: `m4_parity_input_entity_*` bumps it
/// directly, and `m4_grouping_entity_*` writes `space_graph_state`, whose own
/// `m4_parity_input_state_*` trigger bumps it again. The same two-step cascade
/// ran off the legacy `entities` write. What matters to
/// `repair::parity_input_generation_on_connection` -- which subtracts the
/// measured generation delta from `total_changes()` -- is that every bump stays
/// one single-row update of the singleton, which these deltas pin.
#[tokio::test]
async fn migration_123_shadow_page_write_bumps_each_generation_exactly_once() {
    const SPACE: &str = "m123-firing-space";
    let (db, _dir) = test_db().await;
    let conn = db.conn.lock().await;

    async fn parity_generation(conn: &libsql::Connection) -> i64 {
        let mut rows = conn
            .query(
                "SELECT generation FROM community_parity_input_state WHERE singleton=1",
                (),
            )
            .await
            .unwrap();
        rows.next().await.unwrap().unwrap().get(0).unwrap()
    }
    async fn grouping_generation(conn: &libsql::Connection, space: &str) -> i64 {
        let mut rows = conn
            .query(
                "SELECT grouping_generation FROM space_graph_state WHERE space=?1",
                libsql::params![space],
            )
            .await
            .unwrap();
        rows.next()
            .await
            .unwrap()
            .map(|row| row.get::<i64>(0).unwrap())
            .unwrap_or(0)
    }

    let now = chrono::Utc::now().to_rfc3339();
    let parity_before = parity_generation(&conn).await;
    conn.execute(
        "INSERT INTO pages (
            id, title, content, kind, space, workspace, source_memory_ids,
            version, status, created_at, last_compiled, last_modified
         ) VALUES (
            'm123-firing-page', 'M123 Firing', '', 'entity', ?1, ?1, '[]',
            1, 'active', ?2, ?2, ?2
         )",
        libsql::params![SPACE, now.clone()],
    )
    .await
    .unwrap();
    assert_eq!(
        parity_generation(&conn).await - parity_before,
        2,
        "one shadow-page INSERT fires the parity trigger once directly and once \
         through the space_graph_state cascade -- no more, no less"
    );
    assert_eq!(
        grouping_generation(&conn, SPACE).await,
        1,
        "one shadow-page INSERT must bump the space grouping generation exactly once"
    );

    let parity_before = parity_generation(&conn).await;
    let grouping_before = grouping_generation(&conn, SPACE).await;
    conn.execute(
        "UPDATE pages SET embedding = vector32(?1) WHERE id = 'm123-firing-page'",
        libsql::params![MemoryDB::vec_to_sql(&vec![0.5f32; 768])],
    )
    .await
    .unwrap();
    assert_eq!(
        parity_generation(&conn).await - parity_before,
        2,
        "one shadow-page embedding UPDATE fires the parity trigger once directly \
         and once through the space_graph_state cascade"
    );
    assert_eq!(
        grouping_generation(&conn, SPACE).await - grouping_before,
        1,
        "one shadow-page embedding UPDATE must bump the space grouping generation exactly once"
    );

    // A non-entity page write must not touch either generation -- the ported
    // triggers are fenced on `kind`, not on `pages` as a whole.
    let parity_before = parity_generation(&conn).await;
    let grouping_before = grouping_generation(&conn, SPACE).await;
    conn.execute(
        "INSERT INTO pages (
            id, title, content, kind, space, workspace, source_memory_ids,
            version, status, created_at, last_compiled, last_modified
         ) VALUES (
            'm123-firing-concept', 'M123 Concept', '', 'concept', ?1, ?1, '[]',
            1, 'active', ?2, ?2, ?2
         )",
        libsql::params![SPACE, now],
    )
    .await
    .unwrap();
    assert_eq!(parity_generation(&conn).await, parity_before);
    assert_eq!(grouping_generation(&conn, SPACE).await, grouping_before);
}

/// Decision 1's end-to-end proof: with the legacy entity tables gone, the
/// community feature still runs the whole way through -- discovery over the
/// canonical entity substrate, storage of both the label-propagation
/// assignment and the durable M4 grouping, and the reader path the refinery
/// actually consumes on the other side.
///
/// The three legs mirror `refinery::Phase::CommunityDetection` in order:
/// `detect_communities` (the always-on label-prop producer, whose only
/// remaining store is `pages.community_id`), `run_next_community_grouping_cycle`
/// (the M4 durable lane), then `reconcile_pending_community_readers`. If the
/// retirement had left any of the three reading a table that no longer exists,
/// or writing one nothing reads, this fails rather than silently producing an
/// empty community set.
/// KG review 2026-08-16, migration 124: the repair for databases already past
/// the frozen-replay fixes. (a) An active edge stranded on an archived shadow
/// page (archived by a raw status flip, i.e. before `archive_entity` learned
/// to retract) is retired and stamped; (b) a job parked by either now-fixed
/// conflict is requeued; (c) an active cites edge whose memory moved is
/// downgraded to legacy under the pages-reading fence.
#[tokio::test]
async fn migration_124_retires_orphan_edges_requeues_parked_jobs_and_downgrades_moved_edges() {
    let (db, _dir) = test_db().await;
    let orphan_edge = seed_linked_entity_pair(&db, "m124", "work").await;
    let now = chrono::Utc::now().to_rfc3339();
    db.insert_page(
        "m124-page",
        "M124 page",
        None,
        "cites a memory",
        None,
        Some("work"),
        &["m124-src"],
        &now,
    )
    .await
    .unwrap();
    let cites_edge = crate::provenance::compute_edge_id(
        "cites",
        "page",
        "m124-page",
        "memory",
        "m124-src",
        "m124-src",
    );
    {
        let conn = db.conn.lock().await;
        // (a) the pre-fix archive shape: status flipped, edges untouched.
        conn.execute(
            "UPDATE pages SET status = 'archived' \
             WHERE id = (SELECT page_id FROM entity_page_map WHERE entity_id = 'm124-a')",
            (),
        )
        .await
        .unwrap();
        // (b) a job parked by the version-only conflict.
        conn.execute(
            "INSERT INTO claim_derivation_jobs \
                 (job_id, page_id, page_version, status, attempts, last_error, \
                  created_at, updated_at) \
             VALUES ('m124-page:1', 'm124-page', 1, 'parked', 5, \
                     'Conflict: support_verdict_supersedes_existing: cr already has a support \
                      edge for this span naming a different verdict', 1, 1) \
             ON CONFLICT(job_id) DO UPDATE SET status = 'parked', attempts = 5, \
                 last_error = excluded.last_error",
            (),
        )
        .await
        .unwrap();
        // (c) `insert_page` dual-wrote the same-space cites edge; now the
        // memory moves (the live move path leaves cites edges active).
        conn.execute(
            "UPDATE memories SET space = 'elsewhere' WHERE source_id = 'm124-src'",
            (),
        )
        .await
        .unwrap();
        // Rewind to the pre-repair boundary.
        conn.execute("PRAGMA user_version = 123", ()).await.unwrap();
    }

    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("migration 124 must apply");
    assert_eq!(user_version(&db).await, i64::from(SCHEMA_VERSION));

    let (valid_until, _, tag, _) = relates_edge_state(&db, &orphan_edge).await;
    assert!(valid_until.is_some(), "the orphan edge is retired");
    assert_eq!(
        tag.as_deref(),
        Some("m124-a"),
        "an edge orphaned by an ARCHIVED shadow is stamped for restore"
    );
    let (lineage, cites_valid_until, _) = edge_state(&db, &cites_edge).await;
    assert_eq!(
        lineage, "legacy",
        "the moved-endpoint cites edge is downgraded"
    );
    assert!(cites_valid_until.is_none());
    {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT status, attempts, last_error FROM claim_derivation_jobs \
                 WHERE job_id = 'm124-page:1'",
                (),
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().unwrap();
        assert_eq!(row.get::<String>(0).unwrap(), "pending");
        assert_eq!(row.get::<i64>(1).unwrap(), 0);
        assert!(row.get::<Option<String>>(2).unwrap().is_none());
    }

    // The restore lane picks the stamped edge back up.
    assert!(db.restore_entity("m124-a").await.unwrap());
    let (valid_until, _, tag, _) = relates_edge_state(&db, &orphan_edge).await;
    assert!(valid_until.is_none());
    assert!(tag.is_none());
}

/// Migration 125 (KG observation identity, PR 1): an observation's identity
/// is `(entity_id, lower(trim(content)))`. `test_db()` already carries
/// `idx_observations_identity` (migration 125 is its sole creator -- the
/// fresh-schema `SCHEMA` block runs before `run_migrations` on every open,
/// so putting the index there would fail the first open of a DB that still
/// holds duplicates; a fresh install gets the index by replaying the
/// migration chain from version 0), so duplicates are seeded by dropping the
/// index, inserting raw rows, rewinding `user_version` to 124, and replaying
/// migration 125 for real -- proving both halves (dedup DELETE, `CREATE
/// UNIQUE INDEX`) through the actual migration path rather than asserting on
/// hand-run SQL.
#[tokio::test]
async fn migration_125_dedups_observations_and_adds_identity_index() {
    let (db, _dir) = test_db().await;
    db.test_seed_entity_shadow_page(TestEntity::new("m125-e", "M125 Entity", "concept"))
        .await
        .unwrap();
    {
        let conn = db.conn.lock().await;
        conn.execute("DROP INDEX IF EXISTS idx_observations_identity", ())
            .await
            .unwrap();
        // Oldest survivor by created_at, a case/whitespace-variant
        // duplicate, and an unrelated observation that must survive intact.
        conn.execute(
            "INSERT INTO observations (id, entity_id, content, created_at) \
             VALUES ('m125-old', 'm125-e', 'Foo bar', 100)",
            (),
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO observations (id, entity_id, content, created_at) \
             VALUES ('m125-dup', 'm125-e', 'foo bar  ', 200)",
            (),
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO observations (id, entity_id, content, created_at) \
             VALUES ('m125-other', 'm125-e', 'Other', 150)",
            (),
        )
        .await
        .unwrap();
        // A group of 3+ duplicates (prod has 16 such groups): oldest by
        // `created_at` must survive out of every member, not just a pair.
        conn.execute(
            "INSERT INTO observations (id, entity_id, content, created_at) \
             VALUES ('m125-triple-a', 'm125-e', 'Triple', 50), \
                    ('m125-triple-b', 'm125-e', 'triple', 60), \
                    ('m125-triple-c', 'm125-e', ' TRIPLE ', 70)",
            (),
        )
        .await
        .unwrap();
        // A `created_at` tie (prod has 18 such groups): the delete's
        // secondary sort is smallest `rowid`, so the first-inserted row
        // (lower rowid) must survive.
        conn.execute(
            "INSERT INTO observations (id, entity_id, content, created_at) \
             VALUES ('m125-tie-a', 'm125-e', 'Tie', 300), \
                    ('m125-tie-b', 'm125-e', 'TIE', 300)",
            (),
        )
        .await
        .unwrap();
        conn.execute("PRAGMA user_version = 124", ()).await.unwrap();
    }

    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("migration 125 must apply");
    assert_eq!(user_version(&db).await, i64::from(SCHEMA_VERSION));

    {
        let conn = db.conn.lock().await;
        let remaining: i64 = conn
            .query(
                "SELECT COUNT(*) FROM observations WHERE entity_id = 'm125-e'",
                (),
            )
            .await
            .unwrap()
            .next()
            .await
            .unwrap()
            .unwrap()
            .get::<i64>(0)
            .unwrap();
        assert_eq!(
            remaining, 4,
            "the case/whitespace duplicate, the group-of-3, and the created_at \
             tie all collapse to one survivor each (2 unrelated + 1 + 1)"
        );

        let survivor: String = conn
            .query(
                "SELECT id FROM observations \
                 WHERE entity_id = 'm125-e' AND lower(trim(content)) = 'foo bar'",
                (),
            )
            .await
            .unwrap()
            .next()
            .await
            .unwrap()
            .unwrap()
            .get::<String>(0)
            .unwrap();
        assert_eq!(survivor, "m125-old", "the oldest row per identity survives");

        let triple_survivor: String = conn
            .query(
                "SELECT id FROM observations \
                 WHERE entity_id = 'm125-e' AND lower(trim(content)) = 'triple'",
                (),
            )
            .await
            .unwrap()
            .next()
            .await
            .unwrap()
            .unwrap()
            .get::<String>(0)
            .unwrap();
        assert_eq!(
            triple_survivor, "m125-triple-a",
            "the oldest of a 3-way duplicate group survives"
        );

        let tie_survivor: String = conn
            .query(
                "SELECT id FROM observations \
                 WHERE entity_id = 'm125-e' AND lower(trim(content)) = 'tie'",
                (),
            )
            .await
            .unwrap()
            .next()
            .await
            .unwrap()
            .unwrap()
            .get::<String>(0)
            .unwrap();
        assert_eq!(
            tie_survivor, "m125-tie-a",
            "a created_at tie breaks on smallest rowid (first inserted)"
        );

        let idx_count: i64 = conn
            .query(
                "SELECT COUNT(*) FROM sqlite_master \
                 WHERE type = 'index' AND name = 'idx_observations_identity'",
                (),
            )
            .await
            .unwrap()
            .next()
            .await
            .unwrap()
            .unwrap()
            .get::<i64>(0)
            .unwrap();
        assert_eq!(idx_count, 1, "the identity index exists");

        let changed = conn
            .execute(
                "INSERT OR IGNORE INTO observations (id, entity_id, content, created_at) \
                 VALUES ('m125-probe', 'm125-e', 'FOO BAR', 999)",
                (),
            )
            .await
            .unwrap();
        assert_eq!(
            changed, 0,
            "the index blocks a case/whitespace-variant duplicate insert"
        );

        // Idempotency: rewind and replay finds nothing left to dedupe, and
        // `CREATE UNIQUE INDEX IF NOT EXISTS` is a no-op.
        conn.execute("PRAGMA user_version = 124", ()).await.unwrap();
    }
    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("re-running migration 125 must be a no-op");
    assert_eq!(user_version(&db).await, i64::from(SCHEMA_VERSION));
    let conn = db.conn.lock().await;
    let remaining: i64 = conn
        .query(
            "SELECT COUNT(*) FROM observations WHERE entity_id = 'm125-e'",
            (),
        )
        .await
        .unwrap()
        .next()
        .await
        .unwrap()
        .unwrap()
        .get::<i64>(0)
        .unwrap();
    assert_eq!(remaining, 4, "re-run finds no further duplicates");
}

/// BLOCKER 1 (review, PR 1 fix round): `SCHEMA` is `execute_batch`'d on
/// every open, unconditionally and *before* `run_migrations` (see the
/// `entities`-split comment near `SCHEMA`'s definition). An earlier draft of
/// this migration put `CREATE UNIQUE INDEX idx_observations_identity`
/// straight into `SCHEMA`, which would abort every future open of the real
/// prod database (163 pre-125 duplicate rows) with a `UNIQUE constraint
/// failed` before migration 125 ever ran. This test proves the fix through
/// the real, on-disk open path (`MemoryDB::new_with_shared_embedder`, not
/// `test_db()`, which never re-opens): seed duplicates with no index
/// present, drop the handle, and reopen on the same path. The open must
/// succeed, and migration 125 -- not `SCHEMA` -- must be what dedupes and
/// creates the index.
#[tokio::test]
async fn reopening_a_db_with_pre_125_duplicate_observations_migrates_cleanly() {
    let dir = tempdir().unwrap();
    let embedder = shared_embedder();
    let db = MemoryDB::new_with_shared_embedder(
        dir.path(),
        Arc::new(crate::events::NoopEmitter),
        Arc::clone(&embedder),
    )
    .await
    .expect("fresh open must succeed");
    db.test_seed_entity_shadow_page(TestEntity::new("m125-reopen-e", "Reopen Entity", "concept"))
        .await
        .unwrap();
    {
        let conn = db.conn.lock().await;
        // Simulate a database that predates migration 125: no identity
        // index, and two writers' worth of raw duplicate rows already on
        // disk, exactly like prod's 163 duplicates.
        conn.execute("DROP INDEX IF EXISTS idx_observations_identity", ())
            .await
            .unwrap();
        conn.execute(
            "INSERT INTO observations (id, entity_id, content, created_at) \
             VALUES ('m125-reopen-old', 'm125-reopen-e', 'Same fact', 100)",
            (),
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO observations (id, entity_id, content, created_at) \
             VALUES ('m125-reopen-dup', 'm125-reopen-e', 'same fact', 200)",
            (),
        )
        .await
        .unwrap();
        conn.execute("PRAGMA user_version = 124", ()).await.unwrap();
    }
    drop(db);

    let reopened = MemoryDB::new_with_shared_embedder(
        dir.path(),
        Arc::new(crate::events::NoopEmitter),
        embedder,
    )
    .await
    .expect(
        "reopen must succeed: SCHEMA must not contain a UNIQUE index that \
         could fail against pre-125 duplicates before migration 125 runs",
    );

    let conn = reopened.conn.lock().await;
    let mut version_rows = conn.query("PRAGMA user_version", ()).await.unwrap();
    assert_eq!(
        version_rows
            .next()
            .await
            .unwrap()
            .unwrap()
            .get::<i64>(0)
            .unwrap(),
        i64::from(SCHEMA_VERSION),
        "reopen must replay migration 125 (and everything after it)"
    );
    drop(version_rows);

    let remaining: i64 = conn
        .query(
            "SELECT COUNT(*) FROM observations WHERE entity_id = 'm125-reopen-e'",
            (),
        )
        .await
        .unwrap()
        .next()
        .await
        .unwrap()
        .unwrap()
        .get::<i64>(0)
        .unwrap();
    assert_eq!(
        remaining, 1,
        "migration 125 must dedupe the pre-existing duplicate on reopen"
    );

    let idx_count: i64 = conn
        .query(
            "SELECT COUNT(*) FROM sqlite_master \
             WHERE type = 'index' AND name = 'idx_observations_identity'",
            (),
        )
        .await
        .unwrap()
        .next()
        .await
        .unwrap()
        .unwrap()
        .get::<i64>(0)
        .unwrap();
    assert_eq!(
        idx_count, 1,
        "migration 125 must create the identity index on reopen"
    );
}

/// `post_write::add_observation`'s duplicate-detection wrapper
/// (`add_observation_dedup`): a second identical observation returns the
/// same id instead of minting a new row, and carries a warning the caller
/// can surface.
#[tokio::test]
async fn add_observation_twice_returns_existing_id_and_warns() {
    let (db, _dir) = test_db().await;
    let entity_id = db
        .create_entity("M125 Dedup Entity", "concept", None)
        .await
        .unwrap();
    let make_req = || wenlan_types::requests::AddObservationRequest {
        entity_id: entity_id.clone(),
        content: "Same text".to_string(),
        source_agent: None,
        confidence: None,
    };

    let first =
        crate::post_write::add_observation(&db, make_req(), "test-agent", &ReadScope::Global)
            .await
            .unwrap();
    assert!(first.warnings.is_empty());

    let (watermark_before, activity_count_before): (i64, i64) = {
        let conn = db.conn.lock().await;
        let watermark: i64 = conn
            .query(
                "SELECT entity_updated_at FROM pages WHERE kind = 'entity'
                   AND id = (SELECT page_id FROM entity_page_map WHERE entity_id = ?1)",
                libsql::params![entity_id.as_str()],
            )
            .await
            .unwrap()
            .next()
            .await
            .unwrap()
            .unwrap()
            .get(0)
            .unwrap();
        let activity_count: i64 = conn
            .query(
                "SELECT COUNT(*) FROM agent_activity WHERE action = 'observation_add'",
                (),
            )
            .await
            .unwrap()
            .next()
            .await
            .unwrap()
            .unwrap()
            .get(0)
            .unwrap();
        (watermark, activity_count)
    };

    let second =
        crate::post_write::add_observation(&db, make_req(), "test-agent", &ReadScope::Global)
            .await
            .unwrap();
    assert_eq!(second.id, first.id, "the second call returns the same id");
    assert!(
        second
            .warnings
            .iter()
            .any(|w| w.contains("duplicate observation")),
        "the second call must carry a duplicate warning, got {:?}",
        second.warnings
    );
    assert!(
        !second.wrote,
        "a duplicate observation must report wrote:false"
    );
    assert_eq!(second.outcome, crate::post_write::WriteOutcome::Unchanged);

    let conn = db.conn.lock().await;
    let count: i64 = conn
        .query(
            "SELECT COUNT(*) FROM observations WHERE entity_id = ?1",
            libsql::params![entity_id.as_str()],
        )
        .await
        .unwrap()
        .next()
        .await
        .unwrap()
        .unwrap()
        .get::<i64>(0)
        .unwrap();
    assert_eq!(count, 1, "only one row was created");

    let watermark_after: i64 = conn
        .query(
            "SELECT entity_updated_at FROM pages WHERE kind = 'entity'
               AND id = (SELECT page_id FROM entity_page_map WHERE entity_id = ?1)",
            libsql::params![entity_id.as_str()],
        )
        .await
        .unwrap()
        .next()
        .await
        .unwrap()
        .unwrap()
        .get(0)
        .unwrap();
    assert_eq!(
        watermark_after, watermark_before,
        "a duplicate observation must not touch the entity's freshness watermark"
    );
    let activity_count_after: i64 = conn
        .query(
            "SELECT COUNT(*) FROM agent_activity WHERE action = 'observation_add'",
            (),
        )
        .await
        .unwrap()
        .next()
        .await
        .unwrap()
        .unwrap()
        .get(0)
        .unwrap();
    assert_eq!(
        activity_count_after, activity_count_before,
        "a duplicate observation must not record a new activity event"
    );
}

/// `commit_entity_enrichment_at_version`'s `INSERT OR IGNORE` (migration
/// 125): reprocessing the same source memory must not accumulate duplicates
/// (already true via the per-source DELETE), and a second, different source
/// memory extracting the identical sentence for the same entity must not
/// create a second row either -- the identity index is what stops that case,
/// and the first source keeps provenance.
#[tokio::test]
async fn enrichment_commit_reprocess_keeps_one_observation_per_identity() {
    let (db, _dir) = test_db().await;
    db.upsert_documents(vec![make_memory_doc(
        "mem_m125_source_a",
        "Rust is a systems language.",
        "fact",
        "work",
        "agent",
    )])
    .await
    .unwrap();
    db.upsert_documents(vec![make_memory_doc(
        "mem_m125_source_b",
        "Rust is a systems language, restated.",
        "fact",
        "work",
        "agent",
    )])
    .await
    .unwrap();

    let extracted = extracted_graph("Rust", "Systems", "Rust is a systems language");

    assert!(db
        .commit_entity_enrichment_at_version(
            "mem_m125_source_a",
            1,
            &extracted,
            "Rust is a systems language.",
        )
        .await
        .unwrap());
    // Reprocessing the same source clears its own prior row first, so this
    // must not duplicate even without the identity index.
    assert!(db
        .commit_entity_enrichment_at_version(
            "mem_m125_source_a",
            1,
            &extracted,
            "Rust is a systems language.",
        )
        .await
        .unwrap());

    {
        let conn = db.conn.lock().await;
        let count: i64 = conn
            .query(
                "SELECT COUNT(*) FROM observations WHERE content = 'Rust is a systems language'",
                (),
            )
            .await
            .unwrap()
            .next()
            .await
            .unwrap()
            .unwrap()
            .get::<i64>(0)
            .unwrap();
        assert_eq!(
            count, 1,
            "reprocessing the same source must not duplicate the observation"
        );
    }

    // A second, different source memory extracts the identical sentence for
    // the same entity.
    assert!(db
        .commit_entity_enrichment_at_version(
            "mem_m125_source_b",
            1,
            &extracted,
            "Rust is a systems language, restated.",
        )
        .await
        .unwrap());

    let conn = db.conn.lock().await;
    let count: i64 = conn
        .query(
            "SELECT COUNT(*) FROM observations WHERE content = 'Rust is a systems language'",
            (),
        )
        .await
        .unwrap()
        .next()
        .await
        .unwrap()
        .unwrap()
        .get::<i64>(0)
        .unwrap();
    assert_eq!(
        count, 1,
        "a second source committing the identical sentence must not create a duplicate row"
    );

    let source_memory_id: Option<String> = conn
        .query(
            "SELECT source_memory_id FROM observations \
             WHERE content = 'Rust is a systems language'",
            (),
        )
        .await
        .unwrap()
        .next()
        .await
        .unwrap()
        .unwrap()
        .get(0)
        .unwrap();
    assert_eq!(
        source_memory_id.as_deref(),
        Some("mem_m125_source_a"),
        "the first source keeps provenance"
    );
}

#[tokio::test]
async fn community_pipeline_survives_entity_retirement_end_to_end() {
    const SPACE: &str = "g6s3-community-space";
    const ROOT: &str = "g6s3-community-root";
    // Disjoint pairs, so a working label propagation must find exactly one
    // community per pair -- a collapsed-to-one or one-per-entity result would
    // both be wrong and both are reachable if adjacency or discovery lost its
    // source. Five of them, because the M4 lane holds any space with fewer than
    // `MIN_COMMUNITY_PARTICIPANTS` (10) nodes instead of publishing.
    const PAIRS: [[&str; 2]; 5] = [
        ["g6s3-ent-a1", "g6s3-ent-a2"],
        ["g6s3-ent-b1", "g6s3-ent-b2"],
        ["g6s3-ent-c1", "g6s3-ent-c2"],
        ["g6s3-ent-d1", "g6s3-ent-d2"],
        ["g6s3-ent-e1", "g6s3-ent-e2"],
    ];

    let (db, _dir) = test_db().await;

    // The premise: this runs on a post-123 database, with no legacy table to
    // fall back onto.
    {
        let conn = db.conn.lock().await;
        assert!(
            schema_names(&conn, "table")
                .await
                .iter()
                .all(|name| name != "entities" && name != "entity_aliases"),
            "fixture precondition: the legacy entity tables must already be retired"
        );
    }

    {
        let conn = db.conn.lock().await;
        conn.execute(
            "INSERT INTO spaces (id, name, created_at, updated_at) VALUES (?1, ?1, 1, 1)",
            libsql::params![SPACE],
        )
        .await
        .unwrap();
        conn.execute(
            "INSERT INTO provenance_roots
                (root_id, identity_version, identity_digest, root_kind,
                 independence_group_id, status, created_at)
             VALUES (?1, 1, 'g6s3-community-digest', 'generated',
                     'g6s3-community-group', 'active', 1)",
            libsql::params![ROOT],
        )
        .await
        .unwrap();
    }

    let embedding = MemoryDB::vec_to_sql(&vec![0.25f32; EMBEDDING_DIM]);
    for pair in PAIRS {
        for entity_id in pair {
            db.test_seed_entity_shadow_page(
                TestEntity::new(entity_id, entity_id, "concept")
                    .space(SPACE)
                    .timestamps(1, 1),
            )
            .await
            .unwrap();
            let conn = db.conn.lock().await;
            // One memory per entity, carrying the graph link the summary
            // reader joins on.
            conn.execute(
                "INSERT INTO memories
                    (id, content, source, source_id, title, chunk_index, last_modified,
                     chunk_type, space, entity_id, embedding)
                 VALUES (?1, 'Community member content', 'memory', ?1, ?1, 0, 1,
                         'text', ?2, ?3, vector32(?4))",
                libsql::params![
                    format!("g6s3-mem-{entity_id}"),
                    SPACE,
                    entity_id,
                    embedding.clone()
                ],
            )
            .await
            .unwrap();
        }
        let conn = db.conn.lock().await;
        conn.execute(
            "INSERT INTO edges
                (edge_id, src_id, src_kind, dst_id, dst_kind, edge_type, lineage,
                 grounded, root_id, space, created_at)
             VALUES (?1, ?2, 'entity', ?3, 'entity', 'relates', 'assertion',
                     1, ?4, ?5, 1)",
            libsql::params![
                format!("g6s3-edge-{}", pair[0]),
                pair[0],
                pair[1],
                ROOT,
                SPACE
            ],
        )
        .await
        .unwrap();
    }

    // Leg 1 -- discovery + storage on the label-propagation producer. Its
    // entity discovery and its adjacency scan both read the shadow page now,
    // and `pages.community_id` is the only place its answer lands.
    let detected = db
        .detect_communities()
        .await
        .expect("label propagation runs");
    assert_eq!(
        detected,
        PAIRS.len(),
        "each disjoint grounded pair must resolve to its own community"
    );
    {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT COUNT(*), COUNT(DISTINCT p.community_id)
                   FROM entity_page_map epm
                   JOIN pages p ON p.id = epm.page_id AND p.kind = 'entity'
                  WHERE p.community_id IS NOT NULL",
                (),
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().unwrap();
        assert_eq!(
            row.get::<i64>(0).unwrap(),
            2 * PAIRS.len() as i64,
            "every entity must carry a stored assignment on its shadow page"
        );
        assert_eq!(row.get::<i64>(1).unwrap(), PAIRS.len() as i64);
    }

    // Leg 2 -- the reader the refinery consumes. `load_summary_buckets` is the
    // sole consumer of that assignment; on a database with no parity receipts
    // its gate keeps it on the legacy branch, which is exactly the branch the
    // retirement re-pointed at the shadow page.
    let buckets = db
        .load_summary_buckets()
        .await
        .expect("summary bucket reader runs");
    assert_eq!(
        buckets.len(),
        PAIRS.len(),
        "the reader must see every stored community"
    );
    let mut bucket_sizes: Vec<usize> = buckets
        .iter()
        .map(|(_, members)| members.len())
        .collect::<Vec<_>>();
    bucket_sizes.sort_unstable();
    assert_eq!(
        bucket_sizes,
        vec![2; PAIRS.len()],
        "each community must carry both of its members' memories"
    );

    // Leg 3 -- the durable M4 lane, then the reader reconcile the refinery
    // calls immediately after it.
    let outcome = db
        .run_next_community_grouping_cycle()
        .await
        .expect("M4 grouping cycle runs")
        .expect("a dirty grounded space must publish");
    let member_count = match outcome {
        crate::community_grouping::CommunityGroupingOutcome::Published(receipt) => {
            receipt.member_count
        }
        other => panic!("expected a publication, got {other:?}"),
    };
    assert_eq!(
        member_count,
        2 * PAIRS.len(),
        "every entity must be grouped"
    );
    {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT
                    (SELECT COUNT(*) FROM community_members cm
                       JOIN space_graph_state s ON s.space = cm.space
                      WHERE cm.space = ?1
                        AND cm.published_generation = s.published_generation),
                    (SELECT COUNT(*) FROM communities WHERE space = ?1 AND retired_at IS NULL)",
                libsql::params![SPACE],
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().unwrap();
        assert_eq!(
            row.get::<i64>(0).unwrap(),
            2 * PAIRS.len() as i64,
            "membership must be stored at the generation the reader gate checks"
        );
        assert!(row.get::<i64>(1).unwrap() >= 1);
    }
    db.reconcile_pending_community_readers()
        .await
        .expect("the reader reconcile the refinery runs next must not fault");
}

/// The fresh-install shape for migration 55 Pass B.
///
/// Server startup calls `run_migration_55` unconditionally, before it binds
/// HTTP. Pass B's idempotency receipt is written by Pass B and by nothing else,
/// so a brand-new install reaches it with no receipt and runs the body for
/// real — including the self-heal, which before Stage 3 read `entities`. A
/// fresh install replays the chain to 123, which drops that table, so the
/// legacy predicate would have failed `no such table: entities` and aborted
/// startup for every new user. The existing tests all ran against stores that
/// carry the receipt, which is exactly why none of them saw it.
#[tokio::test]
async fn migration_55_pass_b_runs_on_a_fresh_install_at_the_retirement_version() {
    let tmp = tempfile::tempdir().unwrap();
    let db = MemoryDB::new(
        &tmp.path().join("fresh"),
        Arc::new(crate::events::NoopEmitter),
    )
    .await
    .expect("a fresh install must open");

    {
        let conn = db.conn.lock().await;
        let mut rows = conn.query("PRAGMA user_version", ()).await.unwrap();
        let version: i64 = rows.next().await.unwrap().unwrap().get(0).unwrap();
        assert_eq!(
            version,
            i64::from(SCHEMA_VERSION),
            "fixture precondition: a fresh install replays the whole chain"
        );
        assert!(
            !legacy_table_present(&conn, "entities").await.unwrap(),
            "fixture precondition: migration 123 has dropped `entities`"
        );
    }
    assert!(
        db.get_app_metadata("backfill_memory_entities_v1")
            .await
            .unwrap()
            .is_none(),
        "fixture precondition: a fresh install carries no Pass B receipt, so the body runs"
    );

    db.run_migration_55()
        .await
        .expect("startup runs migration 55 before binding HTTP; a fresh install must survive it");
}

/// Pass B's self-heal decides what an orphan IS, and post-Stage-3 that has to
/// mean the same thing it means everywhere else: no `kind='entity'` shadow page
/// reachable through `entity_page_map` — `entity_exists`'s own predicate.
///
/// Both halves matter. Nulling everything would be a passing "self-heal" that
/// silently destroys every real link; nulling nothing would leave orphans to be
/// backfilled as links to entities that do not exist.
#[tokio::test]
async fn migration_55_pass_b_self_heals_against_canonical_entity_membership() {
    let (db, _dir) = test_db().await;

    db.test_seed_entity_shadow_page(TestEntity::new("ent_live", "Live Entity", "concept"))
        .await
        .unwrap();

    {
        let conn = db.conn.lock().await;
        for (id, source_id, entity_id) in [
            ("c_live", "mem_m55b_live", "ent_live"),
            ("c_orphan", "mem_m55b_orphan", "ent_never_existed"),
        ] {
            conn.execute(
                "INSERT INTO memories (id, content, source, source_id, title, chunk_index, \
                 last_modified, chunk_type, entity_id) \
                 VALUES (?1, 'body', 'memory', ?2, 't', 0, 0, 'text', ?3)",
                libsql::params![id, source_id, entity_id],
            )
            .await
            .unwrap();
        }
    }

    db.run_migration_55_pass_b()
        .await
        .expect("pass B must complete");

    {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT source_id, entity_id FROM memories \
                 WHERE source_id LIKE 'mem_m55b_%' ORDER BY source_id",
                (),
            )
            .await
            .unwrap();
        let mut seen = Vec::new();
        while let Some(row) = rows.next().await.unwrap() {
            seen.push((
                row.get::<String>(0).unwrap(),
                row.get::<Option<String>>(1).unwrap(),
            ));
        }
        assert_eq!(
            seen,
            vec![
                ("mem_m55b_live".to_string(), Some("ent_live".to_string())),
                ("mem_m55b_orphan".to_string(), None),
            ],
            "an id with a live shadow page keeps its link; one without is nulled"
        );

        let mut rows = conn
            .query(
                "SELECT entity_id FROM memory_entities WHERE memory_id LIKE 'mem_m55b_%'",
                (),
            )
            .await
            .unwrap();
        let mut links = Vec::new();
        while let Some(row) = rows.next().await.unwrap() {
            links.push(row.get::<String>(0).unwrap());
        }
        assert_eq!(
            links,
            vec!["ent_live".to_string()],
            "only the canonical entity earns a backfilled link"
        );
    }
}

/// The downgrade barrier has to fire before the constructor writes, not merely
/// before it migrates.
///
/// `run_migrations` is the LAST thing `MemoryDB::new` calls. By the time the
/// old check ran, the constructor had already set `journal_mode=WAL`, swept
/// legacy `chunks` artifacts, and executed `SCHEMA` plus the FTS and trigger
/// DDL against a store built by a build it does not understand. So the
/// assertion here is not just "it refused" — it is that `sqlite_master` is
/// byte-identical afterwards. A barrier that refuses after writing is a
/// post-mortem.
#[tokio::test]
async fn the_downgrade_barrier_refuses_before_the_constructor_writes_anything() {
    let dir = tempdir().unwrap();
    let root = dir.path().join("newer");
    std::fs::create_dir_all(&root).unwrap();
    let db_file = root.join("origin_memory.db");

    let schema_snapshot = |file: std::path::PathBuf| async move {
        let raw = libsql::Builder::new_local(file.to_string_lossy().to_string())
            .build()
            .await
            .unwrap();
        let conn = raw.connect().unwrap();
        let mut rows = conn
            .query(
                "SELECT type || '|' || name FROM sqlite_master ORDER BY type, name",
                (),
            )
            .await
            .unwrap();
        let mut objects = Vec::new();
        while let Some(row) = rows.next().await.unwrap() {
            objects.push(row.get::<String>(0).unwrap());
        }
        objects
    };

    {
        let raw = libsql::Builder::new_local(db_file.to_string_lossy().to_string())
            .build()
            .await
            .unwrap();
        let conn = raw.connect().unwrap();
        conn.execute(&format!("PRAGMA user_version = {}", SCHEMA_VERSION + 1), ())
            .await
            .unwrap();
    }
    let before = schema_snapshot(db_file.clone()).await;

    let refusal = match MemoryDB::new(&root, Arc::new(crate::events::NoopEmitter)).await {
        Err(e) => e.to_string(),
        Ok(_) => panic!("a database newer than this build must refuse at the constructor"),
    };
    assert!(
        refusal.contains("newer than this build supports"),
        "the barrier must say why it refused: {refusal}"
    );

    let after = schema_snapshot(db_file.clone()).await;
    assert_eq!(
        after, before,
        "the refused open must leave the schema untouched — no SCHEMA, no FTS, no triggers"
    );

    // Control: the same file at the same path, with only `user_version` changed
    // back to 0, opens and migrates. So the refusal above is the barrier and not
    // an unrelated constructor failure on this fixture.
    {
        let raw = libsql::Builder::new_local(db_file.to_string_lossy().to_string())
            .build()
            .await
            .unwrap();
        let conn = raw.connect().unwrap();
        conn.execute("PRAGMA user_version = 0", ()).await.unwrap();
    }
    let opened = MemoryDB::new(&root, Arc::new(crate::events::NoopEmitter))
        .await
        .expect("the same fixture below the barrier must open");
    {
        let conn = opened.conn.lock().await;
        let mut rows = conn.query("PRAGMA user_version", ()).await.unwrap();
        assert_eq!(
            rows.next().await.unwrap().unwrap().get::<i64>(0).unwrap(),
            i64::from(SCHEMA_VERSION),
            "the control must actually migrate, or it proves nothing about the refusal"
        );
    }
}

/// The residue an older build leaves behind, and the residue that is not
/// residue at all.
///
/// A pre-123 build opening a retired store runs its own `SCHEMA` — which still
/// carries `CREATE TABLE IF NOT EXISTS entities` — before its barrier refuses,
/// so it leaves an empty shell and quits. Nothing removed it: the
/// reconstruction path early-returns at 123 and above. Rows flip the answer,
/// because boot is no place to decide which copy of entity data is right.
#[tokio::test]
async fn an_empty_legacy_entity_shell_is_swept_from_a_retired_store() {
    let (db, _dir) = test_db().await;
    db.test_create_legacy_entity_tables().await.unwrap();
    {
        let conn = db.conn.lock().await;
        for name in ["entities", "entity_aliases"] {
            assert!(
                legacy_table_present(&conn, name).await.unwrap(),
                "fixture precondition: the older build's shell is present ({name})"
            );
        }
    }

    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("a retired store carrying an empty shell must still boot");

    {
        let conn = db.conn.lock().await;
        for name in ["entities", "entity_aliases"] {
            assert!(
                !legacy_table_present(&conn, name).await.unwrap(),
                "an empty `{name}` shell on a retired store is schema residue and must be swept"
            );
        }
    }
}

#[tokio::test]
async fn a_populated_legacy_entity_shell_survives_a_retired_boot() {
    let (db, _dir) = test_db().await;
    db.test_create_legacy_entity_tables().await.unwrap();
    {
        let conn = db.conn.lock().await;
        conn.execute(
            "INSERT INTO entities (id, name, entity_type, created_at, updated_at) \
             VALUES ('ent_unknown_provenance', 'Unknown', 'concept', 1, 1)",
            (),
        )
        .await
        .unwrap();
    }

    db.run_migrations(&crate::events::NoopEmitter)
        .await
        .expect("a retired store carrying unexplained legacy rows must still boot");

    {
        let conn = db.conn.lock().await;
        assert!(
            legacy_table_present(&conn, "entities").await.unwrap(),
            "rows of unknown provenance are never destroyed at boot"
        );
        let mut rows = conn
            .query("SELECT COUNT(*) FROM entities", ())
            .await
            .unwrap();
        assert_eq!(
            rows.next().await.unwrap().unwrap().get::<i64>(0).unwrap(),
            1,
            "the row must survive untouched"
        );
        assert!(
            legacy_table_present(&conn, "entity_aliases").await.unwrap(),
            "the pair is handled together: `entity_aliases` references `entities(id)`"
        );
    }
}

/// Reconstruction refuses where it cannot be right — and the discriminator is
/// the SHAPE, not the stamped version.
///
/// `LEGACY_ENTITIES_SCHEMA_V122` spells `space`, which migration 50 is what
/// renames `domain` into. Hand it to a store that is still `domain`-shaped and
/// migration 50 later tries to rename a column that is already there. But the
/// version number cannot tell you which store you have: a fixture that rewound
/// `user_version` on a fully migrated database stamps 44 while being
/// version-122-shaped, and refusing that one would break every rewind fixture
/// in this suite (`test_migration_45_folds_goal_to_identity` and
/// `test_migration_49_pages_changelog_column` are the two that prove it). So
/// both halves are asserted at the SAME version, differing only in whether
/// `memories` carries `space`.
#[tokio::test]
async fn reconstruction_refuses_a_pre_rename_shape_and_serves_a_rewound_one() {
    let dir = tempdir().unwrap();
    const STAMPED: i64 = 44;

    let fixture = |name: &'static str, space_column: &'static str| {
        let path = dir.path().join(name);
        async move {
            let raw = libsql::Builder::new_local(path.to_string_lossy().to_string())
                .build()
                .await
                .unwrap();
            let conn = raw.connect().unwrap();
            conn.execute(
                &format!("CREATE TABLE memories (id TEXT PRIMARY KEY, {space_column} TEXT)"),
                (),
            )
            .await
            .unwrap();
            conn.execute(&format!("PRAGMA user_version = {STAMPED}"), ())
                .await
                .unwrap();
            (raw, conn)
        }
    };

    // Genuinely mid-chain: `memories` has not been renamed yet, so this store
    // predates migration 50 and its `entities` shape cannot be rebuilt.
    let (_pre_raw, pre_rename) = fixture("pre_rename.db", "domain").await;
    let refusal = ensure_legacy_entities_table(&pre_rename)
        .await
        .expect_err("a `domain`-shaped store must refuse, not synthesize a `space`-shaped table")
        .to_string();
    assert!(
        refusal.contains("corrupt"),
        "the refusal must name the state: {refusal}"
    );
    assert!(
        !legacy_table_present(&pre_rename, "entities").await.unwrap(),
        "refusing means building nothing"
    );

    // Same stamped version, post-rename shape: a rewound fixture. It gets the
    // version-122 shape back, which is what it was an instant ago.
    let (_post_raw, rewound) = fixture("rewound.db", "space").await;
    ensure_legacy_entities_table(&rewound)
        .await
        .expect("a version-122-shaped store gets the version-122 shape, whatever it stamped");
    let mut rows = rewound
        .query(
            "SELECT COUNT(*) FROM pragma_table_info('entities') WHERE name = 'space'",
            (),
        )
        .await
        .unwrap();
    assert_eq!(
        rows.next().await.unwrap().unwrap().get::<i64>(0).unwrap(),
        1,
        "the reconstructed table must carry `space`, which is what makes it the post-50 shape"
    );
}
